def _project_scope_pair(raw_pair: Any) -> str:
    raw = str(raw_pair or "").strip().upper()
    compact = raw.replace(" ", "").replace("-", "").replace("_", "").replace(":", "")
    if compact in {"NAS100", "NAS100USD", "NASDAQ", "NASDAQ100"} or "NAS100" in compact or "NASDAQ" in compact:
        return "NAS100"
    if compact in {"US500", "SPX500", "SP500", "SPX", "SPY", "US500USD", "SPX500USD"} or "US500" in compact or "SPX500" in compact or "SP500" in compact:
        return "US500"
    if compact in {"XAU", "XAUUSD", "GOLD"} or "XAUUSD" in compact:
        return "XAUUSD"
    if compact in {"XAG", "XAGUSD", "SILVER"} or "XAGUSD" in compact:
        return "XAGUSD"
    return raw

def project_scope_accepts_pair(raw_pair: Any) -> bool:
    return _project_scope_pair(raw_pair) in PROJECT_SCOPE_ALLOWED_PAIRS
