# ============================================================
# POSTGRESQL DUAL-ENGINE SIDECAR FOUNDATION (v10.0.99)
# ============================================================
# Safety rule:
# - SQLite remains the default and the current live service can run this build
#   unchanged with DATABASE_ENGINE=sqlite.
# - PostgreSQL runtime is deliberately opt-in and intended for the separate
#   sidecar/test Railway service first.
# - DATABASE_ENGINE=postgres alone is NOT enough: POSTGRES_RUNTIME_ENABLED=true
#   is also required. When POSTGRES_REQUIRE_TEST_MODE=true (default), broker
#   execution must be disabled/read-only/killed before a Postgres connection is
#   allowed. This prevents an accidental live cutover while compatibility is
#   still being proved.
DATABASE_ENGINE = os.getenv("DATABASE_ENGINE", "sqlite").strip().lower()
POSTGRES_SIDECAR_DATABASE_URL = os.getenv("POSTGRES_SIDECAR_DATABASE_URL", os.getenv("DATABASE_URL", "")).strip()
POSTGRES_READINESS_CONNECT_TEST = os.getenv("POSTGRES_READINESS_CONNECT_TEST", "false").strip().lower() == "true"
POSTGRES_REQUIRE_TEST_MODE = os.getenv("POSTGRES_REQUIRE_TEST_MODE", "true").strip().lower() == "true"
POSTGRES_RUNTIME_ENABLED = os.getenv("POSTGRES_RUNTIME_ENABLED", "false").strip().lower() == "true"
POSTGRES_CONNECT_TIMEOUT_SECONDS = max(2, min(int(float(os.getenv("POSTGRES_CONNECT_TIMEOUT_SECONDS", "10"))), 60))

def _postgres_driver_status() -> Dict[str, Any]:
    """Return optional Postgres driver status without importing at startup hard.

    Railway may not have psycopg installed yet. This function keeps the live
    SQLite bot unaffected while letting a sidecar service report what is missing.
    """
    status = {"psycopg3_available": False, "psycopg2_available": False, "preferred": None}
    try:
        import psycopg  # type: ignore  # noqa: F401
        status["psycopg3_available"] = True
        status["preferred"] = "psycopg"
        return status
    except Exception as e:
        status["psycopg3_error"] = str(e)
    try:
        import psycopg2  # type: ignore  # noqa: F401
        status["psycopg2_available"] = True
        status["preferred"] = "psycopg2"
    except Exception as e:
        status["psycopg2_error"] = str(e)
    return status


def _postgres_connectivity_check() -> Dict[str, Any]:
    """Optional sidecar-only Postgres connectivity check.

    This never runs unless POSTGRES_READINESS_CONNECT_TEST=true. It should be
    used on a separate Railway test service, not the live trading service.
    """
    driver = _postgres_driver_status()
    if not POSTGRES_SIDECAR_DATABASE_URL:
        return {"ok": False, "skipped": True, "reason": "POSTGRES_SIDECAR_DATABASE_URL/DATABASE_URL not set", "driver": driver}
    if not POSTGRES_READINESS_CONNECT_TEST:
        return {"ok": None, "skipped": True, "reason": "POSTGRES_READINESS_CONNECT_TEST=false", "driver": driver}
    if driver.get("preferred") == "psycopg":
        try:
            import psycopg  # type: ignore
            with psycopg.connect(POSTGRES_SIDECAR_DATABASE_URL, connect_timeout=5) as conn:
                with conn.cursor() as cur:
                    cur.execute("SELECT 1")
                    val = cur.fetchone()[0]
            return {"ok": val == 1, "driver": driver}
        except Exception as e:
            return {"ok": False, "error": str(e), "driver": driver}
    if driver.get("preferred") == "psycopg2":
        try:
            import psycopg2  # type: ignore
            conn = psycopg2.connect(POSTGRES_SIDECAR_DATABASE_URL, connect_timeout=5)
            try:
                cur = conn.cursor()
                cur.execute("SELECT 1")
                val = cur.fetchone()[0]
                cur.close()
            finally:
                conn.close()
            return {"ok": val == 1, "driver": driver}
        except Exception as e:
            return {"ok": False, "error": str(e), "driver": driver}
    return {"ok": False, "error": "No Postgres driver installed. Add psycopg[binary] or psycopg2-binary in the sidecar requirements.", "driver": driver}


def _is_postgres_engine() -> bool:
    return DATABASE_ENGINE in {"postgres", "postgresql", "pg"}


def _postgres_test_mode_safety_from_env() -> Dict[str, Any]:
    broker_execution_enabled = os.getenv("BROKER_EXECUTION_ENABLED", "false").strip().lower() == "true"
    broker_read_only = os.getenv("BROKER_READ_ONLY", "true").strip().lower() != "false"
    broker_kill_switch = os.getenv("BROKER_KILL_SWITCH", "true").strip().lower() != "false"
    oanda_enabled = os.getenv("OANDA_ENABLED", "false").strip().lower() == "true"
    safe = (
        not broker_execution_enabled
        and (broker_read_only or broker_kill_switch or not oanda_enabled)
    )
    return {
        "safe_for_sidecar_runtime": safe,
        "broker_execution_enabled": broker_execution_enabled,
        "broker_read_only": broker_read_only,
        "broker_kill_switch": broker_kill_switch,
        "oanda_enabled": oanda_enabled,
    }


def database_runtime_status() -> Dict[str, Any]:
    pg_safety = _postgres_test_mode_safety_from_env()
    return {
        "active_database_engine": "postgres" if _is_postgres_engine() else "sqlite",
        "database_engine_raw": DATABASE_ENGINE,
        "live_sqlite_db_path": DB_PATH,
        "postgres_sidecar_configured": bool(POSTGRES_SIDECAR_DATABASE_URL),
        "postgres_runtime_enabled": POSTGRES_RUNTIME_ENABLED,
        "postgres_require_test_mode": POSTGRES_REQUIRE_TEST_MODE,
        "postgres_connect_test_enabled": POSTGRES_READINESS_CONNECT_TEST,
        "postgres_driver": _postgres_driver_status(),
        "postgres_runtime_safety": pg_safety,
        "dual_engine_build": True,
        "safety_note": (
            "SQLite remains the default. PostgreSQL requires explicit runtime opt-in and, by default, sidecar-safe broker settings."
        ),
    }


class _CompatStaticCursor:
    """Small cursor-like object used for Postgres no-op compatibility statements."""

    def __init__(self, rows: Optional[List[Dict[str, Any]]] = None, lastrowid: Optional[int] = None):
        self._rows = list(rows or [])
        self._idx = 0
        self.lastrowid = lastrowid

    def fetchone(self):
        if self._idx >= len(self._rows):
            return None
        row = self._rows[self._idx]
        self._idx += 1
        return row

    def fetchall(self):
        if self._idx >= len(self._rows):
            return []
        rows = self._rows[self._idx:]
        self._idx = len(self._rows)
        return rows


_POSTGRES_REPLACE_CONFLICT_KEYS = {
    "closed_trades": ["trade_id"],
    "active_basket_cycles": ["asset"],
    "active_family_basket_cycles": ["family"],
}


def _replace_qmark_placeholders(sql: str) -> str:
    """Convert SQLite qmark placeholders to psycopg %s without touching quoted text."""
    out: List[str] = []
    i = 0
    in_single = False
    in_double = False
    while i < len(sql):
        ch = sql[i]
        if ch == "'" and not in_double:
            # SQL escapes a single quote by doubling it.
            if in_single and i + 1 < len(sql) and sql[i + 1] == "'":
                out.append("''")
                i += 2
                continue
            in_single = not in_single
            out.append(ch)
            i += 1
            continue
        if ch == '"' and not in_single:
            if in_double and i + 1 < len(sql) and sql[i + 1] == '"':
                out.append('""')
                i += 2
                continue
            in_double = not in_double
            out.append(ch)
            i += 1
            continue
        if ch == "?" and not in_single and not in_double:
            out.append("%s")
        else:
            out.append(ch)
        i += 1
    return "".join(out)


def _escape_literal_percents_for_pg(sql: str) -> str:
    """Escape literal % characters when psycopg parameters are present."""
    out: List[str] = []
    i = 0
    while i < len(sql):
        ch = sql[i]
        if ch != "%":
            out.append(ch)
            i += 1
            continue
        nxt = sql[i + 1] if i + 1 < len(sql) else ""
        if nxt in {"s", "%"}:
            out.append("%" + nxt)
            i += 2
        else:
            out.append("%%")
            i += 1
    return "".join(out)


def _postgres_transform_ddl(sql: str) -> str:
    out = sql
    out = re.sub(r"\bINTEGER\s+PRIMARY\s+KEY\s+AUTOINCREMENT\b", "BIGSERIAL PRIMARY KEY", out, flags=re.IGNORECASE)
    out = re.sub(r"\bAUTOINCREMENT\b", "", out, flags=re.IGNORECASE)
    # SQLite REAL is an 8-byte floating value; preserve that behaviour in Postgres.
    out = re.sub(r"\bREAL\b", "DOUBLE PRECISION", out, flags=re.IGNORECASE)
    out = re.sub(r"\bBLOB\b", "BYTEA", out, flags=re.IGNORECASE)
    return out


def _postgres_transform_insert_or_replace(sql: str) -> str:
    """Translate the small set of SQLite INSERT OR REPLACE statements to UPSERT."""
    m = re.match(
        r"\s*INSERT\s+OR\s+REPLACE\s+INTO\s+([\w\"]+)\s*\((.*?)\)\s*VALUES\s*\((.*?)\)\s*;?\s*$",
        sql,
        flags=re.IGNORECASE | re.DOTALL,
    )
    if not m:
        return sql
    raw_table = m.group(1)
    table = raw_table.strip('"').lower()
    conflict_cols = _POSTGRES_REPLACE_CONFLICT_KEYS.get(table)
    if not conflict_cols:
        raise RuntimeError(f"Postgres compatibility: no conflict key configured for INSERT OR REPLACE table {table!r}")
    columns = [c.strip() for c in m.group(2).split(",") if c.strip()]
    values_sql = m.group(3)
    conflict_sql = ", ".join(f'"{c}"' for c in conflict_cols)
    conflict_names = {c.lower() for c in conflict_cols}
    update_cols = [c for c in columns if c.strip('"').lower() not in conflict_names]
    update_sql = ", ".join(f"{c} = EXCLUDED.{c}" for c in update_cols)
    return (
        f"INSERT INTO {raw_table} ({', '.join(columns)}) VALUES ({values_sql}) "
        f"ON CONFLICT ({conflict_sql}) DO UPDATE SET {update_sql}"
    )


def _postgres_prepare_sql(sql: str, params: Optional[Tuple[Any, ...]] = None) -> Tuple[Optional[str], Tuple[Any, ...], Optional[_CompatStaticCursor]]:
    """Translate SQLite-flavoured SQL used by the app into Postgres-compatible SQL."""
    original = str(sql)
    stripped = original.strip()
    params_tuple: Tuple[Any, ...] = tuple(params or ())
    upper = stripped.upper()

    # SQLite sequence maintenance is only cosmetic after DELETE. Postgres sequence
    # alignment is handled by the migration/import script, not by routine app resets.
    if upper.startswith("DELETE FROM SQLITE_SEQUENCE"):
        return None, (), _CompatStaticCursor([])

    # PRAGMA table_info(table) compatibility.
    m = re.match(r"^PRAGMA\s+TABLE_INFO\(([^)]+)\)\s*;?$", stripped, flags=re.IGNORECASE)
    if m:
        table = m.group(1).strip().strip('"')
        q = """
            SELECT
                c.ordinal_position - 1 AS cid,
                c.column_name AS name,
                c.data_type AS type,
                CASE WHEN c.is_nullable = 'NO' THEN 1 ELSE 0 END AS notnull,
                c.column_default AS dflt_value,
                CASE WHEN pk.column_name IS NOT NULL THEN 1 ELSE 0 END AS pk
            FROM information_schema.columns c
            LEFT JOIN (
                SELECT kcu.table_schema, kcu.table_name, kcu.column_name
                FROM information_schema.table_constraints tc
                JOIN information_schema.key_column_usage kcu
                  ON tc.constraint_name = kcu.constraint_name
                 AND tc.table_schema = kcu.table_schema
                WHERE tc.constraint_type = 'PRIMARY KEY'
            ) pk
              ON pk.table_schema = c.table_schema
             AND pk.table_name = c.table_name
             AND pk.column_name = c.column_name
            WHERE c.table_schema = current_schema()
              AND c.table_name = %s
            ORDER BY c.ordinal_position
        """
        return q, (table,), None

    # PRAGMA index_list(table) compatibility for migration inventory endpoints.
    m = re.match(r"^PRAGMA\s+INDEX_LIST\(([^)]+)\)\s*;?$", stripped, flags=re.IGNORECASE)
    if m:
        table = m.group(1).strip().strip('"')
        q = """
            SELECT
                indexname AS name,
                CASE WHEN indexdef ILIKE 'CREATE UNIQUE INDEX%%' THEN 1 ELSE 0 END AS "unique",
                'c' AS origin
            FROM pg_indexes
            WHERE schemaname = current_schema()
              AND tablename = %s
            ORDER BY indexname
        """
        return q, (table,), None

    # PRAGMA index_info(index) compatibility.
    m = re.match(r"^PRAGMA\s+INDEX_INFO\(([^)]+)\)\s*;?$", stripped, flags=re.IGNORECASE)
    if m:
        index_name = m.group(1).strip().strip('"')
        q = """
            SELECT a.attname AS name
            FROM pg_class t
            JOIN pg_index ix ON t.oid = ix.indrelid
            JOIN pg_class i ON i.oid = ix.indexrelid
            JOIN pg_attribute a ON a.attrelid = t.oid AND a.attnum = ANY(ix.indkey)
            WHERE i.relname = %s
            ORDER BY array_position(ix.indkey, a.attnum)
        """
        return q, (index_name,), None

    # sqlite_master compatibility for the two inventory/reset query shapes used here.
    if "FROM SQLITE_MASTER" in upper:
        if re.search(r"SELECT\s+NAME\s*,\s*SQL", upper):
            q = """
                SELECT tablename AS name, NULL::text AS sql
                FROM pg_tables
                WHERE schemaname = current_schema()
                ORDER BY tablename
            """
        else:
            q = """
                SELECT tablename AS name
                FROM pg_tables
                WHERE schemaname = current_schema()
                ORDER BY tablename
            """
        return q, (), None

    transformed = stripped
    if re.match(r"^(CREATE\s+TABLE|ALTER\s+TABLE)", transformed, flags=re.IGNORECASE):
        transformed = _postgres_transform_ddl(transformed)

    if re.match(r"^INSERT\s+OR\s+REPLACE", transformed, flags=re.IGNORECASE):
        transformed = _postgres_transform_insert_or_replace(transformed)

    if re.match(r"^INSERT\s+OR\s+IGNORE", transformed, flags=re.IGNORECASE):
        transformed = re.sub(r"^INSERT\s+OR\s+IGNORE\s+INTO", "INSERT INTO", transformed, count=1, flags=re.IGNORECASE)
        transformed = transformed.rstrip().rstrip(";") + " ON CONFLICT DO NOTHING"

    transformed = _replace_qmark_placeholders(transformed)
    if params_tuple:
        transformed = _escape_literal_percents_for_pg(transformed)
    return transformed, params_tuple, None


_POSTGRES_LEGACY_RESULT_KEY_ALIASES = {
    # The live SQLite app historically exposes these mixed-case identifiers in
    # sqlite3.Row objects. PostgreSQL folds unquoted identifiers to lowercase,
    # so the sidecar schema is normalised to lowercase for SQL compatibility.
    # Add result aliases so legacy Python code can continue to read either form.
    "last_basket_r": "last_basket_R",
    "last_family_r": "last_family_R",
    "open_basket_r": "open_basket_R",
}


def _postgres_wrap_result_row(row: Any) -> Any:
    """Return a dict row with legacy SQLite key aliases preserved.

    SQL identifiers must remain lowercase on PostgreSQL so unquoted app SQL works.
    But sqlite3.Row historically exposed mixed-case names such as ``open_basket_R``.
    Several dashboard/research paths still access those exact keys, including after
    ``dict(row)`` conversion. Injecting aliases at the cursor boundary preserves the
    SQLite-facing Python contract without changing stored schema or strategy logic.
    """
    if row is None or not hasattr(row, "keys"):
        return row
    wrapped = dict(row)
    lower_lookup = {str(k).lower(): k for k in list(wrapped.keys())}
    for lower_key, legacy_key in _POSTGRES_LEGACY_RESULT_KEY_ALIASES.items():
        actual_key = lower_lookup.get(lower_key)
        if actual_key is not None and legacy_key not in wrapped:
            wrapped[legacy_key] = wrapped[actual_key]
    return wrapped


class _PostgresCompatCursor:
    """Cursor proxy that preserves the legacy sqlite3.Row key contract."""

    def __init__(self, raw_cursor: Any):
        self._cursor = raw_cursor

    def fetchone(self):
        return _postgres_wrap_result_row(self._cursor.fetchone())

    def fetchall(self):
        return [_postgres_wrap_result_row(row) for row in self._cursor.fetchall()]

    def fetchmany(self, size: Optional[int] = None):
        rows = self._cursor.fetchmany(size) if size is not None else self._cursor.fetchmany()
        return [_postgres_wrap_result_row(row) for row in rows]

    def __iter__(self):
        for row in self._cursor:
            yield _postgres_wrap_result_row(row)

    def __getattr__(self, name: str):
        return getattr(self._cursor, name)


class _PostgresCompatConnection:
    """Small DB-API compatibility wrapper so existing SQLite-style app code can run on Postgres."""

    def __init__(self, raw_conn: Any, driver_name: str):
        self._conn = raw_conn
        self.driver_name = driver_name

    def execute(self, sql: str, params: Optional[Tuple[Any, ...]] = None):
        translated, translated_params, static_cursor = _postgres_prepare_sql(sql, params)
        if static_cursor is not None:
            return static_cursor
        if translated is None:
            return _CompatStaticCursor([])

        if self.driver_name == "psycopg":
            from psycopg.rows import dict_row  # type: ignore
            cur = self._conn.cursor(row_factory=dict_row)
        else:
            from psycopg2.extras import RealDictCursor  # type: ignore
            cur = self._conn.cursor(cursor_factory=RealDictCursor)
        cur.execute(translated, translated_params)
        return _PostgresCompatCursor(cur)

    def commit(self) -> None:
        self._conn.commit()

    def rollback(self) -> None:
        self._conn.rollback()

    def close(self) -> None:
        self._conn.close()

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc, tb):
        try:
            if exc_type is None:
                self._conn.commit()
            else:
                self._conn.rollback()
        finally:
            self._conn.close()
        return False


def _open_postgres_connection() -> _PostgresCompatConnection:
    if not POSTGRES_RUNTIME_ENABLED:
        raise RuntimeError(
            "DATABASE_ENGINE=postgres requested but POSTGRES_RUNTIME_ENABLED is false. "
            "Enable it only on the separate sidecar/test service first."
        )
    if not POSTGRES_SIDECAR_DATABASE_URL:
        raise RuntimeError("DATABASE_ENGINE=postgres requested but DATABASE_URL/POSTGRES_SIDECAR_DATABASE_URL is missing.")
    safety = _postgres_test_mode_safety_from_env()
    if POSTGRES_REQUIRE_TEST_MODE and not safety.get("safe_for_sidecar_runtime"):
        raise RuntimeError(
            "Postgres runtime blocked by POSTGRES_REQUIRE_TEST_MODE=true because broker execution settings are not sidecar-safe. "
            "Use BROKER_EXECUTION_ENABLED=false, BROKER_READ_ONLY=true and/or BROKER_KILL_SWITCH=true on the Postgres test service."
        )
    driver = _postgres_driver_status()
    if driver.get("preferred") == "psycopg":
        import psycopg  # type: ignore
        raw = psycopg.connect(
            POSTGRES_SIDECAR_DATABASE_URL,
            connect_timeout=POSTGRES_CONNECT_TIMEOUT_SECONDS,
        )
        return _PostgresCompatConnection(raw, "psycopg")
    if driver.get("preferred") == "psycopg2":
        import psycopg2  # type: ignore
        raw = psycopg2.connect(
            POSTGRES_SIDECAR_DATABASE_URL,
            connect_timeout=POSTGRES_CONNECT_TIMEOUT_SECONDS,
        )
        return _PostgresCompatConnection(raw, "psycopg2")
    raise RuntimeError("No Postgres driver installed. Add psycopg[binary] to the sidecar requirements.")


def db_insert_returning_id(conn: Any, sql: str, params: Tuple[Any, ...], id_column: str = "id") -> int:
    """Insert a row and return its generated id on either SQLite or Postgres."""
    if _is_postgres_engine():
        clean = sql.strip().rstrip(";") + f' RETURNING "{id_column}"'
        row = conn.execute(clean, params).fetchone()
        if not row:
            raise RuntimeError("Postgres INSERT ... RETURNING did not return an id")
        return int(row[id_column])
    cur = conn.execute(sql, params)
    return int(cur.lastrowid)


def is_transient_database_error(exc: Exception) -> bool:
    """Cross-engine retry check for SQLite locks and transient Postgres connection/serialization failures."""
    msg = str(exc).lower()
    if "database is locked" in msg or "database table is locked" in msg:
        return True
    if any(term in msg for term in [
        "could not serialize access", "deadlock detected", "connection reset",
        "server closed the connection", "terminating connection", "timeout expired",
    ]):
        return True
    return False


# ============================================================
# POSTGRESQL SIDECAR SCHEMA INVENTORY (v10.0.72)
# ============================================================
# These helpers are read-only and intended for manual sidecar migration checks.
# They do not change the live SQLite database and they do not enable Postgres
# for trading. They help us inventory the current SQLite schema before building
# a proper Postgres copy/import path.

def _sqlite_db_file_info() -> Dict[str, Any]:
    path = Path(DB_PATH)
    info: Dict[str, Any] = {"path": DB_PATH, "exists": path.exists()}
    if path.exists():
        try:
            info["size_bytes"] = path.stat().st_size
            info["size_mb"] = round(path.stat().st_size / (1024 * 1024), 3)
            info["modified_utc"] = datetime.fromtimestamp(path.stat().st_mtime, tz=timezone.utc).isoformat()
        except Exception as e:
            info["stat_error"] = str(e)
    return info


def _sqlite_table_inventory(include_row_counts: bool = True) -> List[Dict[str, Any]]:
    """Return SQLite table/index inventory for migration planning.

    This is deliberately read-only apart from the existing get_conn PRAGMAs. Use
    manually via /db/sqlite-inventory; it is not called by the dashboard.
    """
    inventory: List[Dict[str, Any]] = []
    with get_conn() as conn:
        tables = conn.execute("""
            SELECT name, sql
            FROM sqlite_master
            WHERE type='table'
              AND name NOT LIKE 'sqlite_%'
            ORDER BY name
        """).fetchall()
        for t in tables:
            name = t["name"]
            row: Dict[str, Any] = {"table": name, "create_sql": t["sql"]}
            try:
                cols = conn.execute(f"PRAGMA table_info({name})").fetchall()
                row["columns"] = [
                    {
                        "cid": c["cid"],
                        "name": c["name"],
                        "type": c["type"],
                        "notnull": bool(c["notnull"]),
                        "default": c["dflt_value"],
                        "pk": bool(c["pk"]),
                    }
                    for c in cols
                ]
            except Exception as e:
                row["columns_error"] = str(e)
            try:
                idxs = conn.execute(f"PRAGMA index_list({name})").fetchall()
                indexes = []
                for idx in idxs:
                    idx_name = idx["name"]
                    idx_info = {"name": idx_name, "unique": bool(idx["unique"]), "origin": idx["origin"]}
                    try:
                        idx_cols = conn.execute(f"PRAGMA index_info({idx_name})").fetchall()
                        idx_info["columns"] = [ic["name"] for ic in idx_cols]
                    except Exception as e:
                        idx_info["columns_error"] = str(e)
                    indexes.append(idx_info)
                row["indexes"] = indexes
            except Exception as e:
                row["indexes_error"] = str(e)
            if include_row_counts:
                try:
                    # Table names are internal sqlite_master values; quote safely.
                    safe_name = str(name).replace('"', '""')
                    row["row_count"] = int(conn.execute(f'SELECT COUNT(*) AS c FROM "{safe_name}"').fetchone()["c"])
                except Exception as e:
                    row["row_count_error"] = str(e)
            inventory.append(row)
    return inventory


def _sqlite_type_to_postgres(sqlite_type: str, is_pk: bool = False) -> str:
    raw = (sqlite_type or "").strip().upper()
    if is_pk and ("INT" in raw or raw == ""):
        return "BIGINT"
    if "INT" in raw:
        return "BIGINT"
    if any(x in raw for x in ["REAL", "FLOA", "DOUB"]):
        return "DOUBLE PRECISION"
    if "NUM" in raw or "DEC" in raw:
        return "NUMERIC"
    if "BOOL" in raw:
        return "BOOLEAN"
    if "BLOB" in raw:
        return "BYTEA"
    if "DATE" in raw or "TIME" in raw:
        # Most timestamps are currently ISO text. Keep as TEXT in the first copy
        # to avoid damaging data. Later we can normalise selected columns.
        return "TEXT"
    return "TEXT"


def _postgres_ddl_preview_from_inventory(inventory: List[Dict[str, Any]]) -> Dict[str, Any]:
    """Generate a conservative Postgres DDL preview.

    This is not intended for blind live execution. It gives us a side-by-side
    checklist of tables/columns that need proper migration testing.
    """
    ddl: List[str] = []
    warnings: List[str] = []
    for table in inventory:
        name = table.get("table", "")
        cols = table.get("columns") or []
        if not name or not cols:
            warnings.append(f"Skipping {name or '<unknown>'}: no columns found")
            continue
        col_lines = []
        pk_cols = [c["name"] for c in cols if c.get("pk")]
        for c in cols:
            col_name = str(c["name"]).replace('"', '""')
            pg_type = _sqlite_type_to_postgres(str(c.get("type") or ""), bool(c.get("pk")))
            line = f'    "{col_name}" {pg_type}'
            if c.get("notnull"):
                line += " NOT NULL"
            if c.get("default") is not None:
                # Defaults differ across engines. Flag rather than blindly copying.
                warnings.append(f"{name}.{c['name']} has SQLite default {c.get('default')!r}; review before Postgres migration")
            col_lines.append(line)
        if pk_cols:
            pk = ", ".join(f'"{str(x).replace(chr(34), chr(34)+chr(34))}"' for x in pk_cols)
            col_lines.append(f"    PRIMARY KEY ({pk})")
        table_name = str(name).replace('"', '""')
        ddl.append(f'CREATE TABLE IF NOT EXISTS "{table_name}" (\n' + ",\n".join(col_lines) + "\n);")
        for idx in table.get("indexes") or []:
            idx_cols = idx.get("columns") or []
            if not idx_cols:
                continue
            idx_name = str(idx.get("name") or f"idx_{name}_{'_'.join(idx_cols)}").replace('"', '""')
            idx_table = table_name
            idx_col_sql = ", ".join(f'"{str(c).replace(chr(34), chr(34)+chr(34))}"' for c in idx_cols)
            unique = "UNIQUE " if idx.get("unique") else ""
            ddl.append(f'CREATE {unique}INDEX IF NOT EXISTS "{idx_name}" ON "{idx_table}" ({idx_col_sql});')
    return {"ddl_preview": ddl, "warnings": warnings}


def _postgres_sidecar_safety_status() -> Dict[str, Any]:
    """Report whether the current service looks safe for sidecar testing."""
    checks = {
        "broker_execution_enabled": env_bool("BROKER_EXECUTION_ENABLED", False),
        "broker_read_only": env_bool("BROKER_READ_ONLY", False),
        "broker_kill_switch": env_bool("BROKER_KILL_SWITCH", False),
        "oanda_enabled": env_bool("OANDA_ENABLED", False),
        "database_engine": DATABASE_ENGINE,
    }
    # Safe sidecar testing means no real broker writes can happen. The live
    # service will naturally fail this because it is allowed to trade; that's OK.
    checks["safe_for_postgres_sidecar_execution_tests"] = (
        not checks["broker_execution_enabled"]
        and (checks["broker_read_only"] or checks["broker_kill_switch"] or not checks["oanda_enabled"])
    )
    checks["note"] = (
        "Live service does not need to pass this. A separate Postgres test service should."
    )
    return checks

def env_bool(name: str, default: bool = False) -> bool:
    """Read a boolean Railway env var safely.

    Accepts true/false, 1/0, yes/no, on/off. Keeps dashboard
    optional maintenance flags from crashing if the helper is missing.
    """
    val = os.getenv(name)
    if val is None:
        return default
    val = str(val).strip().lower()
    if val in {"1", "true", "yes", "y", "on"}:
        return True
    if val in {"0", "false", "no", "n", "off"}:
        return False
    return default

