# ============================================================
# GLOBAL RESEARCH ROW LIMITS (Postgres runtime)
# ============================================================
# The old live SQLite build used smaller derived-research caps to protect the
# Railway volume and dashboard. Now that live is on Postgres, derived research
# exports can safely include much larger result sets while still keeping a hard
# guardrail against accidentally requesting unlimited rows from the dashboard.
#
# Defaults:
# - dashboard/detail views stay moderate so /dashboard and JSON endpoints do not
#   generate huge in-memory pages.
# - individual research CSV exports default to 25k rows, but can be raised with
#   ?limit=100000 or Railway env vars when needed.
# - /export/all.zip is intentionally capped lower than individual exports; a full
#   zip containing every raw table + every derived research view can otherwise
#   exceed Railway memory/response limits and crash.
#
# Override in Railway if needed:
# - RESEARCH_ROW_DEFAULT_LIMIT
# - RESEARCH_ROW_EXPORT_LIMIT
# - RESEARCH_ROW_DASHBOARD_LIMIT
# - RESEARCH_ROW_HARD_LIMIT
# - EXPORT_TABLE_ROW_LIMIT
# - EXPORT_ALL_TABLE_ROW_LIMIT
# - EXPORT_ALL_DERIVED_ROW_LIMIT
RESEARCH_ROW_HARD_LIMIT = max(100000, min(int(float(os.getenv("RESEARCH_ROW_HARD_LIMIT", "250000"))), 1000000))
RESEARCH_ROW_DEFAULT_LIMIT = max(1000, min(int(float(os.getenv("RESEARCH_ROW_DEFAULT_LIMIT", "25000"))), RESEARCH_ROW_HARD_LIMIT))
RESEARCH_ROW_EXPORT_LIMIT = max(5000, min(int(float(os.getenv("RESEARCH_ROW_EXPORT_LIMIT", str(RESEARCH_ROW_DEFAULT_LIMIT)))), RESEARCH_ROW_HARD_LIMIT))
RESEARCH_ROW_DASHBOARD_LIMIT = max(1500, min(int(float(os.getenv("RESEARCH_ROW_DASHBOARD_LIMIT", "5000"))), RESEARCH_ROW_HARD_LIMIT))
RESEARCH_DETAIL_SAMPLE_LIMIT = max(200, min(int(float(os.getenv("RESEARCH_DETAIL_SAMPLE_LIMIT", "5000"))), RESEARCH_ROW_HARD_LIMIT))
EXPORT_TABLE_ROW_LIMIT = max(1000, min(int(float(os.getenv("EXPORT_TABLE_ROW_LIMIT", "50000"))), RESEARCH_ROW_HARD_LIMIT))
EXPORT_ALL_TABLE_ROW_LIMIT = max(1000, min(int(float(os.getenv("EXPORT_ALL_TABLE_ROW_LIMIT", "15000"))), RESEARCH_ROW_HARD_LIMIT))
EXPORT_ALL_DERIVED_ROW_LIMIT = max(1000, min(int(float(os.getenv("EXPORT_ALL_DERIVED_ROW_LIMIT", "15000"))), RESEARCH_ROW_HARD_LIMIT))

