JUNE_FULL_DEMO_MIN_OPEN_TRADES_FOR_NORMAL_TRIM = int(float(os.getenv("JUNE_FULL_DEMO_MIN_OPEN_TRADES_FOR_NORMAL_TRIM", "25")))
JUNE_FULL_DEMO_MIN_OPEN_TRADES_FOR_FULL_BASKET_CLOSE = int(float(os.getenv("JUNE_FULL_DEMO_MIN_OPEN_TRADES_FOR_FULL_BASKET_CLOSE", "50")))
JUNE_FULL_DEMO_HEAVY_BASKET_OPEN_TRADES = int(float(os.getenv("JUNE_FULL_DEMO_HEAVY_BASKET_OPEN_TRADES", "100")))
# v10.0.24: staged entry-blocking guard.
# Young baskets should not be starved just because early floating P&L is red.
# Entry blocking now scales like close/trim defence: 1-9 broker-confirmed trades
# usually keep accepting true signals; 10-24 only block on severe damage; 25+
# can use normal pause/defence entry blocking.
JUNE_FULL_DEMO_MIN_OPEN_TRADES_FOR_ENTRY_BLOCK = int(float(os.getenv("JUNE_FULL_DEMO_MIN_OPEN_TRADES_FOR_ENTRY_BLOCK", "10")))
