# DATABASE
# ============================================================

def column_exists(conn: sqlite3.Connection, table: str, column: str) -> bool:
    rows = conn.execute(f"PRAGMA table_info({table})").fetchall()
    # PostgreSQL folds unquoted identifiers to lowercase. The legacy SQLite
    # schema contains a few mixed-case names such as open_basket_R, so compare
    # identifiers case-insensitively across engines.
    target = safe_str(column).lower()
    return target in {safe_str(r["name"]).lower() for r in rows}


def add_column_if_missing(conn: sqlite3.Connection, table: str, column: str, col_type: str) -> None:
    # PostgreSQL should use its native idempotent DDL as a second safety net.
    # This avoids DuplicateColumn when an existing mixed-case SQLite identifier
    # has already been normalised to lowercase by PostgreSQL.
    if _is_postgres_engine():
        conn.execute(f"ALTER TABLE {table} ADD COLUMN IF NOT EXISTS {column} {col_type}")
        return
    if not column_exists(conn, table, column):
        conn.execute(f"ALTER TABLE {table} ADD COLUMN {column} {col_type}")


