def build_metals_candidate_summary() -> Dict[str, Any]:
    rows = build_metals_research_outcomes(limit=RESEARCH_ROW_DASHBOARD_LIMIT, candidates_only=False)
    accepted = [r for r in rows if int(r.get("candidate") or 0) == 1]
    candidate_like = [r for r in rows if int(r.get("candidate_like") or 0) == 1]
    return {
        "all_rows": len(rows),
        "accepted_candidates": len(accepted),
        "candidate_like_rows": len(candidate_like),
        "accepted_by_asset": {a: sum(1 for r in accepted if safe_str(r.get("asset")).upper() == a) for a in sorted({safe_str(r.get("asset")).upper() for r in rows})},
        "candidate_like_by_asset": {a: sum(1 for r in candidate_like if safe_str(r.get("asset")).upper() == a) for a in sorted({safe_str(r.get("asset")).upper() for r in rows})},
    }


# ============================================================
# MULTI-CONTEXT RESEARCH OUTCOME HELPERS
# ============================================================

RESEARCH_CONTEXT_MILESTONES = [12, 24, 48, 72, 96]
# v10.0.82: raise the multi-context research dashboard/export cap.
# The old 10k default was close to being reached with 12 research assets x 4 context TF rows.
# Still capped to protect the live Railway SQLite dashboard from accidentally requesting unlimited rows.
RESEARCH_CONTEXT_DASHBOARD_LIMIT = max(1500, min(int(float(os.getenv("RESEARCH_CONTEXT_DASHBOARD_LIMIT", str(RESEARCH_ROW_DASHBOARD_LIMIT)))), RESEARCH_ROW_HARD_LIMIT))
RESEARCH_CONTEXT_DEFAULT_ASSETS = {
    "XAUUSD", "XAU", "XAGUSD", "XAG",
}

def research_context_assets() -> List[str]:
    env_assets = os.getenv("RESEARCH_CONTEXT_ASSETS", ",".join(sorted(RESEARCH_CONTEXT_DEFAULT_ASSETS)))
    return [x.strip().upper() for x in env_assets.split(",") if x.strip()]

def research_asset_label(asset: str) -> str:
    a = safe_str(asset).upper()
    labels = {
        "XAU": "XAU / Gold", "XAUUSD": "XAU / Gold",
        "XAG": "XAG / Silver", "XAGUSD": "XAG / Silver",
    }
    return labels.get(a, a)

def research_context_sl_pct(asset: str) -> float:
    a = safe_str(asset).upper()
    if a in {"XAU", "XAUUSD"}:
        return float(os.getenv("RESEARCH_XAU_SL_PCT", os.getenv("METALS_RESEARCH_XAU_SL_PCT", "2.21")))
    if a in {"XAG", "XAGUSD"}:
        return float(os.getenv("RESEARCH_XAG_SL_PCT", os.getenv("METALS_RESEARCH_XAG_SL_PCT", "5.24")))
    return float(os.getenv("RESEARCH_CONTEXT_DEFAULT_SL_PCT", "2.50"))

def _research_to_50risk(asset: str, return_pct_value: Any) -> Optional[float]:
    r = safe_float(return_pct_value)
    if r is None:
        return None
    sl = research_context_sl_pct(asset)
    return None if sl == 0 else r / sl * 50.0

def _research_context_variants(raw: Dict[str, Any]) -> List[Dict[str, Any]]:
    """Return only true multi-context research scenarios.

    The multi-context dashboard must not mix in legacy single-context XAU/XAG
    rows, otherwise the 8H metals line is inflated and not comparable with
    2H/4H/12H. A valid research alert carries a `contexts` list from the
    Research Multi-Context Snapshot Logger; each item is evaluated separately.
    """
    contexts = raw.get("contexts")
    if not isinstance(contexts, list):
        return []
    clean: List[Dict[str, Any]] = []
    for c in contexts:
        if not isinstance(c, dict):
            continue
        tf = safe_str(c.get("context_tf") or c.get("tf")).upper()
        if tf in {"2H", "4H", "8H", "12H"}:
            clean.append(c)
    return clean

def build_research_context_outcomes(limit: int = RESEARCH_ROW_DEFAULT_LIMIT, accepted_only: bool = False, candidate_like_only: bool = False) -> List[Dict[str, Any]]:
    init_db()
    # Postgres runtime: allow larger multi-context research windows while keeping a hard safety cap.
    limit = max(1, min(int(limit or RESEARCH_ROW_DEFAULT_LIMIT), RESEARCH_ROW_HARD_LIMIT))
    assets = research_context_assets()
    if not assets:
        return []
    placeholders = ",".join(["?"] * len(assets))
    with get_conn() as conn:
        rows = conn.execute(f"""
            SELECT id, received_at_utc, pair, timestamp_readable, exec_close, exec_high, exec_low,
                   forward_test_candidate, take_trade, raw_json
            FROM raw_signals
            WHERE UPPER(pair) IN ({placeholders})
            ORDER BY UPPER(pair) ASC, id ASC
        """, tuple(assets)).fetchall()
    by_pair: Dict[str, List[sqlite3.Row]] = {}
    for r in rows:
        by_pair.setdefault(safe_str(r["pair"]).upper(), []).append(r)
    out: List[Dict[str, Any]] = []
    for pair, items in by_pair.items():
        for idx, row in enumerate(items):
            raw = _raw_signal_json(row)
            entry = safe_float(row["exec_close"])
            quality = safe_str(raw.get("signal_quality", ""))
            for ctx in _research_context_variants(raw):
                ctx_tf = safe_str(ctx.get("context_tf") or ctx.get("tf") or "UNKNOWN").upper()
                cand = _raw_bool_value(ctx.get("forward_test_candidate"))
                trend_rule = _raw_bool_value(ctx.get("rule_trend_long_v1"))
                cont_rule = _raw_bool_value(ctx.get("rule_bull_continuation_v1"))
                # Context research must be judged per-context. Do not use the parent
                # row's take_trade/quality/root candidate here, because those are often
                # "any context true" flags and would make 2H/4H/8H/12H all look identical.
                take = _raw_bool_value(row["take_trade"])
                root_candidate = _raw_bool_value(row["forward_test_candidate"])
                is_candidate_like = cand or trend_rule or cont_rule
                if accepted_only and not cand:
                    continue
                if candidate_like_only and not is_candidate_like:
                    continue
                d: Dict[str, Any] = {
                    "scenario_id": f"{row['id']}_{ctx_tf}", "signal_id": row["id"], "asset": pair,
                    "asset_label": research_asset_label(pair), "context_tf": ctx_tf,
                    "candle_time": row["timestamp_readable"], "candle_time_display": display_candle_time(row["timestamp_readable"]),
                    "context_timestamp": ctx.get("context_timestamp", ""), "received_at_utc": row["received_at_utc"],
                    "candidate": 1 if cand else 0,
                    "candidate_like": 1 if is_candidate_like else 0,
                    "root_candidate_any_context": 1 if root_candidate else 0,
                    "root_take_trade_any_context": 1 if take else 0,
                    "score": raw.get("score_raw", ""),
                    "signal_side": raw.get("signal_side", ""), "signal_quality": quality,
                    "setup_type": raw.get("setup_type", ""), "d_bull": raw.get("d_bull", ""), "d_bear": raw.get("d_bear", ""),
                    "ctx_trend_state": ctx.get("ctx_trend_state", ""), "ctx_rsi": ctx.get("ctx_rsi", ""), "ctx_atr_pct": ctx.get("ctx_atr_pct", ""),
                    "rule_trend_long_v1": 1 if trend_rule else 0, "rule_bull_continuation_v1": 1 if cont_rule else 0,
                    "entry_close": entry, "placeholder_sl_pct": research_context_sl_pct(pair),
                }
                for m in RESEARCH_CONTEXT_MILESTONES:
                    for k in ("return", "pnl50", "mfe", "mae", "mfe50", "mae50"):
                        d[f"{k}_{m}h" + ("_pct" if k in {"return","mfe","mae"} else "")] = None
                    d[f"has_{m}h"] = 0
                    if entry is None or entry == 0:
                        continue
                    future = items[idx + 1: idx + m + 1]
                    if len(future) < m:
                        continue
                    target_close = safe_float(future[-1]["exec_close"])
                    highs = [safe_float(x["exec_high"]) for x in future]
                    lows = [safe_float(x["exec_low"]) for x in future]
                    highs = [x for x in highs if x is not None]
                    lows = [x for x in lows if x is not None]
                    if target_close is not None:
                        ret = (target_close / entry - 1.0) * 100.0
                        d[f"return_{m}h_pct"] = ret; d[f"pnl50_{m}h"] = _research_to_50risk(pair, ret)
                    if highs:
                        mfe = (max(highs) / entry - 1.0) * 100.0
                        d[f"mfe_{m}h_pct"] = mfe; d[f"mfe50_{m}h"] = _research_to_50risk(pair, mfe)
                    if lows:
                        mae = (min(lows) / entry - 1.0) * 100.0
                        d[f"mae_{m}h_pct"] = mae; d[f"mae50_{m}h"] = _research_to_50risk(pair, mae)
                    d[f"has_{m}h"] = 1
                out.append(d)
    out.sort(key=lambda x: int(x.get("signal_id") or 0), reverse=True)
    return out[:limit]

def summarise_research_context_outcomes(outcomes: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    rows: List[Dict[str, Any]] = []
    keys = sorted({(safe_str(o.get("asset")).upper(), safe_str(o.get("context_tf")).upper()) for o in outcomes if safe_str(o.get("asset"))})
    for asset, ctx_tf in keys:
        subset = [o for o in outcomes if safe_str(o.get("asset")).upper() == asset and safe_str(o.get("context_tf")).upper() == ctx_tf]
        s: Dict[str, Any] = {"asset": asset, "asset_label": research_asset_label(asset), "context_tf": ctx_tf, "rows": len(subset), "accepted_candidates": sum(1 for o in subset if int(o.get("candidate") or 0) == 1), "candidate_like_rows": sum(1 for o in subset if int(o.get("candidate_like") or 0) == 1), "placeholder_sl_pct": research_context_sl_pct(asset)}
        for m in RESEARCH_CONTEXT_MILESTONES:
            vals = [safe_float(o.get(f"return_{m}h_pct")) for o in subset if int(o.get(f"has_{m}h") or 0) == 1]
            mfes = [safe_float(o.get(f"mfe_{m}h_pct")) for o in subset if int(o.get(f"has_{m}h") or 0) == 1]
            maes = [safe_float(o.get(f"mae_{m}h_pct")) for o in subset if int(o.get(f"has_{m}h") or 0) == 1]
            vals = [v for v in vals if v is not None]; mfes = [v for v in mfes if v is not None]; maes = [v for v in maes if v is not None]
            s[f"n_{m}h"] = len(vals)
            s[f"avg_return_{m}h_pct"] = (sum(vals) / len(vals)) if vals else None
            s[f"win_rate_{m}h_pct"] = (sum(1 for v in vals if v > 0) / len(vals) * 100.0) if vals else None
            s[f"avg_mfe_{m}h_pct"] = (sum(mfes) / len(mfes)) if mfes else None
            s[f"avg_mae_{m}h_pct"] = (sum(maes) / len(maes)) if maes else None
            s[f"avg_pnl50_{m}h"] = _research_to_50risk(asset, s[f"avg_return_{m}h_pct"]) if s[f"avg_return_{m}h_pct"] is not None else None
        rows.append(s)
    return rows

def _research_context_summary_html(summary_rows: List[Dict[str, Any]], empty_label: str) -> str:
    html = ""
    for s in summary_rows or []:
        html += f"""<tr><td><strong>{esc(s.get('asset'))}</strong><div class="small muted">{esc(s.get('asset_label'))}</div></td><td><strong>{esc(s.get('context_tf'))}</strong></td><td>{esc(s.get('rows', 0))}</td><td>{esc(s.get('accepted_candidates', 0))}</td><td>{esc(s.get('candidate_like_rows', 0))}</td><td>{float(s.get('placeholder_sl_pct') or 0):.2f}%</td><td>{esc(s.get('n_12h', 0))}</td><td class="{pnl_class(s.get('avg_return_12h_pct'))}">{pct(s.get('avg_return_12h_pct') or 0)}</td><td class="{pnl_class(s.get('avg_pnl50_12h'))}">{money(s.get('avg_pnl50_12h') or 0)}</td><td>{esc(s.get('n_48h', 0))}</td><td class="{pnl_class(s.get('avg_return_48h_pct'))}">{pct(s.get('avg_return_48h_pct') or 0)}</td><td class="{pnl_class(s.get('avg_pnl50_48h'))}">{money(s.get('avg_pnl50_48h') or 0)}</td><td>{esc(s.get('n_72h', 0))}</td><td class="{pnl_class(s.get('avg_return_72h_pct'))}">{pct(s.get('avg_return_72h_pct') or 0)}</td><td class="{pnl_class(s.get('avg_pnl50_72h'))}">{money(s.get('avg_pnl50_72h') or 0)}</td><td>{esc(s.get('n_96h', 0))}</td><td class="{pnl_class(s.get('avg_return_96h_pct'))}">{pct(s.get('avg_return_96h_pct') or 0)}</td><td class="{pnl_class(s.get('avg_pnl50_96h'))}">{money(s.get('avg_pnl50_96h') or 0)}</td></tr>"""
    return html or f'<tr><td colspan="18">{esc(empty_label)}</td></tr>'

def _research_context_detail_html(rows: List[Dict[str, Any]], limit: int = 120) -> str:
    html = ""
    for o in (rows or [])[:limit]:
        cand = int(o.get("candidate") or 0) == 1
        row_class = "true" if cand else "false"
        html += f"""<tr><td>{esc(o.get('signal_id'))}</td><td><strong>{esc(o.get('asset'))}</strong></td><td>{esc(o.get('context_tf'))}</td><td>{esc(o.get('candle_time_display') or display_candle_time(o.get('candle_time')))}</td><td class="{row_class}"><strong>{'true' if cand else 'false'}</strong></td><td>{esc(o.get('score'))}</td><td>{esc(o.get('signal_quality'))}</td><td>{esc(o.get('setup_type'))}</td><td>{esc(o.get('ctx_trend_state'))}</td><td>{esc(o.get('ctx_rsi'))}</td><td>{esc(o.get('ctx_atr_pct'))}</td><td>{float(o.get('placeholder_sl_pct') or 0):.2f}%</td><td class="{pnl_class(o.get('return_12h_pct'))}">{pct(o.get('return_12h_pct') or 0) if o.get('has_12h') else 'pending'}</td><td class="{pnl_class(o.get('return_48h_pct'))}">{pct(o.get('return_48h_pct') or 0) if o.get('has_48h') else 'pending'}</td><td class="{pnl_class(o.get('mfe_48h_pct'))}">{pct(o.get('mfe_48h_pct') or 0) if o.get('has_48h') else 'pending'}</td><td class="{pnl_class(o.get('mae_48h_pct'))}">{pct(o.get('mae_48h_pct') or 0) if o.get('has_48h') else 'pending'}</td><td class="{pnl_class(o.get('return_96h_pct'))}">{pct(o.get('return_96h_pct') or 0) if o.get('has_96h') else 'pending'}</td></tr>"""
    return html

def dicts_to_csv(rows: List[Dict[str, Any]]) -> str:
    output = io.StringIO()
    if not rows:
        return ""
    fieldnames: List[str] = []
    for r in rows:
        for k in r.keys():
            if k not in fieldnames:
                fieldnames.append(k)
    writer = csv.DictWriter(output, fieldnames=fieldnames, extrasaction="ignore")
    writer.writeheader()
    for r in rows:
        writer.writerow(r)
    return output.getvalue()


def rows_to_csv(rows: List[Dict[str, Any]], fallback_fieldnames: Optional[List[str]] = None) -> str:
    """CSV helper for derived export rows.

    Kept global because several explicit export endpoints are registered after
    the generic /export/{file_key}.csv route. If those explicit routes are ever
    reached directly, they still need a working CSV writer.
    """
    output = io.StringIO()
    fieldnames: List[str] = []
    for r in rows or []:
        for k in dict(r).keys():
            if k not in fieldnames:
                fieldnames.append(k)
    if not fieldnames:
        fieldnames = list(fallback_fieldnames or [])
    writer = csv.DictWriter(output, fieldnames=fieldnames, extrasaction="ignore")
    writer.writeheader()
    for r in rows or []:
        writer.writerow(dict(r))
    return output.getvalue()


