def cross_index_solo_guard_status_snapshot() -> Dict[str, Any]:
    """Read-only current policy/decision snapshot for NAS100 and US500."""
    init_db()
    rows: List[Dict[str, Any]] = []
    with get_conn() as conn:
        for asset in ["NAS100", "US500"]:
            signal = conn.execute(f"""
                SELECT *
                FROM raw_signals
                WHERE UPPER(pair) = ?
                  AND {_cross_index_candidate_sql_where()}
                ORDER BY id DESC
                LIMIT 1
            """, (asset,)).fetchone()
            if signal:
                decision = cross_index_solo_entry_guard(conn, signal)
                decision["latest_candidate_raw_signal_id"] = int(signal["id"] or 0)
                decision["latest_candidate_received_at_utc"] = safe_str(signal["received_at_utc"])
            else:
                decision = {
                    "asset": asset,
                    "allow": True,
                    "enabled": bool(CROSS_INDEX_CONFIRMATION_ENABLED),
                    "mode": CROSS_INDEX_CONFIRMATION_MODE,
                    "reason": "no_production_candidate_found",
                    "current_active_asset_links": count_live_demo_active_broker_links_for_asset(conn, asset),
                    "unsupported_solo_count_before": 0,
                    "cap": int(CROSS_INDEX_UNSUPPORTED_SOLO_CAP),
                    "lookback_hours": float(CROSS_INDEX_CONFIRMATION_LOOKBACK_HOURS),
                }
            rows.append(decision)
    return {
        "status": "ok",
        "runtime_module": RUNTIME_MODULE,
        "enabled": bool(CROSS_INDEX_CONFIRMATION_ENABLED),
        "env_requested": bool(CROSS_INDEX_CONFIRMATION_ENV_REQUESTED),
        "mode": CROSS_INDEX_CONFIRMATION_MODE,
        "cap": int(CROSS_INDEX_UNSUPPORTED_SOLO_CAP),
        "lookback_hours": float(CROSS_INDEX_CONFIRMATION_LOOKBACK_HOURS),
        "count_basis": "current_active_broker_links_entered_after_support_expiry",
        "closed_trades_counted": False,
        "family_risk_budget_enabled": False,
        "existing_trades_affected": False,
        "rows": rows,
        "time_utc": now_utc_iso(),
    }


