@app.get("/db/sqlite-inventory")
def sqlite_inventory(include_row_counts: bool = True) -> Dict[str, Any]:
    """Manual read-only inventory of the current SQLite schema.

    This is for Postgres sidecar planning only. It is not used by the dashboard
    and it does not migrate or modify data.
    """
    tables = _sqlite_table_inventory(include_row_counts=include_row_counts)
    total_rows = 0
    for t in tables:
        try:
            total_rows += int(t.get("row_count") or 0)
        except Exception:
            pass
    return {
        "status": "ok",
        "app": APP_NAME,
        "time_utc": now_utc_iso(),
        "db_file": _sqlite_db_file_info(),
        "database_runtime": database_runtime_status(),
        "table_count": len(tables),
        "total_rows_counted": total_rows if include_row_counts else None,
        "tables": tables,
        "safety": "read-only inventory; no live trading changes",
    }


@app.get("/db/postgres-migration-plan")
def postgres_migration_plan(include_row_counts: bool = True) -> Dict[str, Any]:
    """Manual Postgres migration planning report.

    Generates a conservative schema/DDL preview from the current SQLite DB. This
    is not an executable live migration endpoint.
    """
    inventory = _sqlite_table_inventory(include_row_counts=include_row_counts)
    ddl_preview = _postgres_ddl_preview_from_inventory(inventory)
    top_tables = sorted(
        [
            {"table": t.get("table"), "row_count": int(t.get("row_count") or 0), "column_count": len(t.get("columns") or [])}
            for t in inventory
        ],
        key=lambda x: x["row_count"],
        reverse=True,
    )[:20]
    return {
        "status": "ok",
        "app": APP_NAME,
        "time_utc": now_utc_iso(),
        "purpose": "Plan Postgres sidecar migration without touching live execution.",
        "sidecar_safety_status": _postgres_sidecar_safety_status(),
        "db_file": _sqlite_db_file_info(),
        "table_count": len(inventory),
        "top_tables_by_rows": top_tables,
        "postgres_connectivity": _postgres_connectivity_check(),
        "ddl_preview": ddl_preview,
        "next_steps": [
            "Create a separate Railway test service with broker execution disabled.",
            "Add Railway PostgreSQL to that test service and set DATABASE_URL/POSTGRES_SIDECAR_DATABASE_URL.",
            "Install psycopg[binary] or psycopg2-binary in the test service.",
            "Use this DDL preview as a checklist; do not run blindly against live.",
            "Build/import copied SQLite data into Postgres sidecar and compare dashboard numbers before any live switch.",
        ],
    }

@app.get("/db/postgres-runtime-smoke")
def postgres_runtime_smoke() -> Dict[str, Any]:
    """Exercise the actual active DB engine using the same app connection layer.

    On the Postgres sidecar this proves that connection, schema init, SQLite-style
    placeholder translation, metadata compatibility, generated IDs and core table
    reads are working. It does not place broker orders.
    """
    init_db()
    with get_conn() as conn:
        table_rows = conn.execute("SELECT name FROM sqlite_master WHERE type='table'").fetchall()
        tables = sorted([safe_str(r["name"]) for r in table_rows])
        core_counts = {}
        for table in ["raw_signals", "open_trades", "closed_trades", "broker_trade_links", "broker_action_queue"]:
            if table in tables:
                core_counts[table] = int(conn.execute(f'SELECT COUNT(*) AS c FROM "{table}"').fetchone()["c"])
        columns = conn.execute("PRAGMA table_info(raw_signals)").fetchall() if "raw_signals" in tables else []
    return {
        "status": "ok",
        "app": APP_NAME,
        "time_utc": now_utc_iso(),
        "database_runtime": database_runtime_status(),
        "active_engine": "postgres" if _is_postgres_engine() else "sqlite",
        "table_count": len(tables),
        "core_counts": core_counts,
        "raw_signals_column_count": len(columns),
        "broker_write_tested": False,
        "safety": "database runtime smoke only; no OANDA write action",
    }


