@app.get("/basket-risk")
def basket_risk(limit: int = 100) -> Dict[str, Any]:
    init_db()
    limit = max(1, min(limit, 500))
    with get_conn() as conn:
        rows = conn.execute("SELECT * FROM basket_risk_checks ORDER BY id DESC LIMIT ?", (limit,)).fetchall()
        latest_by_asset = conn.execute("""
            SELECT b.*
            FROM basket_risk_checks b
            INNER JOIN (
                SELECT asset, MAX(id) AS max_id
                FROM basket_risk_checks
                GROUP BY asset
            ) x ON b.asset = x.asset AND b.id = x.max_id
            ORDER BY b.asset ASC
        """).fetchall()
    return {
        "status": "ok",
        "count": len(rows),
        "latest_by_asset": [dict(row) for row in latest_by_asset],
        "basket_risk_checks": [dict(row) for row in rows],
        "time_utc": now_utc_iso(),
    }


@app.get("/entry-confirmation")
def entry_confirmation(limit: int = 100) -> Dict[str, Any]:
    init_db()
    limit = max(1, min(limit, 500))
    with get_conn() as conn:
        rows = conn.execute("SELECT * FROM entry_confirmation_checks ORDER BY id DESC LIMIT ?", (limit,)).fetchall()
        latest_by_asset = conn.execute("""
            SELECT e.*
            FROM entry_confirmation_checks e
            INNER JOIN (
                SELECT asset, MAX(id) AS max_id
                FROM entry_confirmation_checks
                GROUP BY asset
            ) x ON e.asset = x.asset AND e.id = x.max_id
            ORDER BY e.asset ASC
        """).fetchall()
        summary = conn.execute("""
            SELECT
                asset,
                COUNT(*) AS checks,
                SUM(CASE WHEN current_candidate = 1 THEN 1 ELSE 0 END) AS baseline_entries,
                SUM(CASE WHEN confirmed_entry_allowed = 1 THEN 1 ELSE 0 END) AS confirmed_entries,
                SUM(CASE WHEN current_candidate = 1 AND confirmed_entry_allowed = 0 THEN 1 ELSE 0 END) AS isolated_true_skips
            FROM entry_confirmation_checks
            GROUP BY asset
            ORDER BY asset ASC
        """).fetchall()
    return {
        "status": "ok",
        "count": len(rows),
        "summary": [dict(row) for row in summary],
        "latest_by_asset": [dict(row) for row in latest_by_asset],
        "entry_confirmation_checks": [dict(row) for row in rows],
        "time_utc": now_utc_iso(),
    }


