@app.get("/advice-outcome-audit")
def advice_outcome_audit(limit: int = 200) -> Dict[str, Any]:
    init_db()
    limit = max(1, min(limit, 1000))
    with get_conn() as conn:
        rows = conn.execute("""
            SELECT *
            FROM advice_outcome_audit
            ORDER BY id DESC
            LIMIT ?
        """, (limit,)).fetchall()
        summary = conn.execute("""
            SELECT
                asset,
                tiered_action,
                basket_phase,
                COUNT(*) AS advice_count,
                AVG(selected_pnl_at_advice_50risk) AS avg_selected_pnl_at_advice,
                AVG(latest_delta_vs_advice_50risk) AS avg_latest_delta,
                AVG(outcome_1h_delta_50risk) AS avg_1h_delta,
                AVG(outcome_4h_delta_50risk) AS avg_4h_delta,
                AVG(outcome_12h_delta_50risk) AS avg_12h_delta,
                AVG(outcome_24h_delta_50risk) AS avg_24h_delta
            FROM advice_outcome_audit
            GROUP BY asset, tiered_action, basket_phase
            ORDER BY asset ASC, tiered_action ASC, basket_phase ASC
        """).fetchall()
    return {
        "status": "ok",
        "count": len(rows),
        "summary": [dict(row) for row in summary],
        "advice_outcome_audit": [dict(row) for row in rows],
        "time_utc": now_utc_iso(),
    }


