@app.get("/broker/oanda/shadow-auto/status")
def broker_oanda_shadow_auto_status() -> Dict[str, Any]:
    init_db()
    status = broker_shadow_auto_status()
    with get_conn() as conn:
        active_links = conn.execute("""
            SELECT COUNT(*) AS c FROM broker_trade_links
            WHERE mode='shadow_demo_auto' AND status IN ('OPEN','CLOSE_SENT')
        """).fetchone()["c"]
        queued = conn.execute("""
            SELECT COUNT(*) AS c FROM broker_action_queue
            WHERE mode='shadow_demo_auto' AND status LIKE 'QUEUED%'
        """).fetchone()["c"]
        executed = conn.execute("""
            SELECT COUNT(*) AS c FROM broker_action_queue
            WHERE mode='shadow_demo_auto' AND status='EXECUTED'
        """).fetchone()["c"]
        failed = conn.execute("""
            SELECT COUNT(*) AS c FROM broker_action_queue
            WHERE mode='shadow_demo_auto' AND status LIKE '%FAILED%'
        """).fetchone()["c"]
    return {"status": "ok", "shadow_auto": status, "active_auto_links": active_links, "queued_auto_actions": queued, "executed_auto_actions": executed, "failed_auto_actions": failed, "time_utc": now_utc_iso()}

