def _count_oanda_allowed_open_exposure() -> Dict[str, Any]:
    """Return counts/details for current allowed OANDA exposure.

    Used before wiping local broker test records so we do not hide evidence while
    demo broker exposure is still open.
    """
    allowed = set(BROKER_ALLOWED_INSTRUMENTS or [])
    trades_resp = oanda_request(f"/v3/accounts/{OANDA_ACCOUNT_ID}/openTrades")
    positions_resp = oanda_request(f"/v3/accounts/{OANDA_ACCOUNT_ID}/openPositions")
    if not trades_resp.get("ok") or not positions_resp.get("ok"):
        return {
            "ok": False,
            "error": "Could not verify OANDA open trades/positions before wipe.",
            "trades_response_ok": trades_resp.get("ok"),
            "positions_response_ok": positions_resp.get("ok"),
            "trades_error": trades_resp.get("error", ""),
            "positions_error": positions_resp.get("error", ""),
        }

    trades = trades_resp.get("data", {}).get("trades", []) or []
    positions = positions_resp.get("data", {}).get("positions", []) or []
    if allowed:
        trades = [t for t in trades if safe_str(t.get("instrument")) in allowed]
        positions = [p for p in positions if safe_str(p.get("instrument")) in allowed]

    return {
        "ok": True,
        "open_trade_count": len(trades),
        "open_position_count": len(positions),
        "open_trades": trades,
        "open_positions": positions,
    }


async def wipe_broker_test_data_impl(request: Request) -> Dict[str, Any]:
    """Wipe local broker-test tables after confirming OANDA is flat.

    This clears only local testing/audit/link/queue records. It does not touch
    strategy research tables or any OANDA broker account data.
    """
    init_db()
    try:
        payload = await request.json()
    except Exception:
        payload = {}

    confirm = safe_str(payload.get("confirm") or payload.get("confirmation") or "")
    if confirm != "WIPE_BROKER_TEST_DATA":
        return {
            "status": "blocked",
            "ok": False,
            "reason": "Send confirm='WIPE_BROKER_TEST_DATA' to wipe local broker test records.",
            "time_utc": now_utc_iso(),
        }

    include_snapshots = parse_bool(payload.get("include_broker_snapshots"), False)
    force = parse_bool(payload.get("force"), False)

    exposure = _count_oanda_allowed_open_exposure() if OANDA_ENABLED else {"ok": True, "open_trade_count": 0, "open_position_count": 0, "open_trades": [], "open_positions": []}
    if not exposure.get("ok") and not force:
        return {"status": "blocked", "ok": False, "reason": exposure.get("error"), "exposure_check": exposure, "time_utc": now_utc_iso()}
    if not force and (int(exposure.get("open_trade_count") or 0) > 0 or int(exposure.get("open_position_count") or 0) > 0):
        return {
            "status": "blocked",
            "ok": False,
            "reason": "OANDA still has open allowed trades/positions. Close broker exposure before wiping test records.",
            "exposure_check": exposure,
            "time_utc": now_utc_iso(),
        }

    tables = ["execution_audit_events", "broker_action_queue", "broker_trade_links"]
    if include_snapshots:
        tables.append("broker_snapshots")

    deleted_counts: Dict[str, int] = {}
    with get_conn() as conn:
        for table in tables:
            before = conn.execute(f"SELECT COUNT(*) AS c FROM {table}").fetchone()["c"]
            conn.execute(f"DELETE FROM {table}")
            deleted_counts[table] = int(before or 0)
            try:
                conn.execute("DELETE FROM sqlite_sequence WHERE name = ?", (table,))
            except Exception:
                pass
        conn.commit()

    return {
        "status": "ok",
        "ok": True,
        "message": "Local broker test records wiped. OANDA broker exposure was verified flat first.",
        "deleted_counts": deleted_counts,
        "include_broker_snapshots": include_snapshots,
        "exposure_check": {k: v for k, v in exposure.items() if k not in {"open_trades", "open_positions"}},
        "time_utc": now_utc_iso(),
    }


@app.post("/broker/oanda/test/wipe-broker-test-data")
async def broker_oanda_test_wipe_broker_test_data(request: Request) -> Dict[str, Any]:
    return await wipe_broker_test_data_impl(request)


