def reclassify_timeout_failures(limit: int = 100) -> Dict[str, Any]:
    """Move ambiguous timeout failures into WAITING_RECONCILIATION so they block duplicate opens.

    Use after upgrading from older versions where read timeouts were marked EXECUTION_FAILED.
    This does not retry anything. It only makes the queue safe/idempotent.
    """
    init_db()
    try:
        limit = max(1, min(int(limit), 1000))
    except Exception:
        limit = 100
    with get_conn() as conn:
        rows = [dict(r) for r in conn.execute("""
            SELECT * FROM broker_action_queue
            WHERE mode = 'shadow_demo_auto'
              AND action = 'place_risk_order'
              AND status = 'EXECUTION_FAILED'
            ORDER BY id DESC
            LIMIT ?
        """, (limit,)).fetchall()]
    changed=[]
    skipped=[]
    for q in rows:
        hay = " ".join([safe_str(q.get("notes")), safe_str(q.get("preview_json")), safe_str(q.get("reason"))])
        if is_oanda_timeout_or_unknown_response({"text": hay}):
            qid=int(q.get("id") or 0)
            update_broker_action_queue_status(qid, "WAITING_RECONCILIATION", "Reclassified old timeout/ambiguous failure. Reconcile broker state before any retry.")
            changed.append({"queue_id": qid, "shadow_trade_id": q.get("shadow_trade_id"), "old_status": q.get("status"), "new_status": "WAITING_RECONCILIATION"})
        else:
            skipped.append({"queue_id": q.get("id"), "reason": "not timeout/ambiguous"})
    return {"status": "ok", "ok": True, "checked": len(rows), "changed": len(changed), "changed_items": changed, "skipped": skipped, "time_utc": now_utc_iso()}

