@app.post("/broker/oanda/test/execute-queued-action")
async def broker_oanda_test_execute_queued_action(request: Request) -> Dict[str, Any]:
    """Manual restricted in live mode execution of one queued dry-run broker action.

    v6.2: reconcile now includes CLOSE_SENT broker links so queued closes are confirmed closed.
    Supports queued place_risk_order, close_linked_trade, and close_until_flat actions.
    """
    init_db()
    try:
        payload = await request.json()
    except Exception:
        payload = {}

    queue_id = int(payload.get("queue_id") or payload.get("id") or 0)
    if queue_id <= 0:
        raise HTTPException(status_code=400, detail="queue_id is required")

    try:
        allow_reexecute = parse_bool(payload.get("allow_reexecute"), False)

        with get_conn() as conn:
            row = conn.execute("SELECT * FROM broker_action_queue WHERE id = ?", (queue_id,)).fetchone()
        if not row:
            raise HTTPException(status_code=404, detail=f"queue_id {queue_id} not found")

        q = dict(row)
        q_status = safe_str(q.get("status", "")).upper()
        q_action = safe_str(q.get("action", ""))

        if q_status == "CANCELLED":
            return {"status": "error", "ok": False, "queue_id": queue_id, "error": "Queued action is cancelled", "queued_action": q, "safety": oanda_safety_state(), "time_utc": now_utc_iso()}
        if q.get("executed_audit_id") and not allow_reexecute:
            return {"status": "error", "ok": False, "queue_id": queue_id, "error": "Queued action already has executed_audit_id; pass allow_reexecute=true only for deliberate retest", "queued_action": q, "safety": oanda_safety_state(), "time_utc": now_utc_iso()}
        if q_action not in {"place_risk_order", "close_linked_trade", "close_until_flat"}:
            return {"status": "error", "ok": False, "queue_id": queue_id, "error": f"Unsupported queued action: {q_action}", "queued_action": q, "safety": oanda_safety_state(), "time_utc": now_utc_iso()}

        safety = oanda_safety_state()
        if not safety.get("orders_allowed"):
            update_broker_action_queue_status(queue_id, "EXECUTION_BLOCKED", safe_str(safety.get("reason", "orders not allowed")))
            return {"status": "blocked", "ok": False, "queue_id": queue_id, "error": safe_str(safety.get("reason", "orders not allowed")), "queued_action": q, "safety": safety, "time_utc": now_utc_iso()}

        instrument = normalise_oanda_instrument(q.get("instrument") or "")
        side = safe_str(q.get("side") or "buy").lower()

        if q_action == "close_until_flat":
            try:
                preview = json.loads(q.get("preview_json") or "{}")
            except Exception:
                preview = {}

            requested = preview.get("instruments") or q.get("instrument") or list(BROKER_ALLOWED_INSTRUMENTS)
            if isinstance(requested, str):
                instruments = [normalise_oanda_instrument(x) for x in requested.split(",")]
            else:
                instruments = [normalise_oanda_instrument(x) for x in requested]
            instruments = [x for x in instruments if x]
            instruments = list(dict.fromkeys(instruments))

            try:
                max_retries = int(preview.get("max_retries", os.getenv("BROKER_CLOSE_ALL_MAX_RETRIES", "3")))
            except Exception:
                max_retries = 3
            max_retries = max(0, min(max_retries, 10))

            try:
                retry_sleep_seconds = float(preview.get("retry_sleep_seconds", os.getenv("BROKER_CLOSE_ALL_RETRY_SLEEP_SECONDS", "0.75")))
            except Exception:
                retry_sleep_seconds = 0.75
            retry_sleep_seconds = max(0.0, min(retry_sleep_seconds, 5.0))

            valid_instruments = []
            validation_results = []
            for inst in instruments:
                inst_ok, inst_msg = validate_manual_oanda_instrument(inst)
                if inst_ok:
                    valid_instruments.append(inst)
                else:
                    validation_results.append({"instrument": inst, "ok": False, "error": inst_msg})

            if not valid_instruments:
                update_broker_action_queue_status(queue_id, "EXECUTION_FAILED", "no valid allowed instruments for close_until_flat")
                return {"status": "error", "ok": False, "queue_id": queue_id, "error": "no valid allowed instruments for close_until_flat", "validation_results": validation_results, "safety": safety, "time_utc": now_utc_iso()}

            instrument_set = set(valid_instruments)

            def _remaining_positions() -> Tuple[bool, List[Dict[str, Any]], Dict[str, Any]]:
                resp_pos = oanda_request(f"/v3/accounts/{OANDA_ACCOUNT_ID}/openPositions")
                if not resp_pos.get("ok"):
                    return False, [], resp_pos
                positions = resp_pos.get("data", {}).get("positions", []) or []
                remaining_pos = [p for p in positions if safe_str(p.get("instrument")) in instrument_set]
                return True, remaining_pos, resp_pos

            def _close_position_sides(position: Dict[str, Any]) -> Dict[str, Any]:
                inst = safe_str(position.get("instrument"))
                long_units = safe_float((position.get("long") or {}).get("units")) or 0.0
                short_units = safe_float((position.get("short") or {}).get("units")) or 0.0
                close_body: Dict[str, Any] = {}
                if long_units > 0:
                    close_body["longUnits"] = "ALL"
                if short_units < 0:
                    close_body["shortUnits"] = "ALL"
                if not close_body:
                    return {"instrument": inst, "ok": True, "skipped": True, "reason": "no non-zero side", "long_units": long_units, "short_units": short_units}
                resp_close = oanda_write_request(
                    f"/v3/accounts/{OANDA_ACCOUNT_ID}/positions/{urllib.parse.quote(inst)}/close",
                    "PUT",
                    close_body,
                )
                return {"instrument": inst, "ok": bool(resp_close.get("ok")), "request": close_body, "long_units_before": long_units, "short_units_before": short_units, "response": resp_close}

            initial_ok, remaining, initial_resp = _remaining_positions()
            if not initial_ok:
                update_broker_action_queue_status(queue_id, "EXECUTION_FAILED", "could not fetch open positions before queued close_until_flat")
                return {"status": "error", "ok": False, "queue_id": queue_id, "error": "could not fetch open positions before queued close_until_flat", "response": initial_resp, "safety": safety, "time_utc": now_utc_iso()}

            initial_remaining_count = len(remaining)
            passes: List[Dict[str, Any]] = []
            max_passes = max_retries + 1
            confirmed_flat = len(remaining) == 0
            for pass_index in range(max_passes):
                if not remaining:
                    confirmed_flat = True
                    passes.append({"pass": pass_index, "skipped": True, "reason": "Already flat before this pass.", "remaining_before_count": 0, "results": [], "remaining_after_count": 0})
                    break
                pass_results = [_close_position_sides(pos) for pos in remaining]
                if retry_sleep_seconds > 0:
                    time.sleep(retry_sleep_seconds)
                after_ok, after_remaining, after_resp = _remaining_positions()
                if not after_ok:
                    passes.append({"pass": pass_index, "remaining_before_count": len(remaining), "results": pass_results, "recheck_ok": False, "recheck_response": after_resp, "remaining_after_count": None})
                    confirmed_flat = False
                    break
                passes.append({"pass": pass_index, "remaining_before_count": len(remaining), "results": pass_results, "recheck_ok": True, "remaining_after_count": len(after_remaining), "remaining_after": after_remaining})
                remaining = after_remaining
                confirmed_flat = len(remaining) == 0
                if confirmed_flat:
                    break

            close_requests_ok = True
            for pass_data in passes:
                for r in pass_data.get("results", []):
                    if r.get("blocked") or r.get("ok") is False:
                        close_requests_ok = False

            success = bool(confirmed_flat and close_requests_ok)
            audit_id = log_execution_audit_event(
                "practice_manual_queue", safe_str(q.get("family") or "INDEX_BASKET"), safe_str(q.get("shadow_trade_id") or ""), "execute_queued_close_until_flat",
                success, f"manual execution of queued close-until-flat action {queue_id}", "",
                raw={"queue": q, "preview": preview, "requested_instruments": valid_instruments, "initial_remaining_count": initial_remaining_count, "passes": passes, "remaining_allowed_positions": remaining, "confirmed_flat": confirmed_flat},
                retry_count=max(0, len(passes) - 1), close_all_required=True, broker_position_confirmed_flat=confirmed_flat,
                response_status_code=200 if success else None,
            )
            update_broker_action_queue_status(queue_id, "EXECUTED" if success else "EXECUTION_FAILED", "Queued close-until-flat executed manually" if success else "Queued close-until-flat did not confirm flat", audit_id, None)
            return {
                "status": "ok" if success else "warning",
                "ok": success,
                "queue_id": queue_id,
                "executed_audit_id": audit_id,
                "confirmed_flat": confirmed_flat,
                "requested_instruments": valid_instruments,
                "initial_remaining_count": initial_remaining_count,
                "remaining_allowed_positions": remaining,
                "passes_run": len(passes),
                "passes": passes,
                "safety": oanda_safety_state(),
                "time_utc": now_utc_iso(),
            }

        if q_action == "close_linked_trade":
            link_id = int(q.get("broker_trade_link_id") or 0)
            with get_conn() as conn:
                link_row = conn.execute("SELECT * FROM broker_trade_links WHERE id = ?", (link_id,)).fetchone() if link_id > 0 else None
            if not link_row:
                update_broker_action_queue_status(queue_id, "EXECUTION_FAILED", "linked broker trade not found")
                return {"status": "error", "ok": False, "queue_id": queue_id, "error": "linked broker trade not found", "queued_action": q, "safety": safety, "time_utc": now_utc_iso()}
            link = dict(link_row)
            broker_trade_id = safe_str(link.get("broker_trade_id") or "")
            if not broker_trade_id:
                update_broker_action_queue_status(queue_id, "EXECUTION_FAILED", "linked broker trade has no broker_trade_id")
                return {"status": "error", "ok": False, "queue_id": queue_id, "error": "linked broker trade has no broker_trade_id", "broker_trade_link": link, "safety": safety, "time_utc": now_utc_iso()}

            close_body = {"units": "ALL"}
            resp = oanda_write_request(f"/v3/accounts/{OANDA_ACCOUNT_ID}/trades/{urllib.parse.quote(broker_trade_id)}/close", "PUT", close_body)
            details = extract_oanda_execution_details(resp)
            broker_order_id = details.get("broker_order_id") or extract_transaction_id(resp)
            success = bool(resp.get("ok"))
            audit_id = log_execution_audit_event(
                "practice_manual_queue", normalise_oanda_instrument(link.get("instrument") or instrument), safe_str(link.get("shadow_trade_id") or ""), "execute_queued_close_linked_trade",
                success, f"manual execution of queued close action {queue_id}", broker_order_id, raw={"queue": q, "broker_trade_link": link, "request": close_body, "response": resp},
                side=safe_str(link.get("side") or side), close_units=details.get("closed_units"), actual_price=details.get("actual_price"),
                broker_trade_id=broker_trade_id, response_status_code=details.get("response_status_code"),
            )
            if success:
                now_closed = now_utc_iso()
                with get_conn() as conn:
                    conn.execute("""
                        UPDATE broker_trade_links
                        SET updated_at_utc=?, status='CLOSE_SENT', closed_at_utc=COALESCE(NULLIF(closed_at_utc,''), ?),
                            last_reconciled_at_utc=?, notes=?
                        WHERE id=?
                    """, (now_closed, now_closed, now_closed, f"Close sent from broker_action_queue id {queue_id}", link_id))
                    conn.commit()
                update_broker_action_queue_status(queue_id, "EXECUTED", "Queued linked close executed manually", audit_id, link_id)
            else:
                if is_oanda_market_closed_response(resp):
                    mark_queue_waiting_market_reopen(queue_id, resp, audit_id, link_id)
                else:
                    update_broker_action_queue_status(queue_id, "EXECUTION_FAILED", safe_str(resp.get("error") or resp.get("text") or "OANDA close failed"), audit_id, link_id)
            return {
                "status": "ok" if success else ("waiting_market_reopen" if is_oanda_market_closed_response(resp) else "error"),
                "ok": success,
                "queue_id": queue_id,
                "executed_audit_id": audit_id,
                "broker_trade_link_id": link_id,
                "request": close_body,
                "response": resp,
                "broker_order_id": broker_order_id,
                "broker_trade_id": broker_trade_id,
                "safety": oanda_safety_state(),
                "time_utc": now_utc_iso(),
            }

        # place_risk_order
        requested_units = safe_float(q.get("requested_units"))
        preview: Dict[str, Any]
        if requested_units is None or abs(requested_units) <= 0:
            preview = build_risk_order_preview(
                instrument=instrument,
                side=side,
                risk_amount=safe_float(q.get("risk_amount")),
                sl_pct=safe_float(q.get("sl_pct")),
            )
            if not preview.get("ok"):
                update_broker_action_queue_status(queue_id, "EXECUTION_PREVIEW_ERROR", safe_str(preview.get("error", "preview failed")))
                return {"status": "error", "ok": False, "queue_id": queue_id, "preview": preview, "safety": safety, "time_utc": now_utc_iso()}
            requested_units = safe_float(preview.get("signed_units"))
        else:
            try:
                preview = json.loads(q.get("preview_json") or "{}")
            except Exception:
                preview = {}

        if requested_units is None or abs(float(requested_units)) <= 0:
            update_broker_action_queue_status(queue_id, "EXECUTION_FAILED", "requested_units missing/zero")
            return {"status": "error", "ok": False, "queue_id": queue_id, "error": "requested_units missing/zero", "queued_action": q, "safety": safety, "time_utc": now_utc_iso()}

        order_body = {
            "order": {
                "type": "MARKET",
                "instrument": instrument,
                "units": str(requested_units),
                "timeInForce": "FOK",
                "positionFill": "DEFAULT",
            }
        }

        resp = oanda_write_request(f"/v3/accounts/{OANDA_ACCOUNT_ID}/orders", "POST", order_body)
        details = extract_oanda_execution_details(resp)
        broker_order_id = details.get("broker_order_id") or extract_transaction_id(resp)
        success = bool(resp.get("ok"))

        audit_id = log_execution_audit_event(
            "practice_manual_queue", instrument, safe_str(q.get("shadow_trade_id", "")), "execute_queued_place_risk_order",
            success, f"manual execution of queued action {queue_id}", broker_order_id, raw={"queue": q, "preview": preview, "request": order_body, "response": resp},
            intended_price=safe_float(q.get("preview_price")) or safe_float(preview.get("current_mid_price")),
            actual_price=details.get("actual_price"),
            side=side,
            requested_units=requested_units,
            filled_units=details.get("filled_units"),
            risk_amount=safe_float(q.get("risk_amount")),
            sl_pct=safe_float(q.get("sl_pct")),
            estimated_risk=safe_float(q.get("estimated_risk")),
            broker_trade_id=details.get("broker_trade_id", ""),
            response_status_code=details.get("response_status_code"),
        )

        link_id = None
        if success:
            link_id = create_broker_trade_link(
                source="queue_execute",
                mode="practice_manual_queue",
                shadow_trade_id=safe_str(q.get("shadow_trade_id", "")),
                shadow_asset=safe_str(q.get("shadow_asset", "")) or instrument,
                shadow_trade_ref=f"broker_action_queue_id={queue_id}",
                instrument=instrument,
                side=side,
                requested_units=requested_units,
                filled_units=details.get("filled_units"),
                broker_order_id=broker_order_id,
                broker_trade_id=details.get("broker_trade_id", ""),
                source_audit_id=audit_id,
                status="OPEN",
                last_known_price=details.get("actual_price"),
                notes=f"Executed from broker_action_queue id {queue_id}. Manual practice only.",
                raw={"queue": q, "preview": preview, "response": resp},
            )
            update_broker_action_queue_status(queue_id, "EXECUTED", "Executed manually from queue", audit_id, link_id)
        else:
            if is_oanda_market_closed_response(resp):
                mark_queue_waiting_market_reopen(queue_id, resp, audit_id, None)
            else:
                update_broker_action_queue_status(queue_id, "EXECUTION_FAILED", safe_str(resp.get("error") or resp.get("text") or "OANDA order failed"), audit_id, None)

        return {
            "status": "ok" if success else ("waiting_market_reopen" if is_oanda_market_closed_response(resp) else "error"),
            "ok": success,
            "queue_id": queue_id,
            "executed_audit_id": audit_id,
            "broker_trade_link_id": link_id,
            "request": order_body,
            "response": resp,
            "broker_order_id": broker_order_id,
            "broker_trade_id": details.get("broker_trade_id", ""),
            "safety": oanda_safety_state(),
            "time_utc": now_utc_iso(),
        }

    except HTTPException:
        raise
    except Exception as exc:
        err = f"execute queued action failed: {type(exc).__name__}: {exc}"
        try:
            update_broker_action_queue_status(queue_id, "EXECUTION_FAILED", err)
        except Exception:
            pass
        return {"status": "error", "ok": False, "queue_id": queue_id, "error": err, "safety": oanda_safety_state(), "time_utc": now_utc_iso()}


@app.post("/broker/oanda/reconcile-links")
def broker_oanda_reconcile_links() -> Dict[str, Any]:
    return reconcile_broker_trade_links()


@app.post("/broker/oanda/test/place-linked-risk-order")
async def broker_oanda_test_place_linked_risk_order(request: Request) -> Dict[str, Any]:
    """Manual restricted in live mode risk order that also creates a shadow-to-broker link record."""
    init_db()
    try:
        body = await request.json()
    except Exception:
        body = {}

    shadow_trade_id = safe_str(body.get("shadow_trade_id") or body.get("shadow_id") or "")
    shadow_asset = safe_str(body.get("shadow_asset") or body.get("asset") or body.get("instrument") or "")
    shadow_trade_ref = safe_str(body.get("shadow_trade_ref") or body.get("trade_ref") or "")

    preview = build_risk_order_preview(
        instrument=body.get("instrument") or body.get("asset") or "SPX500_USD",
        side=body.get("side") or "buy",
        risk_amount=safe_float(body.get("risk_amount")) if body.get("risk_amount") is not None else None,
        sl_pct=safe_float(body.get("sl_pct")) if body.get("sl_pct") is not None else None,
    )
    if not preview.get("ok"):
        log_execution_audit_event("practice_manual", safe_str(preview.get("instrument", "")), shadow_trade_id, "place_linked_risk_order", False, safe_str(preview.get("error", "risk preview failed")), raw=preview)
        return {"status": "error", "ok": False, "preview": preview, "safety": oanda_safety_state(), "time_utc": now_utc_iso()}

    order_body = {
        "order": {
            "type": "MARKET",
            "instrument": preview["instrument"],
            "units": str(preview["signed_units"]),
            "timeInForce": "FOK",
            "positionFill": "DEFAULT",
        }
    }
    resp = oanda_write_request(f"/v3/accounts/{OANDA_ACCOUNT_ID}/orders", "POST", order_body)
    details = extract_oanda_execution_details(resp)
    broker_order_id = details.get("broker_order_id") or extract_transaction_id(resp)
    success = bool(resp.get("ok"))

    log_execution_audit_event(
        "practice_manual", preview["instrument"], shadow_trade_id, "place_linked_risk_order",
        success, "manual practice linked risk-sized market order", broker_order_id, raw={"preview": preview, "response": resp},
        intended_price=safe_float(preview.get("current_mid_price")),
        actual_price=details.get("actual_price"),
        side=safe_str(preview.get("side")),
        requested_units=safe_float(preview.get("signed_units")),
        filled_units=details.get("filled_units"),
        risk_amount=safe_float(preview.get("risk_amount_requested")),
        sl_pct=safe_float(preview.get("sl_pct")),
        estimated_risk=safe_float(preview.get("estimated_risk_amount")),
        broker_trade_id=details.get("broker_trade_id", ""),
        response_status_code=details.get("response_status_code"),
    )

    link_id = None
    if success:
        link_id = create_broker_trade_link(
            source="manual_test",
            mode="practice_manual",
            shadow_trade_id=shadow_trade_id,
            shadow_asset=shadow_asset or preview["instrument"],
            shadow_trade_ref=shadow_trade_ref,
            instrument=preview["instrument"],
            side=safe_str(preview.get("side")),
            requested_units=safe_float(preview.get("signed_units")),
            filled_units=details.get("filled_units"),
            broker_order_id=broker_order_id,
            broker_trade_id=details.get("broker_trade_id", ""),
            status="OPEN",
            last_known_price=details.get("actual_price"),
            notes="Manual practice linked risk order. Not automatic strategy execution.",
            raw={"preview": preview, "response": resp},
        )

    return {
        "status": "ok" if success else "error",
        "ok": success,
        "preview": preview,
        "request": order_body,
        "response": resp,
        "broker_order_id": broker_order_id,
        "broker_trade_id": details.get("broker_trade_id", ""),
        "broker_trade_link_id": link_id,
        "safety": oanda_safety_state(),
        "time_utc": now_utc_iso(),
    }



@app.post("/broker/oanda/test/purge-pre-demo-financing")
def broker_oanda_test_purge_pre_demo_financing(body: Dict[str, Any], x_webhook_secret: str = Header(default="")) -> Dict[str, Any]:
    """Optional cleanup: delete financing rows before the live baseline.

    The v10.0.1 dashboard already hides pre-demo costs using the reporting floor.
    This endpoint is only for cleaning the live DB/export after confirming the
    archive exists.
    """
    if x_webhook_secret != WEBHOOK_SECRET:
        raise HTTPException(status_code=401, detail="Invalid webhook secret")
    init_db()
    confirm = safe_str((body or {}).get("confirm") or "") if isinstance(body, dict) else ""
    if confirm != "PURGE_PRE_DEMO_FINANCING":
        return {"status": "blocked", "ok": False, "reason": "Send confirm='PURGE_PRE_DEMO_FINANCING' to delete financing rows before the live baseline timestamp.", "time_utc": now_utc_iso()}
    floor = june_full_demo_started_at_utc()
    if not floor:
        return {"status": "blocked", "ok": False, "reason": "No june_full_demo_started_at_utc runtime setting found.", "time_utc": now_utc_iso()}
    with get_conn() as conn:
        before = conn.execute("SELECT COUNT(*) AS c FROM broker_financing_transactions").fetchone()["c"]
        old = conn.execute("SELECT COUNT(*) AS c FROM broker_financing_transactions WHERE transaction_time < ?", (floor,)).fetchone()["c"]
        conn.execute("DELETE FROM broker_financing_transactions WHERE transaction_time < ?", (floor,))
        conn.commit()
        after = conn.execute("SELECT COUNT(*) AS c FROM broker_financing_transactions").fetchone()["c"]
    return {"status": "ok", "ok": True, "demo_reporting_floor_utc": floor, "rows_before": int(before or 0), "rows_purged": int(old or 0), "rows_after": int(after or 0), "time_utc": now_utc_iso()}


