# ============================================================
# BROKER RECONCILIATION HEALTH
# ============================================================

def broker_reconciliation_health() -> Dict[str, Any]:
    """Compares OANDA's actual open broker trades/positions against Railway's broker trade links.

    This is a read-only operational safety check. It helps detect:
      - broker exposure with no Railway link (orphan broker trades),
      - Railway links marked OPEN when OANDA says the trade is no longer open,
      - links stuck in CLOSE_SENT,
      - queued/executed actions that need follow-up.
    """
    init_db()
    now = now_utc_iso()
    safety = oanda_safety_state()

    trades_resp = oanda_request(f"/v3/accounts/{OANDA_ACCOUNT_ID}/openTrades") if OANDA_ENABLED else {"ok": False, "error": "OANDA_ENABLED is false"}
    positions_resp = oanda_request(f"/v3/accounts/{OANDA_ACCOUNT_ID}/openPositions") if OANDA_ENABLED else {"ok": False, "error": "OANDA_ENABLED is false"}

    open_trades = trades_resp.get("data", {}).get("trades", []) if trades_resp.get("ok") else []
    open_positions = positions_resp.get("data", {}).get("positions", []) if positions_resp.get("ok") else []

    open_trade_ids = {safe_str(t.get("id")) for t in (open_trades or []) if isinstance(t, dict)}
    allowed = set(BROKER_ALLOWED_INSTRUMENTS or [])
    allowed_open_trades = [t for t in (open_trades or []) if not allowed or safe_str(t.get("instrument")) in allowed]
    allowed_open_positions = [p for p in (open_positions or []) if not allowed or safe_str(p.get("instrument")) in allowed]

    with get_conn() as conn:
        link_rows = [dict(r) for r in conn.execute("SELECT * FROM broker_trade_links ORDER BY id DESC LIMIT 1000").fetchall()]
        queue_rows = [dict(r) for r in conn.execute("SELECT * FROM broker_action_queue ORDER BY id DESC LIMIT 1000").fetchall()]

    linked_trade_ids = {safe_str(r.get("broker_trade_id")) for r in link_rows if safe_str(r.get("broker_trade_id"))}
    active_link_statuses = {"OPEN", "LINKED", "PENDING", "CLOSE_SENT"}
    active_links = [r for r in link_rows if safe_str(r.get("status")).upper() in active_link_statuses]

    orphan_open_trades = []
    for t in allowed_open_trades:
        tid = safe_str(t.get("id"))
        if tid and tid not in linked_trade_ids:
            orphan_open_trades.append({
                "broker_trade_id": tid,
                "instrument": t.get("instrument"),
                "currentUnits": t.get("currentUnits"),
                "price": t.get("price"),
                "unrealizedPL": t.get("unrealizedPL") or t.get("trueUnrealizedPL"),
                "openTime": t.get("openTime"),
            })

    stale_open_links = []
    close_sent_links = []
    for r in active_links:
        tid = safe_str(r.get("broker_trade_id"))
        st = safe_str(r.get("status")).upper()
        if st == "CLOSE_SENT":
            close_sent_links.append({
                "link_id": r.get("id"),
                "shadow_trade_id": r.get("shadow_trade_id"),
                "instrument": r.get("instrument"),
                "broker_trade_id": tid,
                "last_reconciled_at_utc": r.get("last_reconciled_at_utc"),
            })
        if tid and tid not in open_trade_ids:
            stale_open_links.append({
                "link_id": r.get("id"),
                "shadow_trade_id": r.get("shadow_trade_id"),
                "instrument": r.get("instrument"),
                "status": r.get("status"),
                "broker_trade_id": tid,
                "last_reconciled_at_utc": r.get("last_reconciled_at_utc"),
            })

    pending_queue = [r for r in queue_rows if safe_str(r.get("status")).upper() in {"QUEUED_DRY_RUN", "QUEUED", "READY", "PENDING", "QUEUED_AUTO_SHADOW"}]
    waiting_reopen_queue = [r for r in queue_rows if safe_str(r.get("status")).upper() == "WAITING_MARKET_REOPEN"]
    waiting_price_retry_queue = [r for r in queue_rows if safe_str(r.get("status")).upper() == "WAITING_PRICE_RETRY" and broker_preview_retry_still_allowed(dict(r))]
    failed_queue = [r for r in queue_rows if ("FAILED" in safe_str(r.get("status")).upper() or "ERROR" in safe_str(r.get("status")).upper()) and safe_str(r.get("status")).upper() not in {"WAITING_MARKET_REOPEN", "WAITING_PRICE_RETRY"}]

    issues: List[str] = []
    if orphan_open_trades:
        issues.append(f"{len(orphan_open_trades)} open OANDA trade(s) have no Railway broker link.")
    if stale_open_links:
        issues.append(f"{len(stale_open_links)} Railway broker link(s) are active but the OANDA trade is not open.")
    if close_sent_links:
        issues.append(f"{len(close_sent_links)} broker link(s) are still CLOSE_SENT and need reconciliation/follow-up.")
    if pending_queue:
        issues.append(f"{len(pending_queue)} queued broker action(s) are pending.")
    if waiting_reopen_queue:
        issues.append(f"{len(waiting_reopen_queue)} queued broker action(s) are waiting for market reopen retry.")
    # WAITING_PRICE_RETRY is a short-lived, controlled retry state. It should be
    # visible in the queue/cost guardrails but should not make reconciliation WARN
    # when OANDA trades and Railway links otherwise match.
    if failed_queue:
        issues.append(f"{len(failed_queue)} queued broker action(s) are failed/error and should be reviewed.")
    if not trades_resp.get("ok"):
        issues.append("Could not read OANDA open trades.")
    if not positions_resp.get("ok"):
        issues.append("Could not read OANDA open positions.")

    if issues:
        status = "WARN"
    else:
        status = "OK"

    return {
        "status": status,
        "ok": status == "OK",
        "issues": issues,
        "counts": {
            "oanda_open_trades": len(open_trades or []),
            "allowed_open_trades": len(allowed_open_trades or []),
            "oanda_open_positions": len(open_positions or []),
            "allowed_open_positions": len(allowed_open_positions or []),
            "active_broker_links": len(active_links),
            "orphan_open_trades": len(orphan_open_trades),
            "stale_open_links": len(stale_open_links),
            "close_sent_links": len(close_sent_links),
            "pending_queue": len(pending_queue),
            "waiting_market_reopen_queue": len(waiting_reopen_queue),
            "waiting_price_retry_queue": len(waiting_price_retry_queue),
            "failed_queue": len(failed_queue),
        },
        "orphan_open_trades": orphan_open_trades,
        "stale_open_links": stale_open_links,
        "close_sent_links": close_sent_links,
        "pending_queue": [{"id": r.get("id"), "action": r.get("action"), "instrument": r.get("instrument"), "status": r.get("status"), "reason": r.get("reason")} for r in pending_queue[:50]],
        "waiting_market_reopen_queue": [{"id": r.get("id"), "action": r.get("action"), "instrument": r.get("instrument"), "status": r.get("status"), "notes": r.get("notes")} for r in waiting_reopen_queue[:50]],
        "waiting_price_retry_queue": [{"id": r.get("id"), "action": r.get("action"), "instrument": r.get("instrument"), "status": r.get("status"), "notes": r.get("notes")} for r in waiting_price_retry_queue[:50]],
        "failed_queue": [{"id": r.get("id"), "action": r.get("action"), "instrument": r.get("instrument"), "status": r.get("status"), "notes": r.get("notes")} for r in failed_queue[:50]],
        "safety": safety,
        "time_utc": now,
    }

