@app.post("/broker/capital-movement")
async def broker_record_capital_movement(request: Request, x_webhook_secret: Optional[str] = Header(None)) -> Dict[str, Any]:
    """Record a deposit/withdrawal so account performance excludes cash injections.

    This is accounting only. It does not place orders, resize trades, or change risk.
    """
    init_db()
    try:
        body = await request.json()
    except Exception:
        body = {}
    body_secret = safe_str(body.get("webhook_secret") or body.get("secret")) if isinstance(body, dict) else ""
    query_secret = safe_str(request.query_params.get("secret") or "")
    if x_webhook_secret != WEBHOOK_SECRET and body_secret != WEBHOOK_SECRET and query_secret != WEBHOOK_SECRET:
        raise HTTPException(status_code=401, detail="Invalid WEBHOOK_SECRET")
    movement_type = safe_str((body or {}).get("movement_type") or (body or {}).get("type") or "DEPOSIT").upper()
    if movement_type not in {"DEPOSIT", "WITHDRAWAL"}:
        raise HTTPException(status_code=400, detail="movement_type must be DEPOSIT or WITHDRAWAL")
    amount = safe_float((body or {}).get("amount"))
    if amount is None or amount <= 0:
        raise HTTPException(status_code=400, detail="amount must be greater than zero")
    note = safe_str((body or {}).get("note") or "")[:500]
    movement_time = safe_str((body or {}).get("movement_time_utc") or now_utc_iso())
    currency = safe_str((body or {}).get("currency") or ("GBP" if safe_str(OANDA_ENV).lower() == "live" else "USD"))

    nav_at_record = None
    with get_conn() as conn:
        row = conn.execute("""
            SELECT nav FROM broker_snapshots
            WHERE environment = ? AND account_id = ? AND status = 'OK'
            ORDER BY created_at_utc DESC, id DESC
            LIMIT 1
        """, (OANDA_ENV, OANDA_ACCOUNT_ID)).fetchone()
        nav_at_record = safe_float(row["nav"]) if row else None
        movement_id = db_insert_returning_id(conn, """
            INSERT INTO broker_capital_movements (
                created_at_utc, movement_time_utc, environment, account_id, movement_type,
                amount, currency, note, nav_at_record, raw_json
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """, (now_utc_iso(), movement_time, OANDA_ENV, OANDA_ACCOUNT_ID, movement_type, float(amount), currency, note, nav_at_record, json.dumps(body or {})))
    log_system_event("broker_capital_movement_recorded", f"{movement_type} {amount:.2f} {currency} for {OANDA_ENV}/{OANDA_ACCOUNT_ID}: {note}")
    return {
        "ok": True,
        "id": movement_id,
        "movement_type": movement_type,
        "amount": float(amount),
        "amount_display": money(amount, currency),
        "currency": currency,
        "note": note,
        "environment": OANDA_ENV,
        "account_id": OANDA_ACCOUNT_ID,
        "nav_at_record": nav_at_record,
        "message": "Capital movement recorded. Trading P&L now excludes this cashflow for matching periods.",
        "time_utc": now_utc_iso(),
    }


@app.post("/broker/reset-accounting-baseline")
async def broker_reset_accounting_baseline(request: Request, x_webhook_secret: Optional[str] = Header(None)) -> Dict[str, Any]:
    """Reset live broker P&L baseline to the latest current-account OANDA snapshot.

    Used when switching from practice to live or deliberately restarting the live
    accounting baseline. Normal deposits/withdrawals should be recorded using
    /broker/capital-movement so they do not distort trading P&L mid-basket.
    This does not place orders.
    """
    init_db()
    try:
        body = await request.json()
    except Exception:
        body = {}
    body_secret = safe_str(body.get("webhook_secret") or body.get("secret")) if isinstance(body, dict) else ""
    query_secret = safe_str(request.query_params.get("secret") or "")
    if x_webhook_secret != WEBHOOK_SECRET and body_secret != WEBHOOK_SECRET and query_secret != WEBHOOK_SECRET:
        raise HTTPException(status_code=401, detail="Invalid WEBHOOK_SECRET")
    if safe_str((body or {}).get("confirm")) != "RESET_BROKER_PNL_BASELINE":
        raise HTTPException(status_code=400, detail="Missing confirm=RESET_BROKER_PNL_BASELINE")

    with get_conn() as conn:
        row = conn.execute("""
            SELECT created_at_utc, balance, nav, unrealized_pl, account_id, environment, raw_json
            FROM broker_snapshots
            WHERE environment = ?
              AND account_id = ?
              AND status = 'OK'
              AND COALESCE(nav,0) > 1
            ORDER BY created_at_utc DESC, id DESC
            LIMIT 1
        """, (OANDA_ENV, OANDA_ACCOUNT_ID)).fetchone()
    if not row:
        raise HTTPException(status_code=400, detail="No funded OK broker snapshot found for current OANDA env/account. Refresh dashboard after funding/account read, then retry.")
    baseline_utc = safe_str(row["created_at_utc"])
    baseline_nav = safe_float(row["nav"]) or 0.0
    key = f"broker_accounting_baseline_utc_{safe_str(OANDA_ENV)}_{safe_str(OANDA_ACCOUNT_ID)}"
    set_broker_runtime_setting(key, baseline_utc)
    set_broker_runtime_setting(f"broker_accounting_baseline_nav_{safe_str(OANDA_ENV)}_{safe_str(OANDA_ACCOUNT_ID)}", f"{baseline_nav:.8f}")
    # Also move the cashflow floor to now. This prevents an initial funding deposit
    # that was logged before the baseline reset from being subtracted as if it were
    # a trading-period cashflow. Future deposits/withdrawals after this reset will
    # still be included normally.
    cashflow_floor_utc = now_utc_iso()
    set_broker_runtime_setting(f"broker_accounting_cashflow_floor_utc_{safe_str(OANDA_ENV)}_{safe_str(OANDA_ACCOUNT_ID)}", cashflow_floor_utc)
    log_system_event("broker_accounting_baseline_reset", f"Reset broker accounting baseline for {OANDA_ENV}/{OANDA_ACCOUNT_ID} at {baseline_utc}, NAV={baseline_nav}, cashflow_floor={cashflow_floor_utc}")
    return {
        "ok": True,
        "status": "BASELINE_RESET",
        "environment": OANDA_ENV,
        "account_id": OANDA_ACCOUNT_ID,
        "baseline_utc": baseline_utc,
        "baseline_nav": baseline_nav,
        "baseline_nav_display": money(baseline_nav),
        "cashflow_floor_utc": cashflow_floor_utc,
        "message": "Broker P&L baseline reset. Future broker P&L reports start from this snapshot. Capital movements logged before this reset are treated as starting capital, not trading P&L cashflow.",
        "time_utc": now_utc_iso(),
    }

