@app.post("/broker/oanda/test/place-risk-order")
async def broker_oanda_test_place_risk_order(request: Request) -> Dict[str, Any]:
    """Manual restricted in live mode market order sized from risk_amount and sl_pct. No automatic strategy execution."""
    init_db()
    try:
        body = await request.json()
    except Exception:
        body = {}

    preview = build_risk_order_preview(
        instrument=body.get("instrument") or body.get("asset") or "SPX500_USD",
        side=body.get("side") or "buy",
        risk_amount=safe_float(body.get("risk_amount")) if body.get("risk_amount") is not None else None,
        sl_pct=safe_float(body.get("sl_pct")) if body.get("sl_pct") is not None else None,
    )
    if not preview.get("ok"):
        log_execution_audit_event("practice_manual", safe_str(preview.get("instrument", "")), "", "place_risk_order", False, safe_str(preview.get("error", "risk preview failed")), raw=preview)
        return {"status": "error", "ok": False, "preview": preview, "safety": oanda_safety_state(), "time_utc": now_utc_iso()}

    order_body = {
        "order": {
            "type": "MARKET",
            "instrument": preview["instrument"],
            "units": str(preview["signed_units"]),
            "timeInForce": "FOK",
            "positionFill": "DEFAULT",
        }
    }
    resp = oanda_write_request(f"/v3/accounts/{OANDA_ACCOUNT_ID}/orders", "POST", order_body)
    details = extract_oanda_execution_details(resp)
    broker_id = details.get("broker_order_id") or extract_transaction_id(resp)
    success = bool(resp.get("ok"))
    log_execution_audit_event(
        "practice_manual", preview["instrument"], details.get("broker_trade_id", ""), "place_risk_order",
        success, "manual practice risk-sized market order", broker_id, raw={"preview": preview, "response": resp},
        intended_price=safe_float(preview.get("current_mid_price")),
        actual_price=details.get("actual_price"),
        side=safe_str(preview.get("side")),
        requested_units=safe_float(preview.get("signed_units")),
        filled_units=details.get("filled_units"),
        risk_amount=safe_float(preview.get("risk_amount_requested")),
        sl_pct=safe_float(preview.get("sl_pct")),
        estimated_risk=safe_float(preview.get("estimated_risk_amount")),
        broker_trade_id=details.get("broker_trade_id", ""),
        response_status_code=details.get("response_status_code"),
    )
    return {"status": "ok" if success else "error", "ok": success, "preview": preview, "request": order_body, "response": resp, "broker_order_id": broker_id, "safety": oanda_safety_state(), "time_utc": now_utc_iso()}


@app.post("/broker/oanda/test/place-order")
async def broker_oanda_test_place_order(request: Request) -> Dict[str, Any]:
    """Manual restricted in live mode market order test. Never called by TradingView/basket logic."""
    init_db()
    try:
        body = await request.json()
    except Exception:
        body = {}

    instrument = normalise_oanda_instrument(body.get("instrument") or body.get("asset"))
    side = safe_str(body.get("side") or "buy").lower()
    units_ok, units_msg, units_val = validate_manual_oanda_units(body.get("units") or BROKER_MAX_TEST_UNITS)
    inst_ok, inst_msg = validate_manual_oanda_instrument(instrument)

    if side not in {"buy", "sell"}:
        result = {"ok": False, "blocked": True, "error": "side must be buy or sell", "safety": oanda_safety_state()}
        log_execution_audit_event("practice_manual", instrument, "", "place_order", False, result["error"], raw=result)
        return result
    if not inst_ok:
        result = {"ok": False, "blocked": True, "error": inst_msg, "safety": oanda_safety_state()}
        log_execution_audit_event("practice_manual", instrument, "", "place_order", False, inst_msg, raw=result)
        return result
    if not units_ok or units_val is None:
        result = {"ok": False, "blocked": True, "error": units_msg, "safety": oanda_safety_state()}
        log_execution_audit_event("practice_manual", instrument, "", "place_order", False, units_msg, raw=result)
        return result

    signed_units = units_val if side == "buy" else -units_val
    order_body = {
        "order": {
            "type": "MARKET",
            "instrument": instrument,
            "units": str(signed_units),
            "timeInForce": "FOK",
            "positionFill": "DEFAULT",
        }
    }
    resp = oanda_write_request(f"/v3/accounts/{OANDA_ACCOUNT_ID}/orders", "POST", order_body)
    details = extract_oanda_execution_details(resp)
    broker_id = details.get("broker_order_id") or extract_transaction_id(resp)
    log_execution_audit_event(
        "practice_manual", instrument, details.get("broker_trade_id", ""), "place_order",
        bool(resp.get("ok")), "manual practice market order", broker_id, raw=resp,
        side=side, requested_units=signed_units, filled_units=details.get("filled_units"),
        actual_price=details.get("actual_price"), broker_trade_id=details.get("broker_trade_id", ""),
        response_status_code=details.get("response_status_code"),
    )
    return {"status": "ok" if resp.get("ok") else "error", "ok": bool(resp.get("ok")), "request": order_body, "response": resp, "broker_order_id": broker_id, "safety": oanda_safety_state(), "time_utc": now_utc_iso()}


@app.post("/broker/oanda/test/close-trade")
async def broker_oanda_test_close_trade(request: Request) -> Dict[str, Any]:
    """Manual restricted in live mode trade close by OANDA trade ID."""
    init_db()
    try:
        body = await request.json()
    except Exception:
        body = {}

    trade_id = safe_str(body.get("trade_id") or body.get("tradeSpecifier"))
    units_raw = body.get("units", "ALL")
    if not trade_id:
        result = {"ok": False, "blocked": True, "error": "Missing trade_id", "safety": oanda_safety_state()}
        log_execution_audit_event("practice_manual", "", "", "close_trade", False, result["error"], raw=result)
        return result

    if safe_str(units_raw).upper() == "ALL":
        close_body = {"units": "ALL"}
    else:
        ok, msg, val = validate_manual_oanda_units(units_raw)
        if not ok or val is None:
            result = {"ok": False, "blocked": True, "error": msg, "safety": oanda_safety_state()}
            log_execution_audit_event("practice_manual", "", trade_id, "close_trade", False, msg, raw=result)
            return result
        close_body = {"units": str(val)}

    resp = oanda_write_request(f"/v3/accounts/{OANDA_ACCOUNT_ID}/trades/{urllib.parse.quote(trade_id)}/close", "PUT", close_body)
    details = extract_oanda_execution_details(resp)
    broker_id = details.get("broker_order_id") or extract_transaction_id(resp)
    log_execution_audit_event(
        "practice_manual", details.get("instrument", ""), trade_id, "close_trade",
        bool(resp.get("ok")), "manual practice close trade", broker_id, raw=resp,
        close_units=details.get("closed_units"), actual_price=details.get("actual_price"),
        broker_trade_id=details.get("broker_trade_id", ""), response_status_code=details.get("response_status_code"),
    )
    return {"status": "ok" if resp.get("ok") else "error", "ok": bool(resp.get("ok")), "request": close_body, "response": resp, "broker_order_id": broker_id, "safety": oanda_safety_state(), "time_utc": now_utc_iso()}


@app.post("/broker/oanda/test/close-position")
async def broker_oanda_test_close_position(request: Request) -> Dict[str, Any]:
    """Manual restricted in live mode close all/part of a position side for an allowed instrument."""
    init_db()
    try:
        body = await request.json()
    except Exception:
        body = {}

    instrument = normalise_oanda_instrument(body.get("instrument") or body.get("asset"))
    side = safe_str(body.get("side") or "both").lower()
    units_raw = body.get("units", "ALL")
    inst_ok, inst_msg = validate_manual_oanda_instrument(instrument)
    if not inst_ok:
        result = {"ok": False, "blocked": True, "error": inst_msg, "safety": oanda_safety_state()}
        log_execution_audit_event("practice_manual", instrument, "", "close_position", False, inst_msg, raw=result)
        return result
    if side not in {"long", "short", "both"}:
        result = {"ok": False, "blocked": True, "error": "side must be long, short, or both", "safety": oanda_safety_state()}
        log_execution_audit_event("practice_manual", instrument, "", "close_position", False, result["error"], raw=result)
        return result

    if safe_str(units_raw).upper() == "ALL":
        units_str = "ALL"
    else:
        ok, msg, val = validate_manual_oanda_units(units_raw)
        if not ok or val is None:
            result = {"ok": False, "blocked": True, "error": msg, "safety": oanda_safety_state()}
            log_execution_audit_event("practice_manual", instrument, "", "close_position", False, msg, raw=result)
            return result
        units_str = str(val)

    close_body: Dict[str, Any] = {}
    if side in {"long", "both"}:
        close_body["longUnits"] = units_str
    if side in {"short", "both"}:
        close_body["shortUnits"] = units_str

    resp = oanda_write_request(f"/v3/accounts/{OANDA_ACCOUNT_ID}/positions/{urllib.parse.quote(instrument)}/close", "PUT", close_body)
    details = extract_oanda_execution_details(resp)
    broker_id = details.get("broker_order_id") or extract_transaction_id(resp)
    log_execution_audit_event(
        "practice_manual", instrument, "", "close_position", bool(resp.get("ok")),
        "manual practice close position", broker_id, raw=resp,
        side=side, close_units=details.get("closed_units"), actual_price=details.get("actual_price"),
        broker_trade_id=details.get("broker_trade_id", ""), response_status_code=details.get("response_status_code"),
    )
    return {"status": "ok" if resp.get("ok") else "error", "ok": bool(resp.get("ok")), "request": close_body, "response": resp, "broker_order_id": broker_id, "safety": oanda_safety_state(), "time_utc": now_utc_iso()}





