# These are the preferred exports now. They avoid the old "huge all.zip" problem
# by grouping the actual jobs into two safe bundles:
# - main NAS100/US500 live analysis
# - metals research review

EXPORT_BUNDLE_DEFAULT_LIMIT = max(5000, min(int(float(os.getenv("EXPORT_BUNDLE_DEFAULT_LIMIT", str(RESEARCH_ROW_EXPORT_LIMIT)))), RESEARCH_ROW_HARD_LIMIT))
EXPORT_BUNDLE_TABLE_LIMIT = max(1000, min(int(float(os.getenv("EXPORT_BUNDLE_TABLE_LIMIT", str(EXPORT_ALL_TABLE_ROW_LIMIT)))), RESEARCH_ROW_HARD_LIMIT))


def _clean_limit(value: Any, default: int) -> int:
    return max(1, min(int(float(value or default)), RESEARCH_ROW_HARD_LIMIT))


def _row_dicts(rows: Any) -> List[Dict[str, Any]]:
    out: List[Dict[str, Any]] = []
    for r in rows or []:
        try:
            out.append(dict(r))
        except Exception:
            out.append({})
    return out


def _query_dicts(conn: Any, sql: str, params: Tuple[Any, ...] = ()) -> List[Dict[str, Any]]:
    return _row_dicts(conn.execute(sql, params).fetchall())


def _write_zip_csv(zf: zipfile.ZipFile, filename: str, rows: List[Dict[str, Any]], fallback: Optional[List[str]] = None) -> None:
    zf.writestr(filename, rows_to_csv(rows, fallback or ["note", "time_utc"]))


def _write_zip_json(zf: zipfile.ZipFile, filename: str, payload: Any) -> None:
    zf.writestr(filename, json.dumps(payload, indent=2, default=str))


def _zip_response(zip_buffer: io.BytesIO, filename: str) -> Response:
    zip_buffer.seek(0)
    return Response(
        content=zip_buffer.getvalue(),
        media_type="application/zip",
        headers={"Content-Disposition": f'attachment; filename="{filename}"'},
    )


def _filtered_raw_signals(conn: Any, variants: List[str], limit: int) -> List[Dict[str, Any]]:
    clean = [safe_str(v).upper() for v in variants if safe_str(v)]
    if not clean:
        return []
    placeholders = ",".join(["?"] * len(clean))
    return _query_dicts(conn, f"""
        SELECT *
        FROM raw_signals
        WHERE UPPER(pair) IN ({placeholders})
        ORDER BY id DESC
        LIMIT ?
    """, tuple(clean + [int(limit)]))


def _table_exists(conn: Any, table_name: str) -> bool:
    try:
        row = conn.execute("SELECT name FROM sqlite_master WHERE type='table' AND name=? LIMIT 1", (table_name,)).fetchone()
        return bool(row)
    except Exception:
        try:
            cols = conn.execute(f"PRAGMA table_info({table_name})").fetchall()
            return bool(cols)
        except Exception:
            return False


def _export_table_dicts(conn: Any, table_name: str, limit: int, newest_first: bool = True) -> List[Dict[str, Any]]:
    if not _table_exists(conn, table_name):
        return [{"note": f"Table {table_name} not available", "time_utc": now_utc_iso()}]
    table_sql = _quote_identifier(table_name)
    order_sql = ""
    try:
        cols = [str(r["name"]) for r in conn.execute(f"PRAGMA table_info({table_name})").fetchall()]
        if newest_first and "id" in cols:
            order_sql = ' ORDER BY "id" DESC'
    except Exception:
        pass
    return _query_dicts(conn, f"SELECT * FROM {table_sql}{order_sql} LIMIT ?", (int(limit),))


def _flatten_metals_deep_rows(limit: int) -> List[Dict[str, Any]]:
    rows: List[Dict[str, Any]] = []
    long_rows = build_metals_research_outcomes(limit=limit, candidates_only=False)
    short_rows = build_metals_short_research_outcomes(limit=limit, candidates_only=False)
    for r in long_rows:
        d = dict(r); d["row_group"] = "metals_long_outcome"; rows.append(d)
    for r in short_rows:
        d = dict(r); d["row_group"] = "metals_short_outcome"; rows.append(d)
    if not rows:
        rows = [{"note": "No metals deep research rows available", "time_utc": now_utc_iso()}]
    return rows


def _bundle_manifest(name: str, limit: int, files: List[str], note: str = "") -> Dict[str, Any]:
    return {
        "bundle": name,
        "generated_at_utc": now_utc_iso(),
        "row_limit_per_large_section": int(limit),
        "files": files,
        "note": note,
    }


