def _metals_demo_asset(value: Any) -> str:
    a = safe_str(value).upper().replace("_", "")
    if a in {"XAU", "XAUUSD"}: return "XAUUSD"
    if a in {"XAG", "XAGUSD"}: return "XAGUSD"
    return a


def _metals_demo_instrument(asset: str) -> str:
    return {"XAUUSD": "XAU_USD", "XAGUSD": "XAG_USD"}.get(_metals_demo_asset(asset), "")


def _metals_demo_risk(asset: str) -> float:
    return METALS_DEMO_XAU_RISK_AMOUNT if _metals_demo_asset(asset) == "XAUUSD" else METALS_DEMO_XAG_RISK_AMOUNT


def _metals_demo_sl_pct(asset: str) -> float:
    return METALS_DEMO_XAU_SL_PCT if _metals_demo_asset(asset) == "XAUUSD" else METALS_DEMO_XAG_SL_PCT


def _metals_demo_spread_limit(asset: str) -> float:
    return METALS_DEMO_MAX_SPREAD_PCT_XAU if _metals_demo_asset(asset) == "XAUUSD" else METALS_DEMO_MAX_SPREAD_PCT_XAG


def _metals_demo_max_risk_overage_pct(asset: str) -> float:
    """Maximum accepted minimum-size risk overage for the isolated demo lane."""
    a = _metals_demo_asset(asset)
    if a == "XAUUSD":
        return float(METALS_DEMO_XAU_MAX_RISK_OVERAGE_PCT)
    if a == "XAGUSD":
        return float(METALS_DEMO_XAG_MAX_RISK_OVERAGE_PCT)
    return float(METALS_DEMO_MAX_RISK_OVERAGE_PCT)


_METALS_ACCOUNT_CACHE: Dict[str, Any] = {"expires_at": 0.0, "currency": "", "raw": {}}
_METALS_ACCOUNT_CACHE_LOCK = threading.Lock()


def _metals_demo_account_currency(force: bool = False) -> Dict[str, Any]:
    """Return OANDA practice account home currency, cached briefly."""
    now_ts = time.time()
    with _METALS_ACCOUNT_CACHE_LOCK:
        if not force and float(_METALS_ACCOUNT_CACHE.get("expires_at") or 0) > now_ts:
            return {
                "ok": bool(_METALS_ACCOUNT_CACHE.get("currency")),
                "currency": safe_str(_METALS_ACCOUNT_CACHE.get("currency")).upper(),
                "cached": True,
                "raw": _METALS_ACCOUNT_CACHE.get("raw") or {},
            }
    if not METALS_DEMO_OANDA_ACCOUNT_ID or not METALS_DEMO_OANDA_API_TOKEN:
        return {"ok": False, "currency": "", "error": "metals_demo_credentials_missing"}
    resp = metals_demo_request(f"/v3/accounts/{METALS_DEMO_OANDA_ACCOUNT_ID}/summary")
    account = resp.get("data", {}).get("account", {}) if resp.get("ok") else {}
    currency = safe_str(account.get("currency")).upper()
    with _METALS_ACCOUNT_CACHE_LOCK:
        _METALS_ACCOUNT_CACHE.update({"expires_at": now_ts + 60.0, "currency": currency, "raw": account})
    return {"ok": bool(resp.get("ok") and currency), "currency": currency, "cached": False, "raw": account, "response_ok": bool(resp.get("ok"))}


def _metals_home_conversion(pricing_payload: Dict[str, Any], quote_currency: str = "USD") -> Dict[str, Any]:
    """Extract quote-currency -> account-home conversion factors from OANDA pricing.

    `accountLoss` is deliberately used for risk sizing so a GBP risk limit is
    calculated on the adverse/loss conversion basis. `positionValue` is used for
    the margin/notional display where supplied.
    """
    quote = safe_str(quote_currency).upper()
    rows = pricing_payload.get("homeConversions", []) or []
    for item in rows:
        if safe_str(item.get("currency")).upper() != quote:
            continue
        account_loss = safe_float(item.get("accountLoss"))
        account_gain = safe_float(item.get("accountGain"))
        position_value = safe_float(item.get("positionValue"))
        return {
            "ok": account_loss is not None and account_loss > 0,
            "quote_currency": quote,
            "account_loss_factor": account_loss,
            "account_gain_factor": account_gain,
            "position_value_factor": position_value,
        }
    return {"ok": False, "quote_currency": quote, "error": f"home_conversion_missing_for_{quote}"}


def metals_demo_config_status() -> Dict[str, Any]:
    missing = []
    if not METALS_DEMO_OANDA_ACCOUNT_ID: missing.append("METALS_DEMO_OANDA_ACCOUNT_ID")
    if not METALS_DEMO_OANDA_API_TOKEN: missing.append("METALS_DEMO_OANDA_API_TOKEN")
    live_overlap = sorted(METALS_DEMO_ALLOWED_INSTRUMENTS.intersection(BROKER_ALLOWED_INSTRUMENTS))
    return {
        "label": METALS_DEMO_LABEL,
        "reporting_currency": METALS_REPORTING_CURRENCY,
        "cash_accounting": "GBP_NATIVE_OANDA_HOME_CONVERSION",
        "require_gbp_account": METALS_DEMO_REQUIRE_GBP_ACCOUNT,
        "enabled": METALS_DEMO_BROKER_ENABLED,
        "environment": METALS_DEMO_OANDA_ENV,
        "account_id": METALS_DEMO_OANDA_ACCOUNT_ID,
        "token_present": bool(METALS_DEMO_OANDA_API_TOKEN),
        "allowed_instruments": sorted(METALS_DEMO_ALLOWED_INSTRUMENTS),
        "live_broker_allowed_instruments": sorted(BROKER_ALLOWED_INSTRUMENTS),
        "live_instrument_overlap": live_overlap,
        "missing": missing,
        "orders_allowed": bool(
            METALS_DEMO_BROKER_ENABLED
            and METALS_DEMO_OANDA_ENV in {"practice","live"}
            and (METALS_DEMO_OANDA_ENV != "live" or METALS_LIVE_EXECUTION_ARMED)
            and not missing
            and not live_overlap
        ),
        "legacy_direction_env": METALS_DEMO_DIRECTION,
        "simulate_longs": METALS_DEMO_SIMULATE_LONGS,
        "simulate_shorts": METALS_DEMO_SIMULATE_SHORTS,
        "basket_manager_enabled": METALS_DEMO_BASKET_MANAGER_ENABLED,
        "manager_version": METALS_DEMO_MANAGER_VERSION,
        "model_version": METALS_DEMO_MODEL_VERSION,
        "risk_gbp": {"XAUUSD": METALS_DEMO_XAU_RISK_AMOUNT, "XAGUSD": METALS_DEMO_XAG_RISK_AMOUNT},
        "sl_pct": {"XAUUSD": METALS_DEMO_XAU_SL_PCT, "XAGUSD": METALS_DEMO_XAG_SL_PCT},
        "max_risk_overage_pct": {
            "XAUUSD": METALS_DEMO_XAU_MAX_RISK_OVERAGE_PCT,
            "XAGUSD": METALS_DEMO_XAG_MAX_RISK_OVERAGE_PCT,
        },
        "minimum_hold_candles": METALS_DEMO_MANAGER_MIN_HOLD_CANDLES,
        "fixed_48h_baseline_candles": METALS_DEMO_FIXED_HOLD_CANDLES,
        "hourly_review_after_min_hold": True,
        "forced_max_hold_candles": METALS_DEMO_MANAGER_MAX_HOLD_CANDLES,
        "family_overlay_execution": "ADVISORY_ONLY",
        "live_execution_armed": METALS_LIVE_EXECUTION_ARMED,
        "safety_note": "Standalone XAU/XAG ownership. Same lane supports practice or live; live writes additionally require METALS_LIVE_EXECUTION_ARMED=true.",
    }


def metals_demo_request(path: str, method: str = "GET", body: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    cfg = metals_demo_config_status()
    if cfg["missing"]:
        return {"ok": False, "blocked": True, "error": "Missing metals demo config: " + ",".join(cfg["missing"])}
    if METALS_DEMO_OANDA_ENV not in {"practice","live"}:
        return {"ok": False, "blocked": True, "error": f"Unsupported Metals OANDA environment: {METALS_DEMO_OANDA_ENV}"}
    if method.upper() != "GET" and not cfg["orders_allowed"]:
        return {"ok": False, "blocked": True, "error": "Metals demo execution disabled or live-instrument overlap detected", "config": cfg}
    clean_path = "/" + safe_str(path).lstrip("/")
    data = None if method.upper() == "GET" else json.dumps(body or {}).encode("utf-8")
    req = urllib.request.Request(
        METALS_DEMO_OANDA_API_BASE + clean_path, data=data, method=method.upper(),
        headers={"Authorization": f"Bearer {METALS_DEMO_OANDA_API_TOKEN}", "Accept": "application/json", "Content-Type": "application/json"},
    )
    try:
        with urllib.request.urlopen(req, timeout=OANDA_TIMEOUT_SECONDS) as resp:
            text = resp.read().decode("utf-8")
            return {"ok": True, "status_code": resp.status, "data": json.loads(text) if text else {}, "url_path": clean_path}
    except urllib.error.HTTPError as e:
        text = e.read().decode("utf-8", errors="replace")
        try: payload = json.loads(text) if text else {}
        except Exception: payload = {"raw_body": text}
        return {"ok": False, "status_code": e.code, "error": str(e), "data": payload, "url_path": clean_path}
    except Exception as e:
        return {"ok": False, "status_code": None, "error": str(e), "url_path": clean_path}


def cleaned_metal_short_demo_candidate(raw: Dict[str, Any], row: Any) -> Dict[str, Any]:
    base = infer_metal_short_candidate(raw, row)
    blockers: List[str] = []
    if int(base.get("short_candidate") or 0) != 1: blockers.append("generated_short_v1_not_true")
    if _raw_bool_value(row["forward_test_candidate"]): blockers.append("long_forward_candidate_true")
    pine_explicit = _raw_any_true(raw, ["pine_short", "explicit_short", "short_signal", "sell_signal", "rule_trend_short_v1", "rule_bear_continuation_v1"])
    exec_rsi = safe_float(raw.get("exec_rsi")); ctx_rsi = safe_float(raw.get("ctx_rsi")); d_rsi = safe_float(raw.get("d_rsi"))
    rsi_delta = safe_float(raw.get("exec_rsi_delta"))
    if exec_rsi is not None and exec_rsi >= METALS_DEMO_HIGH_RSI_BLOCK: blockers.append(f"high_exec_rsi_{exec_rsi:.1f}")
    if ctx_rsi is not None and ctx_rsi >= METALS_DEMO_HIGH_RSI_BLOCK: blockers.append(f"high_ctx_rsi_{ctx_rsi:.1f}")
    if d_rsi is not None and d_rsi >= 62: blockers.append(f"high_daily_rsi_{d_rsi:.1f}")
    if rsi_delta is not None and rsi_delta >= METALS_DEMO_BOUNCE_RSI_DELTA_BLOCK: blockers.append(f"rsi_bounce_delta_{rsi_delta:.1f}")
    bullish_reclaim = _raw_any_true(raw, ["exec_reclaim_ema20", "exec_bull_reclaim", "bounce_candidate", "rule_bull_reclaim_v1"])
    if (_raw_bool_value(raw.get("exec_rsi_up")) and _raw_bool_value(raw.get("ctx_rsi_up")) and _raw_bool_value(raw.get("exec_close_gt_ema20"))) or bullish_reclaim:
        blockers.append("obvious_rebound_or_bullish_reclaim")
    state = "CANDIDATE" if not blockers else ("WATCH" if int(base.get("short_watch") or 0) else "BLOCKED")
    return {
        **base,
        "demo_candidate": 1 if not blockers else 0,
        "demo_state": state,
        "demo_reason": "generated_short_v1_true; cleaned_v2_bounce_filters_passed" if not blockers else "",
        "demo_blockers": "; ".join(blockers),
        "pine_explicit_short_comparison": 1 if pine_explicit else 0,
        "model_version": METALS_DEMO_MODEL_VERSION,
        "rsi": {"exec": exec_rsi, "context": ctx_rsi, "daily": d_rsi, "exec_delta": rsi_delta},
    }



def cleaned_metal_long_demo_candidate(raw: Dict[str, Any], row: Any) -> Dict[str, Any]:
    """Promote the existing long forward candidate to practice simulation only."""
    blockers: List[str] = []
    forward = _raw_bool_value(row["forward_test_candidate"])
    take = _raw_bool_value(row["take_trade"])
    d_bull_present = "d_bull" in raw and safe_str(raw.get("d_bull")) != ""
    d_bull = _raw_bool_value(raw.get("d_bull"))
    d_bear = _raw_bool_value(raw.get("d_bear"))
    if not forward: blockers.append("long_forward_candidate_not_true")
    if d_bull_present and not d_bull: blockers.append("daily_bull_not_true")
    if d_bear and not d_bull: blockers.append("daily_bear_active")
    state = "CANDIDATE" if not blockers else ("WATCH" if take else "BLOCKED")
    return {
        "demo_candidate": 1 if not blockers else 0, "demo_side": "long", "demo_state": state,
        "demo_reason": "existing_long_forward_candidate_true" if not blockers else "",
        "demo_blockers": "; ".join(blockers), "long_forward_candidate": 1 if forward else 0,
        "long_take_trade": 1 if take else 0, "d_bull": 1 if d_bull else 0, "d_bear": 1 if d_bear else 0,
        "model_version": "metal_long_existing_forward_candidate_demo",
    }


def metals_demo_candidate_for_row(raw: Dict[str, Any], row: Any) -> Dict[str, Any]:
    long_c = cleaned_metal_long_demo_candidate(raw, row)
    short_c = cleaned_metal_short_demo_candidate(raw, row)
    if METALS_DEMO_SIMULATE_LONGS and int(long_c.get("demo_candidate") or 0) == 1:
        return {**long_c, "long_candidate_detail": long_c, "short_candidate_detail": short_c}
    if METALS_DEMO_SIMULATE_SHORTS and int(short_c.get("demo_candidate") or 0) == 1:
        return {**short_c, "demo_side": "short", "long_candidate_detail": long_c, "short_candidate_detail": short_c}
    states=[]
    if METALS_DEMO_SIMULATE_LONGS: states.append(f"long:{safe_str(long_c.get('demo_state'))}:{safe_str(long_c.get('demo_blockers'))}")
    if METALS_DEMO_SIMULATE_SHORTS: states.append(f"short:{safe_str(short_c.get('demo_state'))}:{safe_str(short_c.get('demo_blockers'))}")
    return {"demo_candidate":0,"demo_side":"","demo_state":"WATCH" if "WATCH" in "|".join(states) else "BLOCKED",
            "demo_reason":"","demo_blockers":" | ".join(states),"model_version":METALS_DEMO_MANAGER_VERSION,
            "long_candidate_detail":long_c,"short_candidate_detail":short_c}


def _median_numeric(values: List[Any]) -> Optional[float]:
    nums = sorted(float(v) for v in (safe_float(x) for x in values) if v is not None)
    if not nums:
        return None
    mid = len(nums) // 2
    return nums[mid] if len(nums) % 2 else (nums[mid - 1] + nums[mid]) / 2.0


def build_metals_short_shadow_v2_outcomes(
    limit: int = RESEARCH_ROW_DEFAULT_LIMIT,
    state_filter: str = "",
) -> List[Dict[str, Any]]:
    """Distinct cleaned Metals Short Shadow v2 research export."""
    init_db()
    limit = max(1, min(int(limit or RESEARCH_ROW_DEFAULT_LIMIT), RESEARCH_ROW_HARD_LIMIT))
    requested_state = safe_str(state_filter).upper()
    base_rows = build_metals_short_research_outcomes(
        limit=min(RESEARCH_ROW_HARD_LIMIT, max(limit * 5, limit)),
        candidates_only=False,
    )
    signal_ids = [int(r.get("signal_id") or 0) for r in base_rows if int(r.get("signal_id") or 0) > 0]
    raw_by_id, links_by_signal, audits_by_signal = {}, {}, {}

    with get_conn() as conn:
        for start in range(0, len(signal_ids), 500):
            chunk = signal_ids[start:start + 500]
            if not chunk:
                continue
            placeholders = ",".join(["?"] * len(chunk))
            for row in conn.execute(
                f"""SELECT id, received_at_utc, pair, timestamp_readable, exec_close,
                           exec_high, exec_low, forward_test_candidate, take_trade, raw_json
                    FROM raw_signals WHERE id IN ({placeholders})""",
                tuple(chunk),
            ).fetchall():
                raw_by_id[int(row["id"])] = row
            for link in conn.execute(
                f"SELECT * FROM metals_demo_trade_links WHERE raw_signal_id IN ({placeholders}) ORDER BY id DESC",
                tuple(chunk),
            ).fetchall():
                d = dict(link); rid = int(d.get("raw_signal_id") or 0)
                if rid and rid not in links_by_signal:
                    links_by_signal[rid] = d
            for audit in conn.execute(
                f"SELECT * FROM metals_demo_execution_audit WHERE raw_signal_id IN ({placeholders}) ORDER BY id ASC",
                tuple(chunk),
            ).fetchall():
                d = dict(audit); rid = int(d.get("raw_signal_id") or 0)
                audits_by_signal.setdefault(rid, []).append(d)

    out = []
    for base in base_rows:
        signal_id = int(base.get("signal_id") or 0)
        raw_row = raw_by_id.get(signal_id)
        if raw_row is None:
            continue
        clean = cleaned_metal_short_demo_candidate(_raw_signal_json(raw_row), raw_row)
        state = safe_str(clean.get("demo_state") or "BLOCKED").upper()
        aliases = {"CANDIDATES": "CANDIDATE", "WATCHES": "WATCH", "BLOCKERS": "BLOCKED"}
        if requested_state and state != aliases.get(requested_state, requested_state):
            continue

        link = links_by_signal.get(signal_id, {})
        audits = audits_by_signal.get(signal_id, [])
        latest_audit = audits[-1] if audits else {}
        entry_audit = next((a for a in reversed(audits) if safe_str(a.get("action")).lower() == "entry"), {})

        row = dict(base)
        row.update({
            "shadow_v2_export_version": METALS_SHORT_SHADOW_V2_EXPORT_VERSION,
            "shadow_v2_model_version": clean.get("model_version"),
            "generated_short_v1_candidate": int(clean.get("short_candidate") or 0),
            "generated_short_v1_watch": int(clean.get("short_watch") or 0),
            "generated_short_v1_score": clean.get("short_score"),
            "generated_short_v1_reason": clean.get("short_reason"),
            "generated_short_v1_blockers": clean.get("short_blockers"),
            "shadow_v2_candidate": int(clean.get("demo_candidate") or 0),
            "shadow_v2_watch": 1 if state == "WATCH" else 0,
            "shadow_v2_blocked": 1 if state == "BLOCKED" else 0,
            "shadow_v2_candidate_like": 1 if state in {"CANDIDATE", "WATCH"} else 0,
            "shadow_v2_state": state,
            "shadow_v2_reason": clean.get("demo_reason"),
            "shadow_v2_blockers": clean.get("demo_blockers"),
            "pine_explicit_short_comparison": int(clean.get("pine_explicit_short_comparison") or 0),
            "exec_rsi": (clean.get("rsi") or {}).get("exec"),
            "context_rsi": (clean.get("rsi") or {}).get("context"),
            "daily_rsi": (clean.get("rsi") or {}).get("daily"),
            "exec_rsi_delta": (clean.get("rsi") or {}).get("exec_delta"),
            "demo_broker_linked": 1 if link else 0,
            "demo_link_id": link.get("id"),
            "demo_broker_trade_id": link.get("broker_trade_id"),
            "demo_broker_status": link.get("status"),
            "demo_requested_risk": link.get("requested_risk"),
            "demo_estimated_risk": link.get("estimated_risk"),
            "demo_units": link.get("filled_units") or link.get("requested_units"),
            "demo_entry_price": link.get("entry_price"),
            "demo_stop_price": link.get("stop_price"),
            "demo_opened_at_utc": link.get("opened_at_utc"),
            "demo_closed_at_utc": link.get("closed_at_utc"),
            "demo_close_reason": link.get("close_reason"),
            "demo_last_unrealized_pl": link.get("last_known_unrealized_pl"),
            "demo_realized_pl": link.get("realized_pl"),
            "demo_latest_audit_action": latest_audit.get("action"),
            "demo_latest_audit_status": latest_audit.get("status"),
            "demo_latest_audit_message": latest_audit.get("message"),
            "demo_entry_audit_status": entry_audit.get("status"),
            "demo_entry_audit_message": entry_audit.get("message"),
            "demo_audit_event_count": len(audits),
        })
        out.append(row)
        if len(out) >= limit:
            break
    return out


def summarise_metals_short_shadow_v2(rows: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    result = []
    assets = sorted({safe_str(r.get("asset")).upper() for r in rows if safe_str(r.get("asset"))})
    for asset in assets:
        asset_rows = [r for r in rows if safe_str(r.get("asset")).upper() == asset]
        for state in ["ALL", "CANDIDATE", "WATCH", "BLOCKED"]:
            subset = asset_rows if state == "ALL" else [r for r in asset_rows if safe_str(r.get("shadow_v2_state")).upper() == state]
            if not subset:
                continue
            matured = [r for r in subset if int(r.get("has_48h") or 0) == 1]
            returns = [safe_float(r.get("return_48h_pct")) for r in matured]
            returns = [v for v in returns if v is not None]
            sl_pct = metal_research_sl_pct(asset)
            rvals = [float(v) / float(sl_pct) for v in returns if sl_pct]
            maes = [safe_float(r.get("mae_48h_pct")) for r in matured]
            maes = [v for v in maes if v is not None]
            mfes = [safe_float(r.get("mfe_48h_pct")) for r in matured]
            mfes = [v for v in mfes if v is not None]
            linked = [r for r in subset if int(r.get("demo_broker_linked") or 0) == 1]
            realised = [safe_float(r.get("demo_realized_pl")) for r in linked]
            realised = [v for v in realised if v is not None]
            result.append({
                "asset": asset,
                "shadow_v2_state": state,
                "rows": len(subset),
                "matured_48h": len(matured),
                "avg_return_48h_pct": sum(returns) / len(returns) if returns else None,
                "median_return_48h_pct": _median_numeric(returns),
                "avg_R_48h": sum(rvals) / len(rvals) if rvals else None,
                "median_R_48h": _median_numeric(rvals),
                "win_rate_48h_pct": sum(1 for v in returns if v > 0) / len(returns) * 100 if returns else None,
                "avg_mfe_48h_pct": sum(mfes) / len(mfes) if mfes else None,
                "avg_mae_48h_pct": sum(maes) / len(maes) if maes else None,
                "sl_pressure_rate_48h_pct": sum(1 for v in maes if v <= -abs(sl_pct)) / len(maes) * 100 if maes else None,
                "pine_explicit_short_rows": sum(1 for r in subset if int(r.get("pine_explicit_short_comparison") or 0) == 1),
                "demo_broker_linked_rows": len(linked),
                "demo_realised_rows": len(realised),
                "demo_realised_pl_total": sum(realised) if realised else 0.0,
                "model_version": METALS_SHORT_SHADOW_V2_EXPORT_VERSION,
            })
    return result


def _metals_demo_side(value: Any) -> str:
    return "long" if safe_str(value).lower() in {"long","buy"} else "short"


def metals_demo_sizing_preview(asset: str, side: str = "short") -> Dict[str, Any]:
    asset = _metals_demo_asset(asset)
    side = _metals_demo_side(side)
    instrument = _metals_demo_instrument(asset)
    requested_risk_gbp = _metals_demo_risk(asset)
    sl_pct = _metals_demo_sl_pct(asset)
    max_overage_pct = _metals_demo_max_risk_overage_pct(asset)
    out = {
        "ok": False,
        "asset": asset,
        "instrument": instrument,
        "side": side,
        "reporting_currency": "GBP",
        "requested_risk_gbp": requested_risk_gbp,
        "risk_amount": requested_risk_gbp,  # DB/backwards-compatible value; now explicitly GBP
        "sl_pct": sl_pct,
        "max_accepted_risk_overage_pct": max_overage_pct,
        "label": METALS_DEMO_LABEL,
        "warnings": [],
        "blocking_reasons": [],
    }
    if instrument not in METALS_DEMO_ALLOWED_INSTRUMENTS:
        out["blocking_reasons"].append("instrument_not_in_metals_demo_allowlist")
        out["warnings"].append("instrument_not_in_metals_demo_allowlist")
        out["executable"] = False
        return out

    account_status = _metals_demo_account_currency()
    account_currency = safe_str(account_status.get("currency")).upper()
    out["oanda_account_currency"] = account_currency
    if METALS_DEMO_REQUIRE_GBP_ACCOUNT and account_currency != "GBP":
        out["blocking_reasons"].append(f"oanda_account_currency_not_gbp:{account_currency or 'UNKNOWN'}")
        out["warnings"].append("oanda_account_must_be_gbp")
        out["executable"] = False
        return out

    meta_resp = metals_demo_request(
        f"/v3/accounts/{METALS_DEMO_OANDA_ACCOUNT_ID}/instruments?instruments={urllib.parse.quote(instrument)}"
    )
    price_resp = metals_demo_request(
        f"/v3/accounts/{METALS_DEMO_OANDA_ACCOUNT_ID}/pricing?instruments={urllib.parse.quote(instrument)}&includeHomeConversions=true"
    )
    metas = meta_resp.get("data", {}).get("instruments", []) if meta_resp.get("ok") else []
    pricing_payload = price_resp.get("data", {}) if price_resp.get("ok") else {}
    prices = pricing_payload.get("prices", []) or []
    conversion = _metals_home_conversion(pricing_payload, "USD")
    if not metas or not prices:
        out["blocking_reasons"].append("instrument_metadata_or_price_unavailable")
        out["warnings"].append("instrument_metadata_or_price_unavailable")
        out["executable"] = False
        return out
    if not conversion.get("ok"):
        out["blocking_reasons"].append("usd_to_gbp_home_conversion_unavailable")
        out["warnings"].append("cannot_calculate_gbp_risk_without_oanda_home_conversion")
        out["conversion"] = conversion
        out["executable"] = False
        return out

    meta, price = metas[0], prices[0]
    bid = safe_float((price.get("bids") or [{}])[0].get("price"))
    ask = safe_float((price.get("asks") or [{}])[0].get("price"))
    if bid is None or ask is None or bid <= 0 or ask <= 0:
        out["blocking_reasons"].append("invalid_bid_ask")
        out["warnings"].append("invalid_bid_ask")
        out["executable"] = False
        return out

    entry = ask if side == "long" else bid
    mid = (bid + ask) / 2
    spread_pct = (ask - bid) / mid * 100 if mid else None
    stop = entry * (1 - sl_pct / 100) if side == "long" else entry * (1 + sl_pct / 100)

    # Instrument is USD-quoted, so convert stop-distance USD -> GBP before sizing.
    stop_distance_usd_per_unit = abs(entry - stop)
    usd_to_gbp_loss = float(conversion["account_loss_factor"])
    stop_distance_gbp_per_unit = stop_distance_usd_per_unit * usd_to_gbp_loss

    min_units = safe_float(meta.get("minimumTradeSize")) or 1.0
    precision = int(safe_float(meta.get("tradeUnitsPrecision")) or 0)
    step = 10 ** (-precision)
    raw_units = requested_risk_gbp / stop_distance_gbp_per_unit if stop_distance_gbp_per_unit > 0 else 0
    floored = int(raw_units / step) * step if step > 0 else raw_units
    units = max(min_units, floored)

    estimated_risk_gbp = units * stop_distance_gbp_per_unit
    estimated_risk_usd_reference = units * stop_distance_usd_per_unit
    overage = ((estimated_risk_gbp - requested_risk_gbp) / requested_risk_gbp * 100) if requested_risk_gbp else 0
    margin_rate = safe_float(meta.get("marginRate"))
    notional_usd = units * entry
    position_value_factor = safe_float(conversion.get("position_value_factor")) or usd_to_gbp_loss
    estimated_margin_gbp = notional_usd * (margin_rate or 0) * position_value_factor

    if spread_pct is not None and spread_pct > _metals_demo_spread_limit(asset):
        out["blocking_reasons"].append("spread_over_limit")
        out["warnings"].append("spread_over_limit")

    minimum_size_applied = bool(units == min_units and raw_units < min_units)
    if minimum_size_applied and overage > 0:
        if overage > max_overage_pct:
            out["blocking_reasons"].append("minimum_size_risk_overage_above_asset_limit")
            out["warnings"].append("minimum_size_risk_overage")
        else:
            out["warnings"].append("minimum_size_risk_overage_accepted_demo_only")

    out.update({
        "ok": True,
        "bid": bid,
        "ask": ask,
        "entry_price_usd": entry,
        "entry_price": entry,
        "mid_price_usd": mid,
        "spread_pct": spread_pct,
        "spread_limit_pct": _metals_demo_spread_limit(asset),
        "stop_price_usd": stop,
        "stop_price": stop,
        "minimum_trade_size": min_units,
        "minimum_size_applied": minimum_size_applied,
        "trade_units_precision": precision,
        "unit_step": step,
        "raw_units": raw_units,
        "units": units,
        "requested_risk_gbp": requested_risk_gbp,
        "estimated_risk_gbp": estimated_risk_gbp,
        "estimated_risk_usd_reference": estimated_risk_usd_reference,
        "stop_distance_usd_per_unit": stop_distance_usd_per_unit,
        "stop_distance_gbp_per_unit": stop_distance_gbp_per_unit,
        "usd_to_gbp_account_loss_factor": usd_to_gbp_loss,
        "actual_to_requested_risk_multiple": estimated_risk_gbp / requested_risk_gbp if requested_risk_gbp else None,
        "estimated_risk_overage_pct": overage,
        "max_accepted_risk_overage_pct": max_overage_pct,
        "risk_overage_accepted": bool(minimum_size_applied and overage > 0 and overage <= max_overage_pct),
        "margin_rate": margin_rate,
        "estimated_margin_gbp": estimated_margin_gbp,
        "display_precision": int(safe_float(meta.get("displayPrecision")) or 3),
        "cash_accounting_note": "Risk/margin are converted from USD quote values into GBP using OANDA homeConversions; broker P&L is GBP because the practice account is required to be GBP.",
    })
    out["executable"] = bool(not out["blocking_reasons"] and metals_demo_config_status()["orders_allowed"])
    return out


def _metals_demo_audit(raw_signal_id: int, asset: str, instrument: str, action: str, status: str, message: str, preview: Optional[Dict[str, Any]] = None, response: Optional[Dict[str, Any]] = None, link_id: Optional[int] = None, candidate_state: str = "") -> int:
    preview = preview or {}; response = response or {}; data = response.get("data", {}) if isinstance(response, dict) else {}
    fill = data.get("orderFillTransaction") or {}; create = data.get("orderCreateTransaction") or {}
    with get_conn() as conn:
        audit_id = db_insert_returning_id(conn, """
            INSERT INTO metals_demo_execution_audit (
                created_at_utc, raw_signal_id, link_id, asset, instrument, action, status, candidate_state, message,
                requested_risk_amount, estimated_risk_amount, requested_units, actual_units, spread_pct,
                entry_price, stop_price, broker_trade_id, broker_order_id, response_status_code, raw_json
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """, (
            now_utc_iso(), raw_signal_id, link_id, asset, instrument, action, status, candidate_state, message,
            preview.get("risk_amount"), preview.get("estimated_risk_gbp"), preview.get("units"), safe_float(fill.get("units")),
            preview.get("spread_pct"), safe_float(fill.get("price")) or preview.get("bid"), preview.get("stop_price"),
            safe_str((fill.get("tradeOpened") or {}).get("tradeID")), safe_str(fill.get("id") or create.get("id")),
            response.get("status_code"), json.dumps({"preview": preview, "response": response}, default=str),
        ))
        conn.commit(); return audit_id



def _metals_parse_signal_dt(value: Any) -> Optional[datetime]:
    try:
        dt = parse_signal_candle_dt(safe_str(value))
        if dt:
            return dt
    except Exception:
        pass
    s = safe_str(value)
    if not s:
        return None
    try:
        dt = datetime.fromisoformat(s.replace("Z", "+00:00"))
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return dt
    except Exception:
        return None


def _metals_candidate_side_for_row(row: Any) -> str:
    if not row:
        return ""
    try:
        c = metals_demo_candidate_for_row(_raw_signal_json(row), row)
        if c.get("demo_candidate"):
            return _metals_demo_side(c.get("demo_side"))
    except Exception:
        return ""
    return ""


def _xag_active_campaign_state(conn: Any, side: str) -> Dict[str, Any]:
    """
    Campaign remains active until the XAG basket for this direction is flat.
    The first 10 allowance is therefore based on entries made since the oldest
    still-open XAG trade in that campaign, not simply the current open count.
    """
    side = _metals_demo_side(side)
    open_row = conn.execute("""
        SELECT MIN(signal_time) AS campaign_start, COUNT(*) AS open_count
        FROM metals_demo_trade_links
        WHERE asset='XAGUSD'
          AND LOWER(side)=?
          AND status='OPEN'
    """, (side,)).fetchone()

    open_count = int((open_row["open_count"] if open_row else 0) or 0)
    campaign_start = safe_str(open_row["campaign_start"] if open_row else "")
    if open_count <= 0 or not campaign_start:
        return {
            "active": False,
            "campaign_start": "",
            "open_count": 0,
            "entry_count": 0,
        }

    count_row = conn.execute("""
        SELECT COUNT(*) AS c
        FROM metals_demo_trade_links
        WHERE asset='XAGUSD'
          AND LOWER(side)=?
          AND signal_time>=?
    """, (side, campaign_start)).fetchone()

    return {
        "active": True,
        "campaign_start": campaign_start,
        "open_count": open_count,
        "entry_count": int((count_row["c"] if count_row else 0) or 0),
    }


def metals_xag_xau_confirmation_guard(
    conn: Any,
    signal_row: Any,
    candidate: Dict[str, Any],
) -> Dict[str, Any]:
    asset = _metals_demo_asset(signal_row["pair"])
    signal_time = safe_str(signal_row["timestamp_readable"])
    side = _metals_demo_side(candidate.get("demo_side"))
    cap = int(METALS_DEMO_XAG_SOLO_CAMPAIGN_CAP)
    lookback = float(METALS_DEMO_XAU_CONFIRMATION_LOOKBACK_HOURS)

    base = {
        "enabled": bool(METALS_DEMO_XAG_XAU_CONFIRMATION_ENABLED),
        "asset": asset,
        "side": side,
        "signal_time": signal_time,
        "solo_cap": cap,
        "lookback_hours": lookback,
        "allow": True,
        "xau_confirmation_found": False,
    }

    # XAU is deliberately unrestricted.
    if asset != "XAGUSD":
        return {**base, "reason": "xau_unrestricted_or_non_xag"}

    if not METALS_DEMO_XAG_XAU_CONFIRMATION_ENABLED:
        result = {**base, "reason": "xag_xau_confirmation_disabled"}
        _record_xag_guard_decision(conn, signal_row, result)
        return result

    campaign = _xag_active_campaign_state(conn, side)
    count_before = int(campaign.get("entry_count") or 0)
    base.update({
        "active_campaign": bool(campaign.get("active")),
        "campaign_start_time": safe_str(campaign.get("campaign_start")),
        "campaign_entry_count_before": count_before,
        "campaign_open_count": int(campaign.get("open_count") or 0),
    })

    # A flat XAG side starts a fresh campaign. Entries 1..10 are independent.
    if count_before < cap:
        result = {
            **base,
            "allow": True,
            "reason": f"xag_independent_allowance_{count_before+1}_of_{cap}",
            "decision": "ALLOW_SOLO",
        }
        _record_xag_guard_decision(conn, signal_row, result)
        return result

    current_dt = _metals_parse_signal_dt(signal_time)
    if not current_dt:
        # Fail open rather than accidentally blocking execution because of a
        # timestamp-format defect. The decision remains auditable.
        result = {
            **base,
            "allow": True,
            "reason": "signal_time_unparseable_fail_open",
            "decision": "ALLOW_TIMESTAMP_FAIL_OPEN",
        }
        _record_xag_guard_decision(conn, signal_row, result)
        return result

    # Search recent XAU signals and evaluate the *actual Metals demo candidate
    # logic* so a raw Pine flag alone cannot unlock Silver incorrectly.
    recent_xau = conn.execute("""
        SELECT *
        FROM raw_signals
        WHERE UPPER(pair) IN ('XAUUSD','XAU')
          AND id<=?
        ORDER BY id DESC
        LIMIT 24
    """, (int(signal_row["id"]),)).fetchall()

    confirmation = None
    for xrow in recent_xau:
        xdt = _metals_parse_signal_dt(xrow["timestamp_readable"])
        if not xdt:
            continue
        age_h = (current_dt - xdt).total_seconds() / 3600.0
        if age_h < 0:
            continue
        if age_h > lookback:
            # Rows are newest-first; older rows cannot qualify.
            continue
        xside = _metals_candidate_side_for_row(xrow)
        if xside == side:
            confirmation = {
                "raw_signal_id": int(xrow["id"]),
                "time": safe_str(xrow["timestamp_readable"]),
                "side": xside,
                "age_hours": age_h,
            }
            break

    if confirmation:
        result = {
            **base,
            "allow": True,
            "xau_confirmation_found": True,
            "xau_confirmation_raw_signal_id": confirmation["raw_signal_id"],
            "xau_confirmation_time": confirmation["time"],
            "xau_confirmation_side": confirmation["side"],
            "xau_confirmation_age_hours": confirmation["age_hours"],
            "reason": f"xau_{side}_candidate_within_{lookback:g}h",
            "decision": "ALLOW_XAU_CONFIRMED",
        }
    else:
        result = {
            **base,
            "allow": False,
            "reason": (
                f"xag_campaign_entries_{count_before}_ge_cap_{cap};"
                f"no_same_direction_xau_{side}_candidate_within_{lookback:g}h"
            ),
            "decision": "BLOCK_WAIT_XAU_CONFIRMATION",
        }

    _record_xag_guard_decision(conn, signal_row, result)
    return result


def _record_xag_guard_decision(conn: Any, signal_row: Any, result: Dict[str, Any]) -> None:
    try:
        conn.execute("""
            INSERT INTO metals_demo_xag_confirmation_guard (
                created_at_utc,raw_signal_id,signal_time,xag_side,enabled,solo_cap,lookback_hours,
                active_campaign,campaign_start_time,campaign_entry_count_before,
                xau_confirmation_found,xau_confirmation_raw_signal_id,xau_confirmation_time,
                xau_confirmation_side,xau_confirmation_age_hours,allow_entry,decision,reason,
                updated_at_utc
            ) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
            ON CONFLICT(raw_signal_id) DO UPDATE SET
                updated_at_utc=excluded.updated_at_utc,
                xau_confirmation_found=excluded.xau_confirmation_found,
                xau_confirmation_raw_signal_id=excluded.xau_confirmation_raw_signal_id,
                xau_confirmation_time=excluded.xau_confirmation_time,
                xau_confirmation_side=excluded.xau_confirmation_side,
                xau_confirmation_age_hours=excluded.xau_confirmation_age_hours,
                allow_entry=excluded.allow_entry,
                decision=excluded.decision,
                reason=excluded.reason
        """, (
            now_utc_iso(), int(signal_row["id"]), safe_str(signal_row["timestamp_readable"]),
            safe_str(result.get("side")), 1 if result.get("enabled") else 0,
            int(result.get("solo_cap") or 0), safe_float(result.get("lookback_hours")),
            1 if result.get("active_campaign") else 0, safe_str(result.get("campaign_start_time")),
            int(result.get("campaign_entry_count_before") or 0),
            1 if result.get("xau_confirmation_found") else 0,
            result.get("xau_confirmation_raw_signal_id"), safe_str(result.get("xau_confirmation_time")),
            safe_str(result.get("xau_confirmation_side")), safe_float(result.get("xau_confirmation_age_hours")),
            1 if result.get("allow") else 0, safe_str(result.get("decision")),
            safe_str(result.get("reason")), now_utc_iso()
        ))
        conn.commit()
    except Exception:
        # Guard logging must never break execution.
        pass


def update_xag_guard_counterfactual_outcomes(raw_signal_id: int) -> None:
    """
    Research-only outcome capture for XAG candidates that reached this guard.
    Uses the same 3.5? No: uses the configured XAG SL% so results stay in R.
    """
    try:
        with get_conn() as conn:
            guard = conn.execute("""
                SELECT * FROM metals_demo_xag_confirmation_guard
                WHERE raw_signal_id=? LIMIT 1
            """, (int(raw_signal_id),)).fetchone()
            sig = conn.execute("SELECT * FROM raw_signals WHERE id=? LIMIT 1", (int(raw_signal_id),)).fetchone()
            if not guard or not sig:
                return
            entry = safe_float(sig["exec_close"])
            if entry is None or entry <= 0:
                return
            side = _metals_demo_side(guard["xag_side"])
            path = _metals_demo_path(conn, "XAGUSD", int(raw_signal_id), limit=120)
            updates = []
            vals = []
            for horizon in (48,72,96):
                col = f"outcome_{horizon}h_r"
                if safe_float(guard[col]) is None and len(path) >= horizon:
                    px = safe_float(path[horizon-1].get("exec_close"))
                    rr = _metals_demo_r_from_price(side, float(entry), px, _metals_demo_sl_pct("XAGUSD"))
                    updates.append(f"{col}=?")
                    vals.append(rr)
            if updates:
                updates.append("updated_at_utc=?")
                vals.extend([now_utc_iso(), int(raw_signal_id)])
                conn.execute(
                    f"UPDATE metals_demo_xag_confirmation_guard SET {', '.join(updates)} WHERE raw_signal_id=?",
                    tuple(vals)
                )
                conn.commit()
    except Exception:
        pass

def execute_metals_demo_candidate(raw_signal_id: int, source: str = "signal_worker") -> Dict[str, Any]:
    init_db()
    with get_conn() as conn:
        row=conn.execute("SELECT * FROM raw_signals WHERE id=? LIMIT 1",(int(raw_signal_id),)).fetchone()
        if not row: return {"ok":False,"error":"raw_signal_not_found"}
        asset=_metals_demo_asset(row["pair"]); instrument=_metals_demo_instrument(asset)
        if asset not in {"XAUUSD","XAGUSD"}: return {"ok":True,"skipped":True,"reason":"non_metal_asset"}
        existing=conn.execute("SELECT * FROM metals_demo_trade_links WHERE raw_signal_id=? LIMIT 1",(int(raw_signal_id),)).fetchone()
        if existing: return {"ok":True,"duplicate":True,"link_id":existing["id"],"status":existing["status"],"asset":asset}
        candidate=metals_demo_candidate_for_row(_raw_signal_json(row),row)
    if not candidate.get("demo_candidate"):
        _metals_demo_audit(raw_signal_id,asset,instrument,"candidate_evaluation","BLOCKED",candidate.get("demo_blockers") or "not_candidate",candidate_state=candidate.get("demo_state"))
        return {"ok":True,"skipped":True,"asset":asset,"candidate":candidate}
    side=_metals_demo_side(candidate.get("demo_side"))

    # v1.3.1 asymmetric correlation guard:
    # XAU unrestricted; XAG 11th+ campaign entry needs same-direction XAU <=6h.
    with get_conn() as conn:
        confirmation_guard = metals_xag_xau_confirmation_guard(conn, row, candidate)
    if asset == "XAGUSD" and not confirmation_guard.get("allow", True):
        _metals_demo_audit(
            raw_signal_id, asset, instrument, "entry_confirmation_guard", "BLOCKED",
            safe_str(confirmation_guard.get("reason")),
            candidate_state=safe_str(candidate.get("demo_state") or "CANDIDATE")
        )
        return {
            "ok": True,
            "blocked": True,
            "asset": asset,
            "side": side,
            "reason": "xag_requires_recent_same_direction_xau_confirmation",
            "confirmation_guard": confirmation_guard,
            "candidate": candidate,
        }

    preview=metals_demo_sizing_preview(asset,side)
    if not METALS_DEMO_BROKER_ENABLED:
        _metals_demo_audit(raw_signal_id,asset,instrument,"entry_preview","DISABLED_PREVIEW_ONLY","METALS_DEMO_BROKER_ENABLED=false",preview,candidate_state="CANDIDATE")
        return {"ok":True,"preview_only":True,"asset":asset,"side":side,"candidate":candidate,"preview":preview}
    with get_conn() as conn:
        count=conn.execute("SELECT COUNT(*) AS c FROM metals_demo_trade_links WHERE asset=? AND status='OPEN'",(asset,)).fetchone()["c"]
        opposite=conn.execute("SELECT COUNT(*) AS c FROM metals_demo_trade_links WHERE asset=? AND status='OPEN' AND LOWER(side) != ?",(asset,side)).fetchone()["c"]
    if int(count or 0)>=METALS_DEMO_MAX_OPEN_TRADES_PER_ASSET: return {"ok":False,"blocked":True,"asset":asset,"reason":"max_open_trades_per_asset","preview":preview}
    if METALS_DEMO_BLOCK_OPPOSITE_DIRECTION_SAME_ASSET and int(opposite or 0)>0:
        _metals_demo_audit(raw_signal_id,asset,instrument,"entry","BLOCKED","opposite_direction_open_guard_prevents_oanda_netting",preview,candidate_state="CANDIDATE")
        return {"ok":True,"blocked":True,"asset":asset,"side":side,"reason":"opposite_direction_open_guard_prevents_oanda_netting","preview":preview}
    if not preview.get("executable"):
        _metals_demo_audit(raw_signal_id,asset,instrument,"entry","BLOCKED",";".join(preview.get("warnings") or ["preview_not_executable"]),preview,candidate_state="CANDIDATE")
        return {"ok":False,"blocked":True,"asset":asset,"side":side,"reason":"preview_not_executable","preview":preview}
    units=abs(float(preview["units"])) if side=="long" else -abs(float(preview["units"])); dp=int(preview.get("display_precision") or 3)
    body={"order":{"units":str(units),"instrument":instrument,"timeInForce":"FOK","type":"MARKET","positionFill":"DEFAULT",
                   "stopLossOnFill":{"price":f"{float(preview['stop_price']):.{dp}f}","timeInForce":"GTC"}}}
    response=metals_demo_request(f"/v3/accounts/{METALS_DEMO_OANDA_ACCOUNT_ID}/orders","POST",body); data=response.get("data",{}); fill=data.get("orderFillTransaction") or {}; opened=fill.get("tradeOpened") or {}
    broker_trade_id=safe_str(opened.get("tradeID")); broker_order_id=safe_str(fill.get("id") or (data.get("orderCreateTransaction") or {}).get("id"))
    if not response.get("ok") or not broker_trade_id:
        _metals_demo_audit(raw_signal_id,asset,instrument,"entry","FAILED",safe_str(response.get("error") or data),preview,response,candidate_state="CANDIDATE"); return {"ok":False,"asset":asset,"side":side,"response":response,"preview":preview}
    with get_conn() as conn:
        er=conn.execute("SELECT timestamp_readable FROM raw_signals WHERE id=?",(raw_signal_id,)).fetchone(); fill_units=abs(safe_float(fill.get("units")) or preview.get("units") or 0); fill_price=safe_float(fill.get("price")) or preview.get("entry_price")
        link_id=db_insert_returning_id(conn,"""INSERT INTO metals_demo_trade_links (created_at_utc,updated_at_utc,raw_signal_id,asset,instrument,side,model_version,signal_time,entry_signal_id,requested_risk_amount,estimated_risk_amount,requested_units,filled_units,entry_price,stop_price,current_stop_price,broker_trade_id,broker_order_id,status,raw_json) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
            (now_utc_iso(),now_utc_iso(),raw_signal_id,asset,instrument,side,safe_str(candidate.get("model_version") or METALS_DEMO_MANAGER_VERSION),safe_str(er["timestamp_readable"] if er else ""),raw_signal_id,preview.get("risk_amount"),preview.get("estimated_risk_gbp"),preview.get("units"),fill_units,fill_price,preview.get("stop_price"),preview.get("stop_price"),broker_trade_id,broker_order_id,"OPEN",json.dumps({"candidate":candidate,"confirmation_guard":confirmation_guard,"preview":preview,"response":response},default=str)))
        conn.commit()
    _metals_demo_audit(raw_signal_id,asset,instrument,"entry","OPENED",f"practice {side} trade opened from {source}",preview,response,link_id,"CANDIDATE")
    return {"ok":True,"opened":True,"asset":asset,"side":side,"link_id":link_id,"broker_trade_id":broker_trade_id,"preview":preview,"candidate":candidate}


def _metals_demo_pair_variants(asset: str) -> Tuple[str, str]:
    a=_metals_demo_asset(asset); return a,a.replace("USD","")

def _metals_demo_latest_signal_row(conn: Any, asset: str) -> Any:
    a,b=_metals_demo_pair_variants(asset); return conn.execute("SELECT * FROM raw_signals WHERE UPPER(pair) IN (?,?) ORDER BY id DESC LIMIT 1",(a,b)).fetchone()

def _metals_demo_path(conn: Any, asset: str, entry_signal_id: int, limit: int=1000) -> List[Dict[str, Any]]:
    a,b=_metals_demo_pair_variants(asset); return [dict(r) for r in conn.execute("SELECT id,timestamp_readable,exec_close,exec_high,exec_low,forward_test_candidate,take_trade,raw_json FROM raw_signals WHERE UPPER(pair) IN (?,?) AND id>? ORDER BY id ASC LIMIT ?",(a,b,int(entry_signal_id or 0),int(limit))).fetchall()]

def _metals_demo_r_from_price(side: str, entry: float, price: Any, sl_pct: float) -> Optional[float]:
    p=safe_float(price)
    if p is None or entry<=0 or sl_pct<=0: return None
    ret=(p/entry-1)*100; ret=-ret if _metals_demo_side(side)=="short" else ret; return ret/sl_pct

def _metals_demo_trade_metrics(link: Dict[str, Any]) -> Dict[str, Any]:
    asset=_metals_demo_asset(link.get("asset")); side=_metals_demo_side(link.get("side")); entry=safe_float(link.get("entry_price")); sl=_metals_demo_sl_pct(asset)
    if entry is None or entry<=0: return {"ok":False,"reason":"missing_entry_price","hold_candles":0}
    with get_conn() as conn:
        path=_metals_demo_path(conn,asset,int(link.get("entry_signal_id") or link.get("raw_signal_id") or 0)); latest=_metals_demo_latest_signal_row(conn,asset)
    hold=len(path); current=safe_float(path[-1].get("exec_close")) if path else entry; current_r=_metals_demo_r_from_price(side,entry,current,sl)
    highs=[safe_float(x.get("exec_high")) for x in path]; lows=[safe_float(x.get("exec_low")) for x in path]; highs=[x for x in highs if x is not None]; lows=[x for x in lows if x is not None]
    mfe_price=(max(highs) if highs else current) if side=="long" else (min(lows) if lows else current); mae_price=(min(lows) if lows else current) if side=="long" else (max(highs) if highs else current)
    mfe_r=_metals_demo_r_from_price(side,entry,mfe_price,sl); mae_r=_metals_demo_r_from_price(side,entry,mae_price,sl)
    hwm=max([x for x in [safe_float(link.get("manager_high_water_r")),current_r,mfe_r] if x is not None],default=None); giveback=((hwm-current_r)/hwm*100) if hwm and hwm>0 and current_r is not None and current_r<hwm else 0.0
    fixed_price=safe_float(link.get("fixed_48h_price")); fixed_r=safe_float(link.get("fixed_48h_r"))
    if fixed_r is None and len(path)>=METALS_DEMO_FIXED_HOLD_CANDLES:
        fixed_price=safe_float(path[METALS_DEMO_FIXED_HOLD_CANDLES-1].get("exec_close")); fixed_r=_metals_demo_r_from_price(side,entry,fixed_price,sl)
    raw=_raw_signal_json(latest) if latest else {}
    if side=="long":
        c=cleaned_metal_long_demo_candidate(raw,latest) if latest else {}; support=bool(c.get("demo_candidate")); reversal=bool(_raw_bool_value(raw.get("d_bear")) or (not _raw_bool_value(raw.get("exec_close_gt_ema20")) and not _raw_bool_value(raw.get("ctx_rsi_up"))))
    else:
        c=cleaned_metal_short_demo_candidate(raw,latest) if latest else {}; support=bool(c.get("demo_candidate") or int(c.get("short_watch") or 0)==1); reversal=bool((_raw_bool_value(latest["forward_test_candidate"]) if latest else False) or "obvious_rebound_or_bullish_reclaim" in safe_str(c.get("demo_blockers")))
    return {"ok":True,"asset":asset,"side":side,"entry_price":entry,"sl_pct":sl,"hold_candles":hold,"current_price":current,"current_r":current_r,"mfe_r":mfe_r,"mae_r":mae_r,"high_water_r":hwm,"giveback_pct":giveback,"fixed_48h_price":fixed_price,"fixed_48h_r":fixed_r,"latest_signal_id":int(latest["id"]) if latest else None,"direction_support":support,"adverse_reversal":reversal,"latest_candidate":c}

def _metals_demo_phase(hold: int) -> str:
    if hold<METALS_DEMO_MANAGER_MIN_HOLD_CANDLES: return "PRE_48_MIN_HOLD"
    if hold<72: return "48_71_EARLY_RUNNER"
    if hold<96: return "72_95_RUNNER"
    if hold<120: return "96_119_MATURE_RUNNER"
    return "120_PLUS_LATE_RUNNER"

def _metals_demo_decision(m: Dict[str, Any]) -> Dict[str, Any]:
    h=int(m.get("hold_candles") or 0)
    r=safe_float(m.get("current_r"))
    hwm=safe_float(m.get("high_water_r"))
    gb=safe_float(m.get("giveback_pct"))
    support=bool(m.get("direction_support"))
    reversal=bool(m.get("adverse_reversal"))
    phase=_metals_demo_phase(h)

    if h<METALS_DEMO_MANAGER_MIN_HOLD_CANDLES:
        return {
            "decision":"HOLD_MIN_48",
            "phase":phase,
            "reason":"Normal management locked before 48h; emergency broker SL remains active."
        }

    # Project Exit Plan mature-runner rule:
    # 48h is a minimum/first review, never a forced expiry.
    # Ignore any stale Railway max-hold value; 72/96/120 remain milestones only.
    # This mirrors the no-forced-max behaviour already used by Live Indices.

    # HARD safety exit: a runner that has surrendered almost all a prior move.
    # Candidate support does not override severe giveback, matching the Indices
    # candidate-supported extension rule's too_much_giveback blocker.
    if hwm is not None and hwm>=0.75 and gb is not None and gb>=75 and (r or 0)<=0.10:
        return {
            "decision":"CLOSE_GIVEBACK",
            "phase":phase,
            "reason":f"{gb:.1f}% giveback surrendered most of a profitable move."
        }

    # SOFT post-48 exits are suppressed while the same-direction Metals model
    # is still producing a qualifying candidate.
    if support:
        return {
            "decision":"EXTEND",
            "phase":phase,
            "reason":"candidate_supported_post48_extension_override; same-direction Metals candidate still active."
        }

    if r is not None and r<=-0.75:
        return {
            "decision":"CLOSE_DERIORATED",
            "phase":phase,
            "reason":f"Mature trade {r:.2f}R with directional support absent."
        }

    if hwm is not None and hwm>=1.50 and gb is not None and gb>=65:
        return {
            "decision":"CLOSE_GIVEBACK",
            "phase":phase,
            "reason":f"Runner gave back {gb:.1f}% from {hwm:.2f}R HWM with support absent."
        }

    if reversal and r is not None and r<=0.50:
        return {
            "decision":"CLOSE_REVERSAL",
            "phase":phase,
            "reason":"Opposing structure active and mature trade lacks same-direction candidate support."
        }

    return {
        "decision":"EXTEND",
        "phase":phase,
        "reason":"Trade remains acceptable; review again on next hourly metal signal."
    }

def _metals_demo_protect_fraction(hold: int) -> float:
    if hold>=120: return METALS_DEMO_MANAGER_PROTECT_120
    if hold>=96: return METALS_DEMO_MANAGER_PROTECT_96
    if hold>=72: return METALS_DEMO_MANAGER_PROTECT_72
    return METALS_DEMO_MANAGER_PROTECT_48

def _metals_demo_stop_candidate(link: Dict[str, Any],m: Dict[str, Any]) -> Dict[str, Any]:
    h=int(m.get("hold_candles") or 0); entry=safe_float(link.get("entry_price")); cur=safe_float(m.get("current_price")); r=safe_float(m.get("current_r"))
    if h<METALS_DEMO_MANAGER_MIN_HOLD_CANDLES or entry is None or cur is None or r is None or r<=0: return {"eligible":False,"reason":"not_profitable_or_pre48"}
    side=_metals_demo_side(link.get("side")); f=_metals_demo_protect_fraction(h); raw=entry+(cur-entry)*f if side=="long" else entry-(entry-cur)*f; raw=min(raw,cur*0.9999) if side=="long" else max(raw,cur*1.0001); precision=3 if _metals_demo_asset(link.get("asset"))=="XAUUSD" else 5; stop=round(raw,precision)
    prev=safe_float(link.get("current_stop_price")) or safe_float(link.get("stop_price")); step=entry*METALS_DEMO_MANAGER_MIN_STOP_STEP_PCT/100
    if prev is not None and ((side=="long" and stop<=prev+step) or (side=="short" and stop>=prev-step)): return {"eligible":False,"reason":"would_not_tighten_enough","stop_price":stop}
    return {"eligible":True,"stop_price":stop,"protect_fraction":f,"reason":f"protect {f:.0%} of current favourable move"}

def _metals_demo_update_stop(link: Dict[str, Any],cand: Dict[str, Any]) -> Dict[str, Any]:
    if not cand.get("eligible"): return {"ok":True,"status":"NO_UPDATE","reason":cand.get("reason")}
    resp=metals_demo_request(f"/v3/accounts/{METALS_DEMO_OANDA_ACCOUNT_ID}/trades/{urllib.parse.quote(safe_str(link.get('broker_trade_id')))}/orders","PUT",{"stopLoss":{"timeInForce":"GTC","price":str(cand.get("stop_price"))}})
    if resp.get("ok"):
        with get_conn() as conn: conn.execute("UPDATE metals_demo_trade_links SET updated_at_utc=?,current_stop_price=? WHERE id=?",(now_utc_iso(),cand.get("stop_price"),int(link["id"]))); conn.commit()
        _metals_demo_audit(int(link.get("raw_signal_id") or 0),link.get("asset"),link.get("instrument"),"manager_stop_update","UPDATED",safe_str(cand.get("reason")),preview={"stop_price":cand.get("stop_price")},response=resp,link_id=int(link["id"]),candidate_state="MANAGED")
        return {"ok":True,"status":"UPDATED","stop_price":cand.get("stop_price")}
    _metals_demo_audit(int(link.get("raw_signal_id") or 0),link.get("asset"),link.get("instrument"),"manager_stop_update","FAILED",safe_str(resp.get("error") or "stop update failed"),preview={"stop_price":cand.get("stop_price")},response=resp,link_id=int(link["id"]),candidate_state="MANAGED")
    return {"ok":False,"status":"FAILED","response":resp}

def _metals_demo_queue_close(link: Dict[str, Any],reason: str,signal_id: Any) -> int:
    with get_conn() as conn:
        ex=conn.execute("SELECT * FROM metals_demo_action_queue WHERE link_id=? AND action='CLOSE' AND status IN ('PENDING','RETRY') ORDER BY id DESC LIMIT 1",(int(link["id"]),)).fetchone()
        if ex: conn.execute("UPDATE metals_demo_action_queue SET updated_at_utc=?,reason=?,raw_signal_id=? WHERE id=?",(now_utc_iso(),reason,signal_id,int(ex["id"]))); conn.commit(); return int(ex["id"])
        qid=db_insert_returning_id(conn,"INSERT INTO metals_demo_action_queue (created_at_utc,updated_at_utc,raw_signal_id,link_id,asset,instrument,action,status,reason,attempts,raw_json) VALUES (?,?,?,?,?,?,'CLOSE','PENDING',?,0,?)",(now_utc_iso(),now_utc_iso(),signal_id,int(link["id"]),link.get("asset"),link.get("instrument"),reason,json.dumps({"side":link.get("side"),"manager_version":METALS_DEMO_MANAGER_VERSION}))); conn.commit(); return qid

def _metals_demo_close(link: Dict[str, Any],qid: int) -> Dict[str, Any]:
    last={}
    for attempt in range(1,METALS_DEMO_MANAGER_CLOSE_IMMEDIATE_ATTEMPTS+1):
        last=metals_demo_request(f"/v3/accounts/{METALS_DEMO_OANDA_ACCOUNT_ID}/trades/{urllib.parse.quote(safe_str(link.get('broker_trade_id')))}/close","PUT",{"units":"ALL"})
        if last.get("ok"):
            fill=last.get("data",{}).get("orderFillTransaction") or {}; realized=safe_float(fill.get("pl"))
            with get_conn() as conn:
                q=conn.execute("SELECT reason FROM metals_demo_action_queue WHERE id=?",(qid,)).fetchone(); reason=safe_str(q["reason"] if q else "basket_manager_close")
                conn.execute("UPDATE metals_demo_trade_links SET updated_at_utc=?,status='CLOSED_MANAGER',realized_pl=?,closed_at_utc=?,close_reason=? WHERE id=?",(now_utc_iso(),realized,now_utc_iso(),reason,int(link["id"]))); conn.execute("UPDATE metals_demo_action_queue SET updated_at_utc=?,status='DONE',attempts=attempts+? WHERE id=?",(now_utc_iso(),attempt,qid)); conn.commit()
            _metals_demo_audit(int(link.get("raw_signal_id") or 0),link.get("asset"),link.get("instrument"),"manager_close","CLOSED",reason,response=last,link_id=int(link["id"]),candidate_state="MANAGED")
            return {"ok":True,"status":"CLOSED","realized_pl":realized}
        if attempt<METALS_DEMO_MANAGER_CLOSE_IMMEDIATE_ATTEMPTS and METALS_DEMO_MANAGER_CLOSE_RETRY_SLEEP_SECONDS>0: time.sleep(METALS_DEMO_MANAGER_CLOSE_RETRY_SLEEP_SECONDS)
    with get_conn() as conn: conn.execute("UPDATE metals_demo_action_queue SET updated_at_utc=?,status='RETRY',attempts=attempts+? WHERE id=?",(now_utc_iso(),METALS_DEMO_MANAGER_CLOSE_IMMEDIATE_ATTEMPTS,qid)); conn.commit()
    _metals_demo_audit(int(link.get("raw_signal_id") or 0),link.get("asset"),link.get("instrument"),"manager_close","RETRY",safe_str(last.get("error") or "close failed; persistent retry retained"),response=last,link_id=int(link["id"]),candidate_state="MANAGED")
    return {"ok":False,"status":"RETRY","response":last}


def _metals_demo_find_close_in_transaction_ledger(broker_trade_id: Any) -> Dict[str, Any]:
    """Find broker-authoritative close evidence for one Metals trade ID."""
    tid = safe_str(broker_trade_id)
    if not tid:
        return {"ok": False, "reason": "missing_broker_trade_id"}

    # Ensure the local OANDA transaction ledger is as fresh as possible first.
    try:
        metals_demo_sync_broker_transactions(force=True)
    except Exception:
        pass

    with get_conn() as conn:
        rows = [dict(r) for r in conn.execute("""
            SELECT *
            FROM metals_demo_broker_transactions
            WHERE raw_json LIKE ?
            ORDER BY transaction_time DESC, transaction_id DESC
            LIMIT 100
        """, (f"%{tid}%",)).fetchall()]

    for row in rows:
        try:
            raw = json.loads(safe_str(row.get("raw_json")) or "{}")
        except Exception:
            raw = {}

        # OANDA ORDER_FILL close payload.
        for closed in (raw.get("tradesClosed") or []):
            if safe_str((closed or {}).get("tradeID")) == tid:
                pl = safe_float((closed or {}).get("realizedPL"))
                fin = safe_float((closed or {}).get("financing"))
                return {
                    "ok": True,
                    "source": "transaction_tradesClosed",
                    "transaction_id": row.get("transaction_id"),
                    "closed_at_utc": row.get("transaction_time"),
                    "realized_pl": pl,
                    "financing": fin,
                    "net_realized": (float(pl or 0.0) + float(fin or 0.0)),
                    "close_price": safe_float(raw.get("price")),
                    "raw": raw,
                }

        # Partial/final reduction can also carry close economics.
        reduced = raw.get("tradeReduced") or {}
        if safe_str(reduced.get("tradeID")) == tid:
            pl = safe_float(reduced.get("realizedPL"))
            fin = safe_float(reduced.get("financing"))
            return {
                "ok": True,
                "source": "transaction_tradeReduced",
                "transaction_id": row.get("transaction_id"),
                "closed_at_utc": row.get("transaction_time"),
                "realized_pl": pl,
                "financing": fin,
                "net_realized": (float(pl or 0.0) + float(fin or 0.0)),
                "close_price": safe_float(raw.get("price")),
                "raw": raw,
            }

    return {"ok": False, "reason": "no_trade_level_close_evidence_in_ledger"}


def _metals_demo_mark_link_closed_from_broker(
    link: Dict[str, Any],
    *,
    realized_pl: Any = None,
    financing: Any = None,
    close_price: Any = None,
    closed_at_utc: Any = None,
    close_reason: str = "broker_stop_or_external_close",
    evidence_source: str = "",
    evidence: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    """Close the local link only after broker close evidence exists."""
    now = now_utc_iso()
    closed_at = safe_str(closed_at_utc) or now
    pl = safe_float(realized_pl)
    fin = safe_float(financing)
    px = safe_float(close_price)

    with get_conn() as conn:
        conn.execute("""
            UPDATE metals_demo_trade_links
            SET updated_at_utc=?,
                status='CLOSED_BROKER',
                realized_pl=COALESCE(?, realized_pl),
                last_known_unrealized_pl=0,
                last_known_price=COALESCE(?, last_known_price),
                closed_at_utc=COALESCE(NULLIF(closed_at_utc,''), ?),
                close_reason=?,
                manager_last_decision='CLOSED_BROKER_RECONCILED',
                manager_last_reason=?,
                last_reconciled_at_utc=?
            WHERE id=?
        """, (
            now, pl, px, closed_at, close_reason,
            f"{close_reason}; source={evidence_source or 'broker'}",
            now, int(link["id"]),
        ))
        conn.commit()

    try:
        _metals_demo_audit(
            int(link.get("raw_signal_id") or 0),
            safe_str(link.get("asset")),
            safe_str(link.get("instrument")),
            "broker_close_reconciliation",
            "CLOSED_BROKER",
            f"Local OPEN ghost cleared; broker trade {safe_str(link.get('broker_trade_id'))} confirmed closed via {evidence_source or 'broker'}.",
            response=evidence or {},
            candidate_state="RECONCILIATION",
        )
    except Exception:
        pass

    return {
        "ok": True,
        "status": "CLOSED_BROKER",
        "link_id": link.get("id"),
        "broker_trade_id": link.get("broker_trade_id"),
        "realized_pl": pl,
        "financing": fin,
        "close_price": px,
        "closed_at_utc": closed_at,
        "evidence_source": evidence_source,
    }


def _metals_demo_refresh_closed(link: Dict[str, Any]) -> Dict[str, Any]:
    """
    Reconcile one local OPEN link whose broker trade is absent from /openTrades.
    Never assumes absence means closed without checking broker evidence.
    """
    tid = safe_str(link.get("broker_trade_id"))
    if not tid:
        return {"ok": False, "status": "MISSING_BROKER_TRADE_ID"}

    # First preference: OANDA trade endpoint gives full closed-trade state.
    resp = metals_demo_request(
        f"/v3/accounts/{METALS_DEMO_OANDA_ACCOUNT_ID}/trades/{urllib.parse.quote(tid)}"
    )
    trade = (resp.get("data") or {}).get("trade") if resp.get("ok") else None

    if trade and safe_str(trade.get("state")).upper() == "CLOSED":
        return _metals_demo_mark_link_closed_from_broker(
            link,
            realized_pl=trade.get("realizedPL"),
            financing=trade.get("financing"),
            close_price=trade.get("averageClosePrice") or trade.get("price"),
            closed_at_utc=trade.get("closeTime"),
            close_reason="broker_trade_confirmed_closed",
            evidence_source="oanda_trade_endpoint",
            evidence={"trade": trade},
        )

    # Fallback: exact trade-level close evidence from the OANDA transaction ledger.
    tx = _metals_demo_find_close_in_transaction_ledger(tid)
    if tx.get("ok"):
        return _metals_demo_mark_link_closed_from_broker(
            link,
            realized_pl=tx.get("realized_pl"),
            financing=tx.get("financing"),
            close_price=tx.get("close_price"),
            closed_at_utc=tx.get("closed_at_utc"),
            close_reason="broker_transaction_confirmed_close",
            evidence_source=safe_str(tx.get("source")),
            evidence=tx,
        )

    # Do NOT silently close the row when broker evidence is unavailable.
    return {
        "ok": False,
        "status": "BROKER_NOT_OPEN_UNRESOLVED",
        "broker_trade_id": tid,
        "trade_endpoint": resp,
        "transaction_evidence": tx,
    }

def _metals_demo_snapshot_baskets(review_signal_id: Any=None) -> Dict[str, Any]:
    with get_conn() as conn:
        links=[dict(r) for r in conn.execute("SELECT * FROM metals_demo_trade_links WHERE status='OPEN' ORDER BY id").fetchall()]
    groups={}
    for l in links:
        groups.setdefault((_metals_demo_asset(l.get("asset")),_metals_demo_side(l.get("side"))),[]).append(l)
    snaps=[]
    with get_conn() as conn:
        for (asset,side),items in groups.items():
            rs=[safe_float(x.get("manager_current_r")) for x in items]
            rs=[float(x) for x in rs if x is not None]
            br=sum(rs)
            basket_gbp=sum(
                float(safe_float(x.get("manager_current_r")) or 0.0) *
                float(safe_float(x.get("estimated_risk_amount")) or safe_float(x.get("requested_risk_amount")) or _metals_demo_risk(asset))
                for x in items
            )
            key=f"{asset}:{side.upper()}"
            prev=conn.execute("""SELECT high_water_r,high_water_pnl_gbp,high_water_seen_at,created_at_utc
                                 FROM metals_demo_basket_snapshots WHERE basket_key=?
                                 ORDER BY id DESC LIMIT 1""",(key,)).fetchone()
            old_hwm=float(safe_float(prev["high_water_r"] if prev else None) or 0.0)
            if br>old_hwm:
                hwm=br; hwm_gbp=basket_gbp; hwm_seen=now_utc_iso()
            else:
                hwm=old_hwm
                hwm_gbp=safe_float(prev["high_water_pnl_gbp"] if prev else None)
                if hwm_gbp is None:
                    hwm_gbp=hwm*float(_metals_demo_risk(asset))
                hwm_seen=safe_str(prev["high_water_seen_at"] if prev else "")
                if not hwm_seen and hwm>0 and prev:
                    hwm_seen=safe_str(prev["created_at_utc"])
            gb=((hwm-br)/hwm*100) if hwm>0 and br<hwm else 0
            mature=sum(1 for x in items if int(x.get("manager_last_review_candles") or 0)>=METALS_DEMO_MANAGER_MIN_HOLD_CANDLES)
            losing=sum(1 for x in rs if x<0)
            phase="TINY" if len(items)<METALS_DEMO_BASKET_LIGHT_MIN_OPEN else "EARLY" if len(items)<METALS_DEMO_BASKET_NORMAL_MIN_OPEN else "DEVELOPING" if len(items)<METALS_DEMO_BASKET_MATURE_MIN_OPEN else "MATURE"
            if len(items)<METALS_DEMO_BASKET_LIGHT_MIN_OPEN:
                state,action,reason="OBSERVE","HOLD","Young/small basket: no basket-level trim."
            elif br<=METALS_DEMO_BASKET_SEVERE_LOSS_R and mature:
                state,action,reason="CRITICAL","REDUCE_WEAKEST_50_PERCENT_MATURE_ONLY","Severe asset-side basket loss."
            elif len(items)>=METALS_DEMO_BASKET_NORMAL_MIN_OPEN and br<=METALS_DEMO_BASKET_NORMAL_LOSS_R and mature:
                state,action,reason="RED","REDUCE_WEAKEST_25_PERCENT_MATURE_ONLY","Developed basket loss breached defence level."
            elif br<=METALS_DEMO_BASKET_LIGHT_LOSS_R and mature:
                state,action,reason="AMBER","REDUCE_WEAKEST_10_PERCENT_MATURE_ONLY","Basket loss warning."
            elif gb>=METALS_DEMO_BASKET_GIVEBACK_WARN_PCT and mature and hwm>0:
                state,action,reason="AMBER","PROTECT_OR_REDUCE_WEAKEST_MATURE_ONLY","Basket giveback warning."
            else:
                state,action,reason="GREEN","HOLD","Basket within normal tolerance."
            snap={"scope":"ASSET_SIDE","basket_key":key,"asset":asset,"side":side,"open_count":len(items),
                  "matured_count":mature,"losing_count":losing,"losing_pct":losing/len(rs)*100 if rs else 0,
                  "basket_r":br,"basket_pnl_gbp":basket_gbp,"high_water_r":hwm,"high_water_pnl_gbp":hwm_gbp,
                  "high_water_seen_at":hwm_seen,"giveback_pct":gb,"basket_phase":phase,
                  "state":state,"action":action,"reason":reason}
            conn.execute("""INSERT INTO metals_demo_basket_snapshots
                (created_at_utc,review_signal_id,scope,basket_key,asset,side,open_count,matured_count,losing_count,losing_pct,
                 basket_r,high_water_r,giveback_pct,basket_phase,state,action,reason,raw_json,
                 basket_pnl_gbp,high_water_pnl_gbp,high_water_seen_at)
                 VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                (now_utc_iso(),review_signal_id,snap["scope"],key,asset,side,snap["open_count"],mature,
                 snap["losing_count"],snap["losing_pct"],br,hwm,gb,phase,state,action,reason,
                 json.dumps({"link_ids":[x.get("id") for x in items]}),basket_gbp,hwm_gbp,hwm_seen))
            snaps.append(snap)

        rs=[safe_float(x.get("manager_current_r")) for x in links]
        rs=[float(x) for x in rs if x is not None]
        br=sum(rs)
        basket_gbp=sum(
            float(safe_float(x.get("manager_current_r")) or 0.0) *
            float(safe_float(x.get("estimated_risk_amount")) or safe_float(x.get("requested_risk_amount")) or _metals_demo_risk(x.get("asset")))
            for x in links
        )
        key="METALS_BASKET"
        prev=conn.execute("""SELECT high_water_r,high_water_pnl_gbp,high_water_seen_at,created_at_utc
                             FROM metals_demo_basket_snapshots WHERE basket_key=?
                             ORDER BY id DESC LIMIT 1""",(key,)).fetchone()
        old_hwm=float(safe_float(prev["high_water_r"] if prev else None) or 0.0)
        if br>old_hwm:
            hwm=br; hwm_gbp=basket_gbp; hwm_seen=now_utc_iso()
        else:
            hwm=old_hwm
            hwm_gbp=safe_float(prev["high_water_pnl_gbp"] if prev else None)
            if hwm_gbp is None:
                risk_basis=(
                    sum(float(safe_float(x.get("estimated_risk_amount")) or safe_float(x.get("requested_risk_amount")) or _metals_demo_risk(x.get("asset"))) for x in links)/len(links)
                    if links else (float(METALS_DEMO_XAU_RISK_AMOUNT)+float(METALS_DEMO_XAG_RISK_AMOUNT))/2.0
                )
                hwm_gbp=hwm*risk_basis
            hwm_seen=safe_str(prev["high_water_seen_at"] if prev else "")
            if not hwm_seen and hwm>0 and prev:
                hwm_seen=safe_str(prev["created_at_utc"])
        gb=((hwm-br)/hwm*100) if hwm>0 and br<hwm else 0
        state="RED" if br<=METALS_DEMO_BASKET_SEVERE_LOSS_R else "AMBER" if gb>=METALS_DEMO_BASKET_GIVEBACK_WARN_PCT else "GREEN"
        conn.execute("""INSERT INTO metals_demo_basket_snapshots
            (created_at_utc,review_signal_id,scope,basket_key,asset,side,open_count,matured_count,losing_count,losing_pct,
             basket_r,high_water_r,giveback_pct,basket_phase,state,action,reason,raw_json,
             basket_pnl_gbp,high_water_pnl_gbp,high_water_seen_at)
             VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
            (now_utc_iso(),review_signal_id,"FAMILY",key,"","MIXED",len(links),
             sum(1 for x in links if int(x.get("manager_last_review_candles") or 0)>=METALS_DEMO_MANAGER_MIN_HOLD_CANDLES),
             sum(1 for x in rs if x<0),(sum(1 for x in rs if x<0)/len(rs)*100 if rs else 0),
             br,hwm,gb,"MIXED",state,"ADVISORY_ONLY",
             "Family overlay does not directly close XAU/XAG trades.","{}",
             basket_gbp,hwm_gbp,hwm_seen))
        conn.commit()
        snaps.append({"scope":"FAMILY","basket_key":key,"open_count":len(links),
                      "basket_r":br,"basket_pnl_gbp":basket_gbp,"high_water_r":hwm,
                      "high_water_pnl_gbp":hwm_gbp,"high_water_seen_at":hwm_seen,
                      "giveback_pct":gb,"state":state,"action":"ADVISORY_ONLY"})
    return {"ok":True,"snapshots":snaps}

def _metals_demo_apply_basket_defence(asset: str,signal_id: Any) -> List[Dict[str, Any]]:
    out=[]; asset=_metals_demo_asset(asset)
    with get_conn() as conn: rows=[dict(r) for r in conn.execute("SELECT * FROM metals_demo_basket_snapshots WHERE scope='ASSET_SIDE' AND asset=? ORDER BY id DESC",(asset,)).fetchall()]
    seen=set()
    for s in rows:
        side=_metals_demo_side(s.get("side"))
        if side in seen: continue
        seen.add(side); a=safe_str(s.get("action")).upper(); frac=0.5 if "50_PERCENT" in a else 0.25 if "25_PERCENT" in a else 0.1 if ("10_PERCENT" in a or "PROTECT_OR_REDUCE" in a) else 0
        if frac<=0: continue
        with get_conn() as conn: cands=[dict(r) for r in conn.execute("SELECT * FROM metals_demo_trade_links WHERE status='OPEN' AND asset=? AND LOWER(side)=? AND COALESCE(manager_last_review_candles,0)>=? ORDER BY COALESCE(manager_current_r,-999999),id",(asset,side,METALS_DEMO_MANAGER_MIN_HOLD_CANDLES)).fetchall()]
        n=max(1,int(len(cands)*frac+0.999999)) if cands else 0
        for l in cands[:n]:
            reason=f"asset_basket_defence:{s.get('state')}:{s.get('action')}:{s.get('reason')}"; q=_metals_demo_queue_close(l,reason,signal_id); out.append({"link_id":l["id"],"result":_metals_demo_close(l,q),"reason":reason})
    return out


_METALS_TX_SYNC_LOCK = threading.Lock()
_METALS_TX_SYNC_CACHE = {"at": 0.0, "result": None}

def _metals_runtime_get(conn: Any, key: str, default: str = "") -> str:
    row = conn.execute("SELECT value FROM metals_demo_runtime_state WHERE key=? LIMIT 1", (key,)).fetchone()
    return safe_str(row["value"] if row else "") or default

def _metals_runtime_set(conn: Any, key: str, value: Any) -> None:
    now = now_utc_iso()
    conn.execute("""
        INSERT INTO metals_demo_runtime_state(key,value,updated_at_utc)
        VALUES(?,?,?)
        ON CONFLICT(key) DO UPDATE SET value=excluded.value,updated_at_utc=excluded.updated_at_utc
    """, (key, safe_str(value), now))


