@app.get("/export/metals-research.zip")
def export_metals_research_zip(limit: int = EXPORT_BUNDLE_DEFAULT_LIMIT) -> Response:
    init_db()
    limit = _clean_limit(limit, EXPORT_BUNDLE_DEFAULT_LIMIT)
    zip_buffer = io.BytesIO()
    files: List[str] = []
    with zipfile.ZipFile(zip_buffer, mode="w", compression=zipfile.ZIP_DEFLATED) as zf:
        try:
            snap = build_metals_deep_research_snapshot(limit=limit)
            _write_zip_json(zf, "metals-deep-research-summary.json", snap); files.append("metals-deep-research-summary.json")
        except Exception as e:
            _write_zip_json(zf, "metals-deep-research-summary-error.json", {"error": str(e), "time_utc": now_utc_iso()}); files.append("metals-deep-research-summary-error.json")

        try:
            long_rows = build_metals_research_outcomes(limit=limit, candidates_only=False)
            long_accepted = [r for r in long_rows if int(r.get("candidate") or 0) == 1]
            long_candidate_like = [r for r in long_rows if int(r.get("candidate_like") or 0) == 1]
            _write_zip_csv(zf, "metals-long-outcomes-all.csv", long_rows, ["note"]); files.append("metals-long-outcomes-all.csv")
            _write_zip_csv(zf, "metals-long-outcomes-accepted.csv", long_accepted, ["note"]); files.append("metals-long-outcomes-accepted.csv")
            _write_zip_csv(zf, "metals-long-outcomes-candidate-like.csv", long_candidate_like, ["note"]); files.append("metals-long-outcomes-candidate-like.csv")
            _write_zip_csv(zf, "metals-long-summary.csv", summarise_metal_outcomes(long_rows, candidate_like_only=False), ["asset", "rows"]); files.append("metals-long-summary.csv")
        except Exception as e:
            _write_zip_json(zf, "metals-long-export-error.json", {"error": str(e), "time_utc": now_utc_iso()}); files.append("metals-long-export-error.json")

        try:
            short_rows = build_metals_short_research_outcomes(limit=limit, candidates_only=False)
            short_candidates = [r for r in short_rows if int(r.get("short_candidate") or 0) == 1]
            short_watch = [r for r in short_rows if int(r.get("candidate_like") or 0) == 1]
            _write_zip_csv(zf, "metals-short-outcomes-all.csv", short_rows, ["note"]); files.append("metals-short-outcomes-all.csv")
            _write_zip_csv(zf, "metals-short-outcomes-candidates.csv", short_candidates, ["note"]); files.append("metals-short-outcomes-candidates.csv")
            _write_zip_csv(zf, "metals-short-outcomes-watch.csv", short_watch, ["note"]); files.append("metals-short-outcomes-watch.csv")
            _write_zip_csv(zf, "metals-short-summary.csv", summarise_metal_outcomes(short_rows, candidate_like_only=False), ["asset", "rows"]); files.append("metals-short-summary.csv")
            _write_zip_csv(zf, "metals-short-basket-simulation-48h.csv", build_metal_basket_simulation_summary(short_candidates, milestone=48), ["asset", "simulation_state"]); files.append("metals-short-basket-simulation-48h.csv")
        except Exception as e:
            _write_zip_json(zf, "metals-short-export-error.json", {"error": str(e), "time_utc": now_utc_iso()}); files.append("metals-short-export-error.json")

        try:
            shadow_v2_rows = build_metals_short_shadow_v2_outcomes(limit=limit)
            shadow_v2_candidates = [r for r in shadow_v2_rows if safe_str(r.get("shadow_v2_state")).upper() == "CANDIDATE"]
            shadow_v2_watch = [r for r in shadow_v2_rows if safe_str(r.get("shadow_v2_state")).upper() == "WATCH"]
            shadow_v2_blocked = [r for r in shadow_v2_rows if safe_str(r.get("shadow_v2_state")).upper() == "BLOCKED"]
            shadow_v2_summary = summarise_metals_short_shadow_v2(shadow_v2_rows)
            _write_zip_csv(zf, "metals-short-shadow-v2-all.csv", shadow_v2_rows, ["signal_id", "asset"]); files.append("metals-short-shadow-v2-all.csv")
            _write_zip_csv(zf, "metals-short-shadow-v2-candidates.csv", shadow_v2_candidates, ["signal_id", "asset"]); files.append("metals-short-shadow-v2-candidates.csv")
            _write_zip_csv(zf, "metals-short-shadow-v2-watch.csv", shadow_v2_watch, ["signal_id", "asset"]); files.append("metals-short-shadow-v2-watch.csv")
            _write_zip_csv(zf, "metals-short-shadow-v2-blocked.csv", shadow_v2_blocked, ["signal_id", "asset"]); files.append("metals-short-shadow-v2-blocked.csv")
            _write_zip_csv(zf, "metals-short-shadow-v2-summary.csv", shadow_v2_summary, ["asset", "shadow_v2_state"]); files.append("metals-short-shadow-v2-summary.csv")
            _write_zip_json(zf, "metals-short-shadow-v2-summary.json", {
                "status": "ok", "research_only": True, "model_version": METALS_SHORT_SHADOW_V2_EXPORT_VERSION,
                "row_count": len(shadow_v2_rows), "summary": shadow_v2_summary, "time_utc": now_utc_iso(),
            }); files.append("metals-short-shadow-v2-summary.json")
        except Exception as e:
            _write_zip_json(zf, "metals-short-shadow-v2-export-error.json", {"error": str(e), "time_utc": now_utc_iso()}); files.append("metals-short-shadow-v2-export-error.json")

        try:
            with get_conn() as conn:
                raw_rows = _filtered_raw_signals(conn, ["XAUUSD", "XAU", "XAGUSD", "XAG"], limit)
            _write_zip_csv(zf, "raw-signals-metals.csv", raw_rows, ["id", "pair", "timestamp_readable"]); files.append("raw-signals-metals.csv")
        except Exception as e:
            _write_zip_json(zf, "raw-signals-metals-error.json", {"error": str(e), "time_utc": now_utc_iso()}); files.append("raw-signals-metals-error.json")

        try:
            with get_conn() as conn:
                demo_links = [dict(r) for r in conn.execute("SELECT * FROM metals_demo_trade_links ORDER BY id DESC LIMIT ?", (limit,)).fetchall()]
                demo_audit = [dict(r) for r in conn.execute("SELECT * FROM metals_demo_execution_audit ORDER BY id DESC LIMIT ?", (limit,)).fetchall()]
                demo_manager_reviews = [dict(r) for r in conn.execute("SELECT * FROM metals_demo_manager_reviews ORDER BY id DESC LIMIT ?", (limit,)).fetchall()]
                demo_basket_snapshots = [dict(r) for r in conn.execute("SELECT * FROM metals_demo_basket_snapshots ORDER BY id DESC LIMIT ?", (limit,)).fetchall()]
                demo_action_queue = [dict(r) for r in conn.execute("SELECT * FROM metals_demo_action_queue ORDER BY id DESC LIMIT ?", (limit,)).fetchall()]
                demo_broker_transactions = [dict(r) for r in conn.execute("SELECT * FROM metals_demo_broker_transactions ORDER BY transaction_time DESC LIMIT ?", (limit,)).fetchall()]
                demo_runtime_state = [dict(r) for r in conn.execute("SELECT * FROM metals_demo_runtime_state ORDER BY key").fetchall()]
                try:
                    ensure_metals_hwm_history_table()
                    demo_hwm_events = [dict(r) for r in conn.execute("SELECT * FROM metals_demo_hwm_events ORDER BY id DESC LIMIT ?", (limit,)).fetchall()]
                except Exception:
                    demo_hwm_events = []
                demo_open = [r for r in demo_links if safe_str(r.get("status")).upper() == "OPEN"]
            _write_zip_csv(zf, "metals-demo-broker-links.csv", demo_links, ["id"]); files.append("metals-demo-broker-links.csv")
            _write_zip_csv(zf, "metals-demo-execution-audit.csv", demo_audit, ["id"]); files.append("metals-demo-execution-audit.csv")
            _write_zip_csv(zf, "metals-demo-manager-reviews.csv", demo_manager_reviews, ["id"]); files.append("metals-demo-manager-reviews.csv")
            _write_zip_csv(zf, "metals-demo-basket-snapshots.csv", demo_basket_snapshots, ["id"]); files.append("metals-demo-basket-snapshots.csv")
            _write_zip_csv(zf, "metals-demo-action-queue.csv", demo_action_queue, ["id"]); files.append("metals-demo-action-queue.csv")
            _write_zip_csv(zf, "metals-demo-broker-transactions.csv", demo_broker_transactions, ["transaction_id"]); files.append("metals-demo-broker-transactions.csv")
            _write_zip_csv(zf, "metals-demo-runtime-state.csv", demo_runtime_state, ["key"]); files.append("metals-demo-runtime-state.csv")
            _write_zip_csv(zf, "metals-demo-hwm-events.csv", demo_hwm_events, ["id"]); files.append("metals-demo-hwm-events.csv")
            _write_zip_csv(zf, "metals-demo-open-trades.csv", demo_open, ["id"]); files.append("metals-demo-open-trades.csv")
            _write_zip_json(zf, "metals-demo-summary.json", metals_demo_summary()); files.append("metals-demo-summary.json")
        except Exception as e:
            _write_zip_json(zf, "metals-demo-export-error.json", {"error": str(e), "time_utc": now_utc_iso()}); files.append("metals-demo-export-error.json")

        manifest = _bundle_manifest("metals-research", limit, files, "XAU/XAG research plus isolated practice-account metals demo evidence. No live metals money.")
        _write_zip_json(zf, "manifest.json", manifest)
    return _zip_response(zip_buffer, "metals-research.zip")




