# ============================================================
# MANAGED STOP RESEARCH MODELS
# ============================================================

def _managed_stop_weekend_policy(signal_time: Any = None) -> Tuple[int, str]:
    """Return a simple weekend/gap sensitivity flag for index managed stops.

    Uses UTC timestamps only. This is research guidance, not execution.
    Friday evening through Monday evening should be treated carefully because
    tight broker-side stops can be triggered by Sunday gap noise.
    """
    ts = None
    if signal_time:
        try:
            ts = datetime.fromisoformat(str(signal_time).replace("Z", "+00:00"))
        except Exception:
            ts = None
    if ts is None:
        try:
            ts = datetime.now(timezone.utc)
        except Exception:
            return 0, "normal_weekday"
    wd = ts.weekday()  # Mon=0, Fri=4, Sun=6
    hour = ts.hour
    if wd == 4 and hour >= 18:
        return 1, "friday_pre_weekend_freeze_or_widen_research"
    if wd in (5, 6):
        return 1, "weekend_closed_or_reopen_gap_sensitive"
    if wd == 0 and hour <= 18:
        return 1, "monday_gap_watch_do_not_tighten_blindly"
    return 0, "normal_weekday"


def _stop_price_for_target_pnl(instrument: str, broker_fill: float, current: float, units: float, is_long: bool, target_pnl: float) -> Optional[float]:
    units_abs = abs(float(units or 0.0))
    if units_abs <= 0 or broker_fill <= 0 or current <= 0:
        return None
    if target_pnl < 0:
        return None
    if is_long:
        raw = broker_fill + (target_pnl / units_abs)
        raw = min(raw, current * 0.9999)
    else:
        raw = broker_fill - (target_pnl / units_abs)
        raw = max(raw, current * 1.0001)
    return managed_stop_round_price(instrument, raw)


def managed_stop_research_rows(limit: int = 500) -> List[Dict[str, Any]]:
    """Compare simple managed SL ladders for currently open broker-linked trades.

    This is research-only. It does not update OANDA stops. It gives us a view of
    which stop levels would be proposed by a few robust candidate models, including
    weekend/gap sensitivity.
    """
    init_db()
    limit = max(1, min(int(limit or 500), 5000))
    base_rows = managed_stops_status_rows(limit)
    out: List[Dict[str, Any]] = []

    for r in base_rows:
        instrument = safe_str(r.get("instrument"))
        asset = instrument.replace("_USD", "")
        shadow_trade_id = safe_str(r.get("shadow_trade_id"))
        broker_trade_id = safe_str(r.get("broker_trade_id"))
        side = safe_str(r.get("side")).lower()
        hold = int(safe_float(r.get("hold_candles")) or 0)
        broker_fill = safe_float(r.get("broker_fill_price"))
        current = safe_float(r.get("shadow_current_price"))
        units = safe_float(r.get("filled_units")) or 0.0
        is_long = side in {"buy", "long"} or units > 0
        units_abs = abs(float(units or 0.0))
        previous_stop = safe_float(r.get("previous_stop_price"))

        eligible_base = bool(r.get("eligible")) or hold >= 48
        if broker_fill is None or current is None or broker_fill <= 0 or current <= 0 or units_abs <= 0:
            current_pnl = None
            current_r = None
            profit_points = None
        else:
            profit_points = (current - broker_fill) if is_long else (broker_fill - current)
            current_pnl = profit_points * units_abs
            current_r = current_pnl / 50.0 if current_pnl is not None else None

        weekend_flag, weekend_policy = _managed_stop_weekend_policy()
        profitable = current_pnl is not None and current_pnl > 0

        models: List[Dict[str, Any]] = []
        if hold >= 48:
            # Model 1: simple staged percentage of current broker-side profit.
            if hold >= 120:
                frac = 0.75; stage = "120h_plus"; min_r = 1.5
            elif hold >= 96:
                frac = 0.65; stage = "96h_plus"; min_r = 1.0
            elif hold >= 72:
                frac = 0.50; stage = "72h_plus"; min_r = 0.5
            else:
                frac = 0.25; stage = "48h_plus"; min_r = 0.0
            models.append({"model": "balanced_percent_profit", "stage": stage, "protect_mode": f"{int(frac*100)}pct_current_profit", "target_pnl": (current_pnl or 0.0) * frac})

            # Model 2: fixed R floor ladder, capped by current profit.
            fixed_r = 0.0 if hold < 72 else (0.5 if hold < 96 else (1.0 if hold < 120 else 1.5))
            fixed_target = min((current_pnl or 0.0) * 0.90, fixed_r * 50.0) if profitable else 0.0
            models.append({"model": "fixed_R_floor_ladder", "stage": stage, "protect_mode": f"protect_at_least_{fixed_r:g}R_if_available", "target_pnl": fixed_target})

            # Model 3: aggressive mature-runner protection once 96h+.
            aggr_frac = 0.50 if hold < 96 else (0.80 if hold < 120 else 0.90)
            models.append({"model": "aggressive_mature_runner", "stage": stage, "protect_mode": f"{int(aggr_frac*100)}pct_current_profit", "target_pnl": (current_pnl or 0.0) * aggr_frac})

            # Model 4: weekend-aware version of balanced. It would avoid tightening into gap-sensitive windows.
            weekend_target = 0.0 if weekend_flag else (current_pnl or 0.0) * frac
            models.append({"model": "weekend_gap_aware_balanced", "stage": stage, "protect_mode": "freeze_tightening_in_gap_window" if weekend_flag else f"{int(frac*100)}pct_current_profit", "target_pnl": weekend_target})
        else:
            models.append({"model": "not_eligible_pre_48h", "stage": "pre_48h", "protect_mode": "no_managed_stop_yet", "target_pnl": None})

        for m in models:
            target_pnl = safe_float(m.get("target_pnl"))
            stop_price = None
            protected_pct = None
            reason = ""
            eligible = eligible_base and profitable and target_pnl is not None and target_pnl > 0
            if eligible and broker_fill and current:
                stop_price = _stop_price_for_target_pnl(instrument, float(broker_fill), float(current), float(units), is_long, float(target_pnl))
                if stop_price is not None:
                    if is_long:
                        protected_pct = ((stop_price / float(broker_fill)) - 1.0) * 100.0
                        if previous_stop is not None and stop_price <= previous_stop:
                            reason = "candidate would not tighten existing stop"
                            eligible = False
                    else:
                        protected_pct = ((float(broker_fill) / stop_price) - 1.0) * 100.0
                        if previous_stop is not None and stop_price >= previous_stop:
                            reason = "candidate would not tighten existing stop"
                            eligible = False
            else:
                reason = "not profitable/eligible yet" if hold >= 48 else "pre-48h no managed stop"
            if m.get("model") == "weekend_gap_aware_balanced" and weekend_flag:
                reason = "weekend/gap-sensitive window: research model would freeze or widen instead of tighten"
                eligible = False

            out.append({
                "shadow_trade_id": shadow_trade_id,
                "asset": safe_str(asset),
                "instrument": instrument,
                "broker_trade_id": broker_trade_id,
                "side": side,
                "hold_candles": hold,
                "broker_fill_price": broker_fill,
                "shadow_current_price": current,
                "filled_units": units,
                "current_pnl_approx": round(current_pnl, 4) if current_pnl is not None else None,
                "current_R_approx": round(current_r, 4) if current_r is not None else None,
                "previous_stop_price": previous_stop,
                "is_weekend_sensitive_window": weekend_flag,
                "weekend_policy": weekend_policy,
                "model": m.get("model"),
                "stage": m.get("stage"),
                "protect_mode": m.get("protect_mode"),
                "target_protected_pnl": round(target_pnl, 4) if target_pnl is not None else None,
                "target_protected_R": round((target_pnl or 0.0) / 50.0, 4) if target_pnl is not None else None,
                "stop_price": stop_price,
                "protected_profit_pct": round(protected_pct, 5) if protected_pct is not None else None,
                "eligible": int(bool(eligible)),
                "reason": reason or "research candidate",
            })
    return out


def build_managed_stop_research_dashboard_html() -> str:
    try:
        rows = managed_stop_research_rows(limit=250)
    except Exception as e:
        return f"""
        <details>
            <summary>Managed Stop Research</summary>
            <div class="small">Managed stop research unavailable: {esc(e)}</div>
        </details>
        """
    # Show a compact sample of eligible candidates first.
    eligible = [r for r in rows if r.get("eligible")]
    display_rows = (eligible[:80] if eligible else rows[:80])
    html_rows = ""
    for r in display_rows:
        html_rows += f"""
        <tr>
            <td><code>{esc(r.get('shadow_trade_id'))}</code></td>
            <td>{esc(r.get('asset'))}</td>
            <td>{esc(r.get('hold_candles'))}</td>
            <td>{esc(r.get('model'))}</td>
            <td>{esc(r.get('stage'))}</td>
            <td class="{pnl_class(r.get('current_pnl_approx'))}">{money(r.get('current_pnl_approx'))}</td>
            <td>{esc(round(safe_float(r.get('current_R_approx')) or 0, 2))}R</td>
            <td class="{pnl_class(r.get('target_protected_pnl'))}">{money(r.get('target_protected_pnl'))}</td>
            <td>{esc(round(safe_float(r.get('target_protected_R')) or 0, 2))}R</td>
            <td>{esc(r.get('stop_price'))}</td>
            <td>{esc(r.get('weekend_policy'))}</td>
            <td>{esc(r.get('reason'))}</td>
        </tr>
        """
    if not html_rows:
        html_rows = "<tr><td colspan='12'>No managed stop research rows yet.</td></tr>"
    total_current = sum(float(r.get("current_pnl_approx") or 0.0) for r in rows if r.get("model") == "balanced_percent_profit")
    eligible_count = len(eligible)
    return f"""
    <h2>Managed Stop Research</h2>
    <div class="small">Research-only view comparing broker-side managed SL ladders. This does not update OANDA stops. It helps choose robust hourly post-48h stop movement rules and highlights weekend/gap-sensitive periods where tightening may be dangerous.</div>
    <div class="cards">
        <div class="card"><div class="label">Research Rows</div><div class="value">{len(rows)}</div></div>
        <div class="card"><div class="label">Eligible Stop Candidates</div><div class="value">{eligible_count}</div></div>
        <div class="card"><div class="label">Approx Current Linked Profit</div><div class="value {pnl_class(total_current)}">{money(total_current)}</div></div>
    </div>
    <details>
        <summary>Managed Stop Research Candidates</summary>
        <div class="table-scroll"><table class="compact-table">
            <thead><tr><th>Shadow Trade</th><th>Asset</th><th>Hold</th><th>Model</th><th>Stage</th><th>Current P&L</th><th>Current R</th><th>Protected P&L</th><th>Protected R</th><th>Stop</th><th>Weekend Policy</th><th>Reason</th></tr></thead>
            <tbody>{html_rows}</tbody>
        </table></div>
    </details>
    """


@app.get("/managed-stop-research")
def managed_stop_research(limit: int = 500) -> Dict[str, Any]:
    init_db()
    rows = managed_stop_research_rows(limit=limit)
    return {"status": "ok", "count": len(rows), "managed_stop_research": rows, "time_utc": now_utc_iso()}


@app.get("/export/managed-stop-research.csv")
def export_managed_stop_research_csv(limit: int = 5000) -> Response:
    init_db()
    rows = managed_stop_research_rows(limit=limit)
    fieldnames = list(rows[0].keys()) if rows else [
        "shadow_trade_id", "asset", "instrument", "broker_trade_id", "side", "hold_candles",
        "broker_fill_price", "shadow_current_price", "filled_units", "current_pnl_approx", "current_R_approx",
        "previous_stop_price", "is_weekend_sensitive_window", "weekend_policy", "model", "stage",
        "protect_mode", "target_protected_pnl", "target_protected_R", "stop_price",
        "protected_profit_pct", "eligible", "reason"
    ]
    output = io.StringIO()
    writer = csv.DictWriter(output, fieldnames=fieldnames, extrasaction="ignore")
    writer.writeheader()
    for row in rows:
        writer.writerow(row)
    return Response(content=output.getvalue(), media_type="text/csv", headers={"Content-Disposition": 'attachment; filename="managed-stop-research.csv"'})

