def index_protection_stage_state(limit: int = 5000) -> Dict[str, Any]:
    init_db()
    limit = max(1, min(int(limit or 5000), 20000))
    with get_conn() as conn:
        cycle_id = _runtime_setting_from_conn(conn, "index_protection_cycle_id", "")
        stages = [dict(r) for r in conn.execute("SELECT * FROM index_protection_stages ORDER BY id DESC LIMIT ?", (limit,)).fetchall()]
        cohorts = [dict(r) for r in conn.execute("SELECT * FROM index_protection_cohort_trades ORDER BY id DESC LIMIT ?", (limit,)).fetchall()]
        runtime_keys = [
            "index_protection_cycle_id", "index_protection_high_water_R",
            "index_protection_high_water_pnl", "index_protection_high_water_seen_at",
            "index_protection_last_current_R", "index_protection_last_current_pnl",
            "index_protection_last_open_count", "index_protection_last_updated_at",
        ]
        runtime = {key: _runtime_setting_from_conn(conn, key, "") for key in runtime_keys}
    return {
        "status": "ok", "policy_version": INDEX_PROTECTION_POLICY_VERSION,
        "active_cycle_id": cycle_id, "runtime_state": runtime,
        "stages": stages, "cohort_trades": cohorts,
        "time_utc": now_utc_iso(),
    }


