# ============================================================
# v7.4 TEST-ONLY SIMULATED SHADOW CLOSE HARNESS
# ============================================================
# Purpose:
# - Test broker auto-close behaviour without altering real Railway shadow-trade research rows.
# - Lets us simulate that a linked shadow trade has closed, then close the corresponding
#   OANDA live account broker trade and reconcile the broker link.
# - Practice/live-controlled. Obeys the normal broker close safety gates.


def _latest_active_broker_link_for_shadow_trade(shadow_trade_id: str) -> Optional[Dict[str, Any]]:
    shadow_trade_id = safe_str(shadow_trade_id)
    if not shadow_trade_id:
        return None
    with get_conn() as conn:
        row = conn.execute("""
            SELECT *
            FROM broker_trade_links
            WHERE shadow_trade_id = ?
              AND status NOT IN ('CLOSED_OR_NOT_OPEN','CANCELLED','ERROR')
            ORDER BY id DESC
            LIMIT 1
        """, (shadow_trade_id,)).fetchone()
    return dict(row) if row else None


def _execute_simulated_shadow_close_for_link(link: Dict[str, Any], reason: str = "simulated_shadow_close_test") -> Dict[str, Any]:
    """Close one linked OANDA trade for test purposes only, without changing open_trades."""
    can_close, close_reason = broker_shadow_auto_can_close()
    if not can_close:
        return {
            "ok": False,
            "blocked": True,
            "reason": close_reason,
            "broker_trade_link": link,
            "auto_status": broker_shadow_auto_status(),
            "time_utc": now_utc_iso(),
        }

    link_id = int(link.get("id") or 0)
    broker_trade_id = safe_str(link.get("broker_trade_id") or "")
    shadow_trade_id = safe_str(link.get("shadow_trade_id") or "")
    instrument = normalise_oanda_instrument(link.get("instrument") or "")
    side = safe_str(link.get("side") or "")

    if not broker_trade_id:
        return {"ok": False, "error": "broker trade link has no broker_trade_id", "broker_trade_link": link, "time_utc": now_utc_iso()}

    # Create an auditable queue item first, so this follows the same intent -> execution pattern
    # as the real queued close workflow. It is immediately executed by this test harness.
    preview = {
        "ok": True,
        "action": "simulate_shadow_close",
        "broker_trade_link_id": link_id,
        "shadow_trade_id": shadow_trade_id,
        "instrument": instrument,
        "side": side,
        "broker_trade_id": broker_trade_id,
        "close_units": "ALL",
        "test_only": True,
        "does_not_modify_shadow_trade": True,
        "reason": safe_str(reason),
    }
    qid = create_broker_action_queue_item(
        action="close_linked_trade",
        instrument=instrument,
        side=side,
        shadow_trade_id=shadow_trade_id,
        shadow_asset=safe_str(link.get("shadow_asset") or ""),
        family=get_basket_family(safe_str(link.get("shadow_asset") or "")),
        requested_units=safe_float(link.get("last_known_units")) or safe_float(link.get("filled_units")),
        reason=safe_str(reason),
        preview=preview,
        mode="shadow_demo_auto",
        source="simulate_shadow_close_test",
        status="QUEUED_SIMULATED_SHADOW_CLOSE",
        notes="Test-only simulated shadow close. Does not alter open_trades; closes linked OANDA live account trade only.",
    )
    with get_conn() as conn:
        conn.execute("UPDATE broker_action_queue SET broker_trade_link_id = ? WHERE id = ?", (link_id, qid))
        conn.commit()

    close_body = {"units": "ALL"}
    resp = oanda_write_request(f"/v3/accounts/{OANDA_ACCOUNT_ID}/trades/{urllib.parse.quote(broker_trade_id)}/close", "PUT", close_body)
    details = extract_oanda_execution_details(resp)
    broker_order_id = details.get("broker_order_id") or extract_transaction_id(resp)
    success = bool(resp.get("ok"))

    audit_id = log_execution_audit_event(
        "shadow_demo_auto", instrument, shadow_trade_id, "simulate_shadow_close_execute",
        success, f"test-only simulated shadow close for linked broker trade {broker_trade_id}; queue {qid}", broker_order_id,
        raw={"queue_id": qid, "broker_trade_link": link, "request": close_body, "response": resp, "reason": safe_str(reason)},
        side=side, close_units=details.get("closed_units"), actual_price=details.get("actual_price"),
        broker_trade_id=broker_trade_id, response_status_code=details.get("response_status_code"),
    )

    if success:
        now_closed = now_utc_iso()
        with get_conn() as conn:
            conn.execute("""
                UPDATE broker_trade_links
                SET updated_at_utc = ?, status = 'CLOSE_SENT',
                    closed_at_utc = COALESCE(NULLIF(closed_at_utc,''), ?),
                    last_reconciled_at_utc = ?,
                    notes = ?
                WHERE id = ?
            """, (now_closed, now_closed, now_closed, f"Simulated shadow close sent from queue id {qid}. Test-only; open_trades unchanged.", link_id))
            conn.commit()
        update_broker_action_queue_status(qid, "EXECUTED", "Simulated shadow close executed", audit_id, link_id)
    else:
        update_broker_action_queue_status(qid, "EXECUTION_FAILED", safe_str(resp.get("error") or resp.get("text") or "OANDA close failed"), audit_id, link_id)

    reconcile_result = reconcile_broker_trade_links() if success else None

    return {
        "ok": success,
        "queue_id": qid,
        "audit_id": audit_id,
        "broker_trade_link_id": link_id,
        "shadow_trade_id": shadow_trade_id,
        "broker_trade_id": broker_trade_id,
        "instrument": instrument,
        "request": close_body,
        "response": resp,
        "reconcile_result": reconcile_result,
        "note": "Test-only simulated shadow close. The Railway open_trades row is not modified.",
        "time_utc": now_utc_iso(),
    }


@app.post("/broker/oanda/test/simulate-shadow-close")
async def broker_oanda_test_simulate_shadow_close(request: Request) -> Dict[str, Any]:
    """Test-only: close the OANDA broker trade linked to a shadow trade without altering shadow data."""
    init_db()
    try:
        payload = await request.json()
    except Exception:
        payload = {}

    shadow_trade_id = safe_str(payload.get("shadow_trade_id") or "")
    reason = safe_str(payload.get("reason") or "manual simulated shadow close test")

    if not shadow_trade_id:
        raise HTTPException(status_code=400, detail="shadow_trade_id is required")

    link = _latest_active_broker_link_for_shadow_trade(shadow_trade_id)
    if not link:
        raise HTTPException(status_code=404, detail=f"No active broker link found for shadow_trade_id {shadow_trade_id}")

    result = _execute_simulated_shadow_close_for_link(link, reason=reason)
    return {"status": "ok" if result.get("ok") else "error", "result": result, "time_utc": now_utc_iso()}


@app.post("/broker/oanda/test/simulate-multi-shadow-close")
async def broker_oanda_test_simulate_multi_shadow_close(request: Request) -> Dict[str, Any]:
    """Test-only: simulate closes for multiple linked shadow trades, or latest open links if no IDs supplied."""
    init_db()
    try:
        payload = await request.json()
    except Exception:
        payload = {}

    reason = safe_str(payload.get("reason") or "manual multi simulated shadow close test")
    supplied = payload.get("shadow_trade_ids") or payload.get("shadow_trade_id") or []
    if isinstance(supplied, str):
        shadow_trade_ids = [x.strip() for x in supplied.split(",") if x.strip()]
    else:
        shadow_trade_ids = [safe_str(x) for x in supplied if safe_str(x)] if isinstance(supplied, list) else []

    try:
        limit = int(payload.get("limit") or 3)
    except Exception:
        limit = 3
    limit = max(1, min(limit, 25))

    links: List[Dict[str, Any]] = []
    if shadow_trade_ids:
        seen = set()
        for stid in shadow_trade_ids:
            if stid in seen:
                continue
            seen.add(stid)
            link = _latest_active_broker_link_for_shadow_trade(stid)
            if link:
                links.append(link)
            else:
                links.append({"missing": True, "shadow_trade_id": stid})
    else:
        with get_conn() as conn:
            rows = conn.execute("""
                SELECT *
                FROM broker_trade_links
                WHERE mode = 'shadow_demo_auto'
                  AND status NOT IN ('CLOSED_OR_NOT_OPEN','CANCELLED','ERROR')
                ORDER BY id ASC
                LIMIT ?
            """, (limit,)).fetchall()
        links = [dict(r) for r in rows]

    results: List[Dict[str, Any]] = []
    closed_count = 0
    for link in links[:limit]:
        if link.get("missing"):
            results.append({"ok": False, "skipped": True, "reason": "no active broker link found", "shadow_trade_id": link.get("shadow_trade_id")})
            continue
        res = _execute_simulated_shadow_close_for_link(link, reason=reason)
        if res.get("ok"):
            closed_count += 1
        results.append(res)

    health = broker_reconciliation_health() if 'broker_reconciliation_health' in globals() else None
    return {
        "status": "ok",
        "ok": True,
        "requested_count": len(shadow_trade_ids) if shadow_trade_ids else len(links),
        "processed_count": len(results),
        "closed_count": closed_count,
        "results": results,
        "reconciliation_health": health,
        "note": "Test-only simulated close. No open_trades or strategy research rows were modified.",
        "time_utc": now_utc_iso(),
    }

# ============================================================
# v8.9 - OANDA managed stop-loss research harness
