def _metals_standard_latest_family_snapshot() -> Dict[str, Any]:
    init_db()
    with get_conn() as conn:
        row = conn.execute("""
            SELECT *
            FROM metals_demo_basket_snapshots
            WHERE basket_key='METALS_BASKET'
            ORDER BY id DESC
            LIMIT 1
        """).fetchone()
    return dict(row) if row else {}



def metals_demo_live_broker_snapshot() -> Dict[str, Any]:
    """
    Fresh read-only OANDA practice snapshot filtered strictly to XAU_USD/XAG_USD.
    Shared account NAV remains account-level; all trade/P&L metrics here are metals-only.
    """
    cfg = metals_demo_config_status()
    acct = {}
    if cfg.get("missing"):
        return {
            "ok": False, "account": {}, "owned_open_trades": [],
            "owned_open_count": 0, "owned_unrealized_pl": 0.0,
            "owned_margin_used": 0.0, "account_open_count": 0,
            "error": "metals_demo_credentials_missing",
        }

    try:
        acc_resp = metals_demo_request(
            f"/v3/accounts/{METALS_DEMO_OANDA_ACCOUNT_ID}/summary", "GET"
        )
        if acc_resp.get("ok"):
            raw = acc_resp.get("data") or {}
            acct = raw.get("account") or raw
    except Exception:
        acct = {}

    resp = metals_demo_request(
        f"/v3/accounts/{METALS_DEMO_OANDA_ACCOUNT_ID}/openTrades", "GET"
    )
    if not resp.get("ok"):
        return {
            "ok": False, "account": acct, "owned_open_trades": [],
            "owned_open_count": 0, "owned_unrealized_pl": 0.0,
            "owned_margin_used": 0.0, "account_open_count": 0,
            "error": resp.get("error"),
        }

    all_trades = (resp.get("data") or {}).get("trades", []) or []
    allowed = {"XAU_USD", "XAG_USD"}
    owned = [
        t for t in all_trades
        if safe_str(t.get("instrument")).upper() in allowed
    ]
    return {
        "ok": True,
        "account": acct,
        "owned_open_trades": owned,
        "owned_open_count": len(owned),
        "owned_unrealized_pl": sum(
            float(safe_float(t.get("unrealizedPL")) or 0.0) for t in owned
        ),
        "owned_margin_used": sum(
            float(safe_float(t.get("marginUsed")) or 0.0) for t in owned
        ),
        "account_open_count": len(all_trades),
        "time_utc": now_utc_iso(),
    }


def _metals_broker_basket_r(broker: Dict[str, Any]) -> Dict[str, Any]:
    """
    Reconstruct current Metals basket R from actual OANDA UPL and each
    linked trade's effective GBP risk. This makes the top-level R/HWM
    broker-aware even before the local hourly manager has reviewed a trade.
    """
    owned = broker.get("owned_open_trades") or []
    broker_by_id = {safe_str(t.get("id")): t for t in owned}

    with get_conn() as conn:
        links = [dict(r) for r in conn.execute("""
            SELECT * FROM metals_demo_trade_links
            WHERE status='OPEN'
            ORDER BY id
        """).fetchall()]

    total_r = 0.0
    linked = 0
    unlinked = 0
    details = []

    for link in links:
        bid = safe_str(link.get("broker_trade_id"))
        bt = broker_by_id.get(bid)
        if not bt:
            continue

        upl = float(safe_float(bt.get("unrealizedPL")) or 0.0)
        risk = (
            safe_float(link.get("estimated_risk_amount"))
            or safe_float(link.get("requested_risk_amount"))
            or _metals_demo_risk(link.get("asset"))
        )
        risk = float(risk or 0.0)
        rr = (upl / risk) if risk > 0 else 0.0
        total_r += rr
        linked += 1
        details.append({
            "local_id": link.get("id"),
            "broker_trade_id": bid,
            "asset": link.get("asset"),
            "upl_gbp": upl,
            "effective_risk_gbp": risk,
            "broker_r": rr,
        })

    # If an OANDA Metals trade is genuinely broker-only, we cannot safely
    # manufacture an R value without its original risk basis. Cash HWM remains
    # exact; R HWM uses linked trades only and flags the discrepancy.
    linked_ids = {safe_str(x.get("broker_trade_id")) for x in links}
    unlinked = sum(1 for t in owned if safe_str(t.get("id")) not in linked_ids)

    return {
        "basket_r": total_r,
        "linked_count": linked,
        "unlinked_broker_count": unlinked,
        "details": details,
    }


def _metals_broker_highwater_state(broker: Dict[str, Any]) -> Dict[str, Any]:
    """
    Persistent broker-authoritative Metals high-water.

    v1.6.9 continuity rules:
      - a failed/partial OANDA read can NEVER reset HWM;
      - HWM resets only after a successful broker read proves XAU/XAG open-count=0;
      - while a basket is active HWM is monotonic;
      - stored family/manager evidence can repair an accidentally lowered runtime HWM;
      - timestamps use OANDA quote / latest signal market time, not deploy wall-clock;
      - optional operator recovery floor is explicit and defaults to zero.
    """
    ensure_metals_hwm_history_table()

    broker_ok = bool(broker.get("ok"))
    current_gbp = float(safe_float(broker.get("owned_unrealized_pl")) or 0.0)
    open_count = int(broker.get("owned_open_count") or 0)

    with get_conn() as conn:
        old_open = int(safe_float(_metals_runtime_get(conn, "broker_hwm_open_count", "0")) or 0)
        old_hwm_gbp = float(safe_float(_metals_runtime_get(conn, "broker_hwm_gbp", "0")) or 0.0)
        old_hwm_r = float(safe_float(_metals_runtime_get(conn, "broker_hwm_r", "0")) or 0.0)
        old_seen = _metals_runtime_get(conn, "broker_hwm_seen_at", "")
        old_source = _metals_runtime_get(conn, "broker_hwm_source", "legacy_runtime_state")

        # Never treat an API failure as a flat basket.
        if not broker_ok:
            return {
                "current_gbp": current_gbp,
                "current_r": 0.0,
                "high_water_gbp": old_hwm_gbp,
                "high_water_r": old_hwm_r,
                "high_water_seen_at": old_seen,
                "giveback_gbp": max(0.0, old_hwm_gbp - current_gbp),
                "giveback_r": 0.0,
                "giveback_pct": (
                    max(0.0, old_hwm_gbp - current_gbp) / old_hwm_gbp * 100.0
                    if old_hwm_gbp > 0 else 0.0
                ),
                "open_count": old_open,
                "linked_r_count": 0,
                "unlinked_broker_count": 0,
                "r_details": [],
                "source": old_source or "stored_state_broker_read_failed",
                "broker_read_ok": False,
                "historical_repair": False,
            }

        r_state = _metals_broker_basket_r(broker)
        current_r = float(safe_float(r_state.get("basket_r")) or 0.0)
        observed_at = _metals_hwm_observation_time(conn)

        # Only a successful broker read proving flat may reset the cycle.
        if open_count == 0:
            if old_open > 0 or old_hwm_gbp > 0 or old_hwm_r > 0:
                _record_metals_hwm_event(
                    conn, "FLAT_RESET", observed_at, 0, 0.0, 0.0, 0.0, 0.0,
                    "successful_oanda_flat",
                    {"previous_hwm_gbp": old_hwm_gbp, "previous_hwm_r": old_hwm_r},
                )
            _metals_runtime_set(conn, "broker_hwm_open_count", 0)
            _metals_runtime_set(conn, "broker_hwm_gbp", 0.0)
            _metals_runtime_set(conn, "broker_hwm_r", 0.0)
            _metals_runtime_set(conn, "broker_hwm_seen_at", "")
            _metals_runtime_set(conn, "broker_hwm_source", "successful_oanda_flat")
            conn.commit()
            return {
                "current_gbp": 0.0, "current_r": 0.0,
                "high_water_gbp": 0.0, "high_water_r": 0.0,
                "high_water_seen_at": "",
                "giveback_gbp": 0.0, "giveback_r": 0.0,
                "giveback_pct": 0.0,
                "open_count": 0,
                "linked_r_count": r_state.get("linked_count", 0),
                "unlinked_broker_count": r_state.get("unlinked_broker_count", 0),
                "r_details": r_state.get("details", []),
                "source": "successful_oanda_flat",
                "broker_read_ok": True,
                "historical_repair": False,
            }

        evidence = _metals_hwm_recovery_evidence(conn)
        best = evidence.get("best") or {}
        evidence_gbp = float(safe_float(best.get("gbp")) or 0.0)
        evidence_r = float(safe_float(best.get("r")) or 0.0)
        evidence_seen = safe_str(best.get("seen_at"))
        evidence_source = safe_str(best.get("source"))

        hwm_gbp = max(old_hwm_gbp, current_gbp, evidence_gbp)
        hwm_r = max(old_hwm_r, current_r, evidence_r)
        seen = old_seen
        source = old_source or "legacy_runtime_state"
        historical_repair = False

        if evidence_gbp > max(old_hwm_gbp, current_gbp) + 0.005:
            seen = evidence_seen or observed_at
            source = f"historical_repair:{evidence_source}"
            historical_repair = True
        elif current_gbp > old_hwm_gbp + 0.005 and current_gbp >= evidence_gbp:
            seen = observed_at
            source = "broker_cash_new_high"
        elif not seen and hwm_gbp > 0:
            seen = evidence_seen or observed_at
            source = evidence_source or "active_basket_seed"

        # Repair an impossible post-market timestamp created by a deployment
        # without ever lowering the cash HWM.
        latest_signal_seen = _metals_latest_signal_observation_time(conn)
        old_seen_dt = parse_dt(seen)
        last_signal_dt = parse_dt(latest_signal_seen)
        timestamp_repaired = False
        if (
            old_seen_dt is not None
            and last_signal_dt is not None
            and old_seen_dt > last_signal_dt + timedelta(hours=2)
        ):
            market = _metals_demo_market_state()
            quote_dt = parse_dt(market.get("latest_price_time"))
            cap_dt = quote_dt or last_signal_dt
            if cap_dt is not None and old_seen_dt > cap_dt + timedelta(hours=2):
                seen = safe_str(market.get("latest_price_time")) or latest_signal_seen
                source = source + ":timestamp_repaired"
                timestamp_repaired = True

        previous_gbp = old_hwm_gbp
        previous_seen = old_seen
        _metals_runtime_set(conn, "broker_hwm_open_count", open_count)
        _metals_runtime_set(conn, "broker_hwm_gbp", hwm_gbp)
        _metals_runtime_set(conn, "broker_hwm_r", hwm_r)
        _metals_runtime_set(conn, "broker_hwm_seen_at", seen)
        _metals_runtime_set(conn, "broker_hwm_source", source)

        if historical_repair:
            _record_metals_hwm_event(
                conn, "HISTORICAL_REPAIR", seen, open_count,
                current_gbp, current_r, hwm_gbp, hwm_r, source,
                {"previous_hwm_gbp": previous_gbp, "evidence": evidence},
            )
        elif current_gbp > previous_gbp + 0.005:
            _record_metals_hwm_event(
                conn, "NEW_HIGH", seen, open_count,
                current_gbp, current_r, hwm_gbp, hwm_r, source,
            )
        elif timestamp_repaired and previous_seen != seen:
            _record_metals_hwm_event(
                conn, "TIMESTAMP_REPAIR", seen, open_count,
                current_gbp, current_r, hwm_gbp, hwm_r, source,
                {"previous_seen_at": previous_seen},
            )
        conn.commit()

    giveback_gbp = max(0.0, hwm_gbp - current_gbp)
    giveback_r = max(0.0, hwm_r - current_r)
    giveback_pct = (giveback_gbp / hwm_gbp * 100.0) if hwm_gbp > 0 else 0.0

    return {
        "current_gbp": current_gbp,
        "current_r": current_r,
        "high_water_gbp": hwm_gbp,
        "high_water_r": hwm_r,
        "high_water_seen_at": seen,
        "giveback_gbp": giveback_gbp,
        "giveback_r": giveback_r,
        "giveback_pct": giveback_pct,
        "open_count": open_count,
        "linked_r_count": r_state.get("linked_count", 0),
        "unlinked_broker_count": r_state.get("unlinked_broker_count", 0),
        "r_details": r_state.get("details", []),
        "source": source,
        "broker_read_ok": True,
        "historical_repair": historical_repair,
        "historical_evidence": evidence,
    }


def _metals_trade_age_hours(link: Dict[str, Any], broker_trade: Optional[Dict[str, Any]] = None) -> int:
    """
    True wall-clock age of an open Metals trade.

    Priority:
      1) OANDA broker openTime (authoritative when linked)
      2) local signal_time
      3) local created_at_utc
      4) manager_last_review_candles only as a final fallback

    This prevents young/mature counts and 'Oldest' from staying at 0h merely
    because the hourly manager has not yet written a review row.
    """
    candidates = []
    if broker_trade:
        candidates.append(broker_trade.get("openTime"))
    candidates.extend([
        link.get("signal_time"),
        link.get("created_at_utc"),
    ])

    now = now_utc()
    for raw in candidates:
        dt = parse_dt(raw)
        if dt is None:
            continue
        try:
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=timezone.utc)
            hours = int(max(0.0, (now - dt.astimezone(timezone.utc)).total_seconds() / 3600.0))
            return hours
        except Exception:
            continue

    return int(safe_float(link.get("manager_last_review_candles")) or 0)


def _metals_standard_top_uncached() -> Dict[str, Any]:
    snap = metals_demo_summary()
    cfg = snap.get("config") or {}
    family = _metals_standard_latest_family_snapshot()
    broker = metals_demo_live_broker_snapshot()
    acct = broker.get("account") or {}

    open_trades = snap.get("open_trades") or []
    broker_by_id = {
        safe_str(t.get("id")): t
        for t in (broker.get("owned_open_trades") or [])
    }
    open_trade_ages = [
        _metals_trade_age_hours(
            r,
            broker_by_id.get(safe_str(r.get("broker_trade_id")))
        )
        for r in open_trades
    ]
    mature = sum(
        1 for age in open_trade_ages
        if age >= int(METALS_DEMO_MANAGER_MIN_HOLD_CANDLES)
    )
    oldest = max(open_trade_ages or [0])

    latest = snap.get("latest") or {}
    signal_count = sum(
        1 for a in ("XAUUSD", "XAGUSD")
        if (latest.get(a) or {}).get("raw_signal_id")
    )
    candidate_count = sum(
        1 for a in ("XAUUSD", "XAGUSD")
        if safe_str(
            ((latest.get(a) or {}).get("selected_demo_candidate") or {}).get("demo_state")
        ).upper() in ("CANDIDATE", "ACCEPTED", "TRUE")
    )

    # Top-level HWM / Giveback is broker-authoritative and updates on every
    # dashboard refresh, not only after a local manager review.
    broker_hwm = _metals_broker_highwater_state(broker)
    basket_r = float(safe_float(broker_hwm.get("current_r")) or 0.0)
    hwm_r = float(safe_float(broker_hwm.get("high_water_r")) or 0.0)
    hwm_gbp = float(safe_float(broker_hwm.get("high_water_gbp")) or 0.0)
    hwm_time = safe_str(broker_hwm.get("high_water_seen_at"))
    giveback_pct = float(safe_float(broker_hwm.get("giveback_pct")) or 0.0)
    giveback_r = float(safe_float(broker_hwm.get("giveback_r")) or 0.0)
    giveback_gbp = float(safe_float(broker_hwm.get("giveback_gbp")) or 0.0)

    broker_open_pnl = safe_float(broker.get("owned_unrealized_pl")) or 0.0
    realized_pnl = safe_float(snap.get("actual_realized_pnl")) or 0.0

    now = now_utc()
    week_start = (now - timedelta(days=now.weekday())).replace(
        hour=0, minute=0, second=0, microsecond=0
    )
    month_start = now.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
    with get_conn() as conn:
        wk = conn.execute(
            """SELECT COALESCE(SUM(realized_pl),0) AS p
               FROM metals_demo_trade_links
               WHERE closed_at_utc>=?""",
            (week_start.isoformat(),)
        ).fetchone()
        mo = conn.execute(
            """SELECT COALESCE(SUM(realized_pl),0) AS p
               FROM metals_demo_trade_links
               WHERE closed_at_utc>=?""",
            (month_start.isoformat(),)
        ).fetchone()

    return {
        "status": "ok",
        "project": "METALS",
        "mode": "OANDA PRACTICE",
        "reporting_currency": "GBP",
        "time_utc": now_utc_iso(),
        "account": {
            "nav": safe_float(acct.get("NAV")),
            "balance": safe_float(acct.get("balance")),
            "unrealized_pl": safe_float(acct.get("unrealizedPL")),
            "margin_available": safe_float(acct.get("marginAvailable")),
            "currency": safe_str(acct.get("currency") or cfg.get("oanda_account_currency")),
            "gbp_verified": bool(cfg.get("gbp_account_verified")),
        },
        "accounting": {
            "week_pnl": safe_float(wk["p"] if wk else 0) or 0.0,
            "week_label": "Realised this week",
            "month_pnl": safe_float(mo["p"] if mo else 0) or 0.0,
            "month_label": "Realised this month",
        },
        "strategy": {
            "open_pnl": broker_open_pnl,
            "headline_pnl": broker_open_pnl,
            "model_open_pnl": safe_float(snap.get("actual_open_pnl")) or 0.0,
            "realized_pnl": realized_pnl,
            "total_pnl": broker_open_pnl + realized_pnl,
            "open_trades": int(broker.get("owned_open_count") or 0),
            "local_open_trades": int(snap.get("open_trade_count") or 0),
            "open_long": int(snap.get("open_long_count") or 0),
            "open_short": int(snap.get("open_short_count") or 0),
            "mature_48h_plus": mature,
            "oldest_hold": oldest,
            "basket_r": basket_r,
            "high_water_r": hwm_r,
            "high_water_gbp": hwm_gbp,
            "high_water_time": hwm_time,
            "giveback_r": giveback_r,
            "giveback_gbp": giveback_gbp,
            "giveback_pct": giveback_pct,
            "high_water_source": safe_str(broker_hwm.get("source") or "OANDA_XAU_XAG_OPEN_PNL"),
            "high_water_historical_repair": bool(broker_hwm.get("historical_repair")),
            "high_water_broker_read_ok": bool(broker_hwm.get("broker_read_ok", True)),
            "broker_r_linked_count": int(broker_hwm.get("linked_r_count") or 0),
            "broker_r_unlinked_count": int(broker_hwm.get("unlinked_broker_count") or 0),
            "basket_state": safe_str(
                family.get("state") or ("FLAT" if not open_trades else "GREEN")
            ),
            "manager_enabled": bool(cfg.get("basket_manager_enabled")),
            "orders_allowed": bool(cfg.get("orders_allowed")),
            "broker_margin_used": safe_float(broker.get("owned_margin_used")) or 0.0,
            "broker_account_open_count": int(broker.get("account_open_count") or 0),
            "manager_worker": metals_demo_manager_worker_status(),
            "risk_visibility": snap.get("risk_visibility") or {},
        },
        "signals": {
            "received_assets": signal_count,
            "expected_assets": 2,
            "candidate_assets": candidate_count,
            "latest": latest,
        },
        "research": {
            "fixed_48h_rows": int(snap.get("fixed_48h_baseline_rows") or 0),
            "fixed_48h_total_r": safe_float(snap.get("fixed_48h_baseline_total_R")) or 0.0,
        },
    }

def metals_standard_top_snapshot(force: bool = False) -> Dict[str, Any]:
    ts = time.time()
    with _METALS_STD_TOP_LOCK:
        if (
            not force
            and _METALS_STD_TOP_CACHE.get("payload") is not None
            and float(_METALS_STD_TOP_CACHE.get("expires_at") or 0.0) > ts
        ):
            out = dict(_METALS_STD_TOP_CACHE["payload"])
            out["cached"] = True
            return out
    out = _metals_standard_top_uncached()
    with _METALS_STD_TOP_LOCK:
        _METALS_STD_TOP_CACHE["payload"] = dict(out)
        _METALS_STD_TOP_CACHE["expires_at"] = ts + METALS_STANDARD_TOP_CACHE_SECONDS
    out["cached"] = False
    return out


@app.get("/dashboard/top")
def metals_standard_top_route(force: bool = False) -> Dict[str, Any]:
    return metals_standard_top_snapshot(force=force)


